// Tokenizer and keyword tables of the Logomocja dialect.

export type Mode = '2d' | '3d';

export class LogoError extends Error {
  line: number;
  column: number;
  runtime: boolean;
  constructor(message: string, line: number, column: number, runtime = false) {
    super(message);
    this.line = line;
    this.column = column;
    this.runtime = runtime;
  }
}

export type TokType =
  | 'word' // identifier (command, procedure or variable name)
  | 'cname' // legacy :name
  | 'num'
  | 'str' // "…"
  | '['
  | ']'
  | '('
  | ')'
  | 'op' // + - * /
  | 'cmp' // < > = <= >= <>
  | ','
  | 'ma' // "ma:" in a procedure header
  | 'eof';

export interface Tok {
  t: TokType;
  /** Raw source text of the token. */
  text: string;
  /** Normalised (lower-case, NFC) name for word / cname tokens. */
  name: string;
  value: number;
  line: number;
  col: number;
  /** Offsets into the source string. */
  pos: number;
  end: number;
  wsBefore: boolean;
  wsAfter: boolean;
  /** First / last token on its line. */
  first: boolean;
  last: boolean;
}

export type CmdKind =
  | 'fd'
  | 'bk'
  | 'rt'
  | 'lt'
  | 'pu'
  | 'pd'
  | 'color'
  | 'width'
  | 'repeat'
  | 'let'
  | 'if'
  | 'ifelse'
  | 'stop'
  | 'home'
  | 'cs'
  | 'pitchup'
  | 'pitchdown'
  | 'rollright'
  | 'rollleft';

export const COMMAND_ALIASES: Record<CmdKind, string[]> = {
  fd: ['np', 'naprzod', 'naprzód', 'fd', 'forward'],
  bk: ['ws', 'wstecz', 'bk', 'back'],
  rt: ['pw', 'prawo', 'rt', 'right'],
  lt: ['lw', 'lewo', 'lt', 'left'],
  pu: ['pod', 'podnies', 'podnieś', 'pu', 'penup'],
  pd: ['opu', 'opusc', 'opuść', 'pd', 'pendown'],
  color: ['kolor', 'color'],
  width: ['grubosc', 'grubość', 'width'],
  repeat: ['powtorz', 'powtórz', 'repeat'],
  let: ['niech', 'let'],
  if: ['jeśli', 'jesli', 'if'],
  ifelse: ['jeżeli', 'jezeli', 'ifelse'],
  stop: ['stop'],
  home: ['dom', 'home'],
  cs: ['czyść', 'czysc', 'cs', 'clearscreen'],
  pitchup: ['gora', 'góra', 'pitchup'],
  pitchdown: ['dol', 'dół', 'pitchdown'],
  rollright: ['pp', 'przechylprawo', 'rr', 'rollright'],
  rollleft: ['pl', 'przechyllewo', 'rl', 'rollleft'],
};

export const COMMANDS = new Map<string, CmdKind>();
for (const kind of Object.keys(COMMAND_ALIASES) as CmdKind[]) {
  for (const a of COMMAND_ALIASES[kind]) COMMANDS.set(a, kind);
}

export const DEF_WORDS = new Set(['oto', 'to']);
export const END_WORDS = new Set(['już', 'juz', 'end']);
export const REPCOUNT_WORDS = new Set(['nrpowt', 'repcount']);
export const ONLY_3D = new Set<CmdKind>(['pitchup', 'pitchdown', 'rollright', 'rollleft']);

export function isReserved(name: string): boolean {
  return COMMANDS.has(name) || DEF_WORDS.has(name) || END_WORDS.has(name) || REPCOUNT_WORDS.has(name);
}

export function normName(s: string): string {
  return s.normalize('NFC').toLowerCase();
}

export const MAX_SOURCE = 50000;
export const MAX_TOKENS = 10000;

const DELIMS = new Set(['[', ']', '(', ')', '+', '-', '*', '/', '<', '>', '=', ',', ';', '"', ':']);
const NUM_RE = /^(?:\d+(?:\.\d+)?|\.\d+)$/;
const IDENT_START = /[\p{L}_]/u;
const IDENT_CHAR = /[\p{L}\p{N}\p{M}_]/u;

function isWs(ch: string): boolean {
  return ch === ' ' || ch === '\t' || ch === '\n' || ch === '\r' || /\s/.test(ch);
}

export function tokenize(src: string): Tok[] {
  if (src.length > MAX_SOURCE) {
    throw new LogoError(
      `Program jest za długi: ma ${src.length} znaków, a limit to 50 000.`,
      1,
      1,
    );
  }
  const toks: Tok[] = [];
  let i = 0;
  let line = 1;
  let lineStart = 0;
  const n = src.length;

  const push = (t: TokType, pos: number, end: number, name = '', value = 0) => {
    const before = pos === 0 ? '' : src[pos - 1];
    const after = end >= n ? '' : src[end];
    const tok: Tok = {
      t,
      text: src.slice(pos, end),
      name,
      value,
      line,
      col: pos - lineStart + 1,
      pos,
      end,
      wsBefore: before === '' || isWs(before),
      wsAfter: after === '' || isWs(after) || after === ';',
      first: toks.length === 0 || toks[toks.length - 1].line !== line,
      last: true,
    };
    if (toks.length > 0 && toks[toks.length - 1].line === line) toks[toks.length - 1].last = false;
    if (toks.length >= MAX_TOKENS) {
      throw new LogoError('Program ma za dużo elementów (limit to 10 000).', tok.line, tok.col);
    }
    toks.push(tok);
    return tok;
  };

  while (i < n) {
    const ch = src[i];
    if (ch === '\n') {
      i++;
      line++;
      lineStart = i;
      continue;
    }
    if (ch === '\r') {
      i++;
      if (src[i] === '\n') i++;
      line++;
      lineStart = i;
      continue;
    }
    if (isWs(ch)) {
      i++;
      continue;
    }
    if (ch === ';') {
      while (i < n && src[i] !== '\n' && src[i] !== '\r') i++;
      continue;
    }
    if (ch === '[' || ch === ']' || ch === '(' || ch === ')' || ch === ',') {
      push(ch, i, i + 1);
      i++;
      continue;
    }
    if (ch === '+' || ch === '-' || ch === '*' || ch === '/') {
      push('op', i, i + 1);
      i++;
      continue;
    }
    if (ch === '<') {
      const two = src[i + 1] === '=' || src[i + 1] === '>';
      push('cmp', i, i + (two ? 2 : 1));
      i += two ? 2 : 1;
      continue;
    }
    if (ch === '>') {
      const two = src[i + 1] === '=';
      push('cmp', i, i + (two ? 2 : 1));
      i += two ? 2 : 1;
      continue;
    }
    if (ch === '=') {
      push('cmp', i, i + 1);
      i++;
      continue;
    }
    if (ch === '"') {
      let j = i + 1;
      while (j < n && src[j] !== '"' && src[j] !== '\n' && src[j] !== '\r') j++;
      if (j >= n || src[j] !== '"') {
        throw new LogoError(
          'Napis nie jest zamknięty: brakuje drugiego cudzysłowu ".',
          line,
          i - lineStart + 1,
        );
      }
      push('str', i, j + 1, src.slice(i + 1, j));
      i = j + 1;
      continue;
    }
    if (ch === ':') {
      const prev = toks[toks.length - 1];
      if (prev && prev.t === 'word' && prev.name === 'ma' && prev.end === i && prev.line === line) {
        // "ma:" introduces the parameter list of a procedure header.
        prev.t = 'ma';
        prev.text = src.slice(prev.pos, i + 1);
        prev.end = i + 1;
        const after = i + 1 >= n ? '' : src[i + 1];
        prev.wsAfter = after === '' || isWs(after) || after === ';';
        i++;
        continue;
      }
      let j = i + 1;
      while (j < n && !isWs(src[j]) && !DELIMS.has(src[j])) j++;
      const body = src.slice(i + 1, j);
      if (body === '' || !IDENT_START.test(body[0]) || ![...body].every((c) => IDENT_CHAR.test(c))) {
        throw new LogoError(
          'Po dwukropku powinna stać nazwa, na przykład :bok.',
          line,
          i - lineStart + 1,
        );
      }
      push('cname', i, j, normName(body));
      i = j;
      continue;
    }
    // A chunk: a number or a word.
    let j = i;
    while (j < n && !isWs(src[j]) && !DELIMS.has(src[j])) j++;
    const chunk = src.slice(i, j);
    const col = i - lineStart + 1;
    if (/[0-9.]/.test(chunk[0])) {
      if (!NUM_RE.test(chunk)) {
        throw new LogoError(
          `„${chunk}” nie jest poprawną liczbą. Liczby zapisuj tak: 80, 12.5 albo .5.`,
          line,
          col,
        );
      }
      const value = Number(chunk);
      if (!Number.isFinite(value)) {
        throw new LogoError(`Liczba „${shorten(chunk)}” jest za duża.`, line, col);
      }
      push('num', i, j, '', value);
    } else {
      let k = 0;
      for (const c of chunk) {
        const ok = k === 0 ? IDENT_START.test(c) : IDENT_CHAR.test(c);
        if (!ok) {
          throw new LogoError(`Nieoczekiwany znak „${c}”.`, line, col + k);
        }
        k += c.length;
      }
      push('word', i, j, normName(chunk));
    }
    i = j;
  }
  // EOF sentinel (not counted as a token).
  toks.push({
    t: 'eof',
    text: '',
    name: '',
    value: 0,
    line,
    col: n - lineStart + 1,
    pos: n,
    end: n,
    wsBefore: true,
    wsAfter: true,
    first: false,
    last: true,
  });
  return toks;
}

export function shorten(s: string, max = 24): string {
  return s.length > max ? s.slice(0, max - 1) + '…' : s;
}

