// Parser: tokens -> validated program tree. Every parse-time error is found here.
import {
  COMMANDS,
  DEF_WORDS,
  END_WORDS,
  LogoError,
  ONLY_3D,
  REPCOUNT_WORDS,
  isReserved,
  shorten,
  tokenize,
  type CmdKind,
  type Mode,
  type Tok,
} from './tokens';

export type RpnOp =
  | { k: 'num'; v: number }
  | { k: 'var'; name: string; text: string }
  | { k: 'rep' }
  | { k: 'neg' }
  | { k: '+' }
  | { k: '-' }
  | { k: '*' }
  | { k: '/' };

export interface Expr {
  rpn: RpnOp[];
  /** First token of the expression: where argument errors are reported. */
  start: Tok;
  /** True when the expression uses no names (and no nrpowt). */
  literal: boolean;
}

export interface Cond {
  left: Expr;
  op: string;
  right: Expr;
  start: Tok;
}

export type Stmt =
  | { k: 'move'; tok: Tok; sign: 1 | -1; arg: Expr }
  | { k: 'turn'; tok: Tok; axis: 'yaw' | 'pitch' | 'roll'; sign: 1 | -1; arg: Expr }
  | { k: 'pen'; tok: Tok; down: boolean }
  | { k: 'color'; tok: Tok; color: string }
  | { k: 'width'; tok: Tok; arg: Expr }
  | { k: 'repeat'; tok: Tok; count: Expr; body: Stmt[]; close: Tok }
  | { k: 'let'; tok: Tok; name: string; arg: Expr }
  | { k: 'if'; tok: Tok; cond: Cond; body: Stmt[]; close: Tok }
  | { k: 'ifelse'; tok: Tok; cond: Cond; body: Stmt[]; close: Tok; other: Stmt[]; otherClose: Tok }
  | { k: 'stop'; tok: Tok }
  | { k: 'home'; tok: Tok }
  | { k: 'clear'; tok: Tok }
  | { k: 'call'; tok: Tok; proc: Proc; args: Expr[] };

export interface Proc {
  name: string;
  text: string;
  params: string[];
  body: Stmt[];
  end: Tok;
}

export interface Program {
  body: Stmt[];
  procs: Map<string, Proc>;
  mode: Mode;
}

export const MAX_DEPTH = 32;
export const MAX_REPEAT = 10000;

interface Ctx {
  proc: Proc | null;
  locals: Set<string> | null;
  repeatDepth: number;
  depth: number;
}

const PREC: Record<string, number> = { '+': 1, '-': 1, '*': 2, '/': 2 };

export function evalRpnLiteral(rpn: RpnOp[]): number | null {
  const st: number[] = [];
  for (const o of rpn) {
    switch (o.k) {
      case 'num':
        st.push(o.v);
        break;
      case 'neg':
        st.push(-st.pop()!);
        break;
      case '+':
      case '-':
      case '*':
      case '/': {
        const b = st.pop()!;
        const a = st.pop()!;
        let r: number;
        if (o.k === '+') r = a + b;
        else if (o.k === '-') r = a - b;
        else if (o.k === '*') r = a * b;
        else {
          if (b === 0) return null;
          r = a / b;
        }
        if (!Number.isFinite(r)) return null;
        st.push(r);
        break;
      }
      default:
        return null;
    }
  }
  return st[0];
}

export function fmtNum(v: number): string {
  if (Number.isInteger(v)) return String(v);
  return String(Math.round(v * 1e6) / 1e6);
}

export function widthProblem(v: number): string | null {
  if (!Number.isInteger(v) || v < 1 || v > 12) {
    return `Grubość musi być liczbą całkowitą od 1 do 12, a wyszło ${fmtNum(v)}.`;
  }
  return null;
}

export function repeatProblem(v: number): string | null {
  if (!Number.isInteger(v) || v < 0 || v > MAX_REPEAT) {
    return `Liczba powtórzeń musi być liczbą całkowitą od 0 do 10 000, a wyszło ${fmtNum(v)}.`;
  }
  return null;
}

function describe(tok: Tok): string {
  switch (tok.t) {
    case 'eof':
      return 'koniec programu';
    case 'num':
      return `liczba ${shorten(tok.text)}`;
    case 'str':
      return `napis ${shorten(tok.text)}`;
    default:
      return `„${shorten(tok.text)}”`;
  }
}

class Parser {
  toks: Tok[];
  i = 0;
  mode: Mode;
  /** name -> number of parameters, collected before the main pass. */
  arity = new Map<string, number>();
  globals = new Set<string>();
  /** Token index of an `oto` -> names assigned by `niech` in that body. */
  localsAt = new Map<number, Set<string>>();
  procs = new Map<string, Proc>();
  /** Placeholders so that calls can be parsed before their definition. */
  shells = new Map<string, Proc>();

  constructor(src: string, mode: Mode) {
    this.toks = tokenize(src);
    this.mode = mode;
    this.prescan();
  }

  err(msg: string, tok: Tok): never {
    throw new LogoError(msg, tok.line, tok.col);
  }

  peek(): Tok {
    return this.toks[this.i];
  }

  isDef(t: Tok): boolean {
    return t.t === 'word' && DEF_WORDS.has(t.name);
  }

  isEnd(t: Tok): boolean {
    return t.t === 'word' && END_WORDS.has(t.name);
  }

  /** Collects procedure signatures and `niech` declarations ahead of time. */
  prescan() {
    const toks = this.toks;
    let current: Set<string> | null = null;
    for (let i = 0; i < toks.length; i++) {
      const t = toks[i];
      if (t.t !== 'word') continue;
      if (this.isDef(t) && t.first) {
        const nameTok = toks[i + 1];
        current = new Set();
        this.localsAt.set(i, current);
        if (nameTok.t === 'word' && nameTok.line === t.line) {
          let count = 0;
          let j = i + 2;
          for (; toks[j].t !== 'eof' && toks[j].line === t.line; j++) {
            if (toks[j].t === 'cname' || toks[j].t === 'word') count++;
          }
          if (!this.arity.has(nameTok.name) && !isReserved(nameTok.name)) {
            this.arity.set(nameTok.name, count);
            this.shells.set(nameTok.name, {
              name: nameTok.name,
              text: nameTok.text,
              params: [],
              body: [],
              end: nameTok,
            });
          }
          i = j - 1;
        }
      } else if (this.isEnd(t)) {
        current = null;
      } else if (COMMANDS.get(t.name) === 'let') {
        const nt = toks[i + 1];
        if (nt.t === 'word' || nt.t === 'cname') (current ?? this.globals).add(nt.name);
      }
    }
  }

  parseProgram(): Program {
    const body: Stmt[] = [];
    const ctx: Ctx = { proc: null, locals: null, repeatDepth: 0, depth: 0 };
    for (;;) {
      const t = this.peek();
      if (t.t === 'eof') break;
      if (this.isDef(t)) {
        this.parseProc();
      } else {
        body.push(this.parseStmt(ctx));
      }
    }
    return { body, procs: this.procs, mode: this.mode };
  }

  parseProc() {
    const otoIndex = this.i;
    const oto = this.toks[this.i++];
    if (!oto.first) {
      this.err(`Definicja procedury („${oto.text}”) musi zaczynać się na początku wiersza.`, oto);
    }
    // A definition without its closing word is reported at `oto`.
    let hasEnd = false;
    for (let j = this.i; j < this.toks.length; j++) {
      if (this.isEnd(this.toks[j])) {
        hasEnd = true;
        break;
      }
    }
    if (!hasEnd) {
      this.err('Procedura nie ma zakończenia: dopisz „już” w osobnym wierszu.', oto);
    }
    const nameTok = this.peek();
    if (nameTok.line !== oto.line || nameTok.t === 'eof') {
      this.err(`Po „${oto.text}” w tym samym wierszu podaj nazwę procedury.`, oto);
    }
    if (nameTok.t !== 'word') {
      this.err(`Nazwą procedury nie może być ${describe(nameTok)}.`, nameTok);
    }
    if (isReserved(nameTok.name)) {
      this.err(`„${nameTok.text}” to słowo języka i nie może być nazwą procedury.`, nameTok);
    }
    if (this.procs.has(nameTok.name)) {
      this.err(`Procedura „${nameTok.text}” jest już zdefiniowana.`, nameTok);
    }
    this.i++;
    const params: string[] = [];
    const addParam = (t: Tok) => {
      if (isReserved(t.name)) {
        this.err(`„${t.text}” to słowo języka i nie może być nazwą parametru.`, t);
      }
      if (params.includes(t.name)) {
        this.err(`Parametr „${t.text}” występuje w nagłówku dwa razy.`, t);
      }
      params.push(t.name);
    };
    const sameLine = () => this.peek().t !== 'eof' && this.peek().line === oto.line;
    if (sameLine() && this.peek().t === 'ma') {
      const ma = this.toks[this.i++];
      for (;;) {
        if (!sameLine()) {
          const prev = this.toks[this.i - 1];
          this.err('Po „ma:” wypisz parametry oddzielone przecinkami.', prev.t === ',' ? prev : ma);
        }
        const p = this.toks[this.i];
        if (p.t !== 'word') {
          this.err(`Tu powinna być nazwa parametru, a jest ${describe(p)}.`, p);
        }
        addParam(p);
        this.i++;
        if (sameLine() && this.peek().t === ',') {
          this.i++;
          continue;
        }
        break;
      }
      if (sameLine()) {
        const x = this.peek();
        this.err(
          `Nieoczekiwane ${describe(x)} w nagłówku procedury. Parametry oddziel przecinkami, a treść zacznij w następnym wierszu.`,
          x,
        );
      }
    } else {
      while (sameLine()) {
        const p = this.peek();
        if (p.t !== 'cname') {
          this.err(
            `Nieoczekiwane ${describe(p)} w nagłówku procedury. Parametry podaj po „ma:”, a treść zacznij w następnym wierszu.`,
            p,
          );
        }
        addParam(p);
        this.i++;
      }
    }
    const proc = this.shells.get(nameTok.name)!;
    proc.params = params;
    this.arity.set(nameTok.name, params.length);
    this.procs.set(nameTok.name, proc);
    const ctx: Ctx = {
      proc,
      locals: this.localsAt.get(otoIndex) ?? new Set(),
      repeatDepth: 0,
      depth: 0,
    };
    for (;;) {
      const t = this.peek();
      if (t.t === 'eof') {
        this.err('Procedura nie ma zakończenia: dopisz „już” w osobnym wierszu.', oto);
      }
      if (this.isEnd(t)) {
        if (!t.first || !t.last) {
          this.err(`„${t.text}” musi stać samo w osobnym wierszu.`, t);
        }
        proc.end = t;
        this.i++;
        break;
      }
      proc.body.push(this.parseStmt(ctx));
    }
  }

  parseStmt(ctx: Ctx): Stmt {
    const tok = this.toks[this.i++];
    switch (tok.t) {
      case 'word':
        break;
      case 'num':
      case 'str':
      case 'cname':
      case '(':
      case 'op':
        this.err(`Tu powinno być polecenie, a jest ${describe(tok)}.`, tok);
      // eslint-disable-next-line no-fallthrough
      case ']':
        this.err('Nawias ] nie ma pasującego nawiasu [.', tok);
      // eslint-disable-next-line no-fallthrough
      case ')':
        this.err('Nawias ) nie ma pasującego nawiasu (.', tok);
      // eslint-disable-next-line no-fallthrough
      default:
        this.err(`Tu powinno być polecenie, a jest ${describe(tok)}.`, tok);
    }
    const kind = COMMANDS.get(tok.name);
    if (kind) return this.parseCommand(kind, tok, ctx);
    if (DEF_WORDS.has(tok.name)) {
      if (ctx.proc && ctx.depth === 0) {
        this.err('Nie można definiować procedury wewnątrz innej procedury. Zakończ poprzednią słowem „już”.', tok);
      }
      if (ctx.depth > 0) {
        this.err('Procedury definiuje się poza nawiasami [ ], na najwyższym poziomie programu.', tok);
      }
      this.err(`Definicja procedury („${tok.text}”) musi zaczynać się na początku wiersza.`, tok);
    }
    if (END_WORDS.has(tok.name)) {
      if (ctx.depth > 0 && ctx.proc) {
        this.err(`„${tok.text}” pojawia się przed zamknięciem nawiasu [. Dopisz brakujący ].`, tok);
      }
      this.err(`„${tok.text}” kończy procedurę, ale żadna procedura nie jest tu otwarta.`, tok);
    }
    if (REPCOUNT_WORDS.has(tok.name)) {
      this.err(`„${tok.text}” to wartość, a nie polecenie. Użyj jej jako argumentu, np. „np ${tok.text} * 10”.`, tok);
    }
    const n = this.arity.get(tok.name);
    if (n !== undefined) {
      const proc = this.shells.get(tok.name)!;
      const args: Expr[] = [];
      for (let k = 0; k < n; k++) {
        args.push(
          this.parseExpr(tok, ctx, () =>
            n === 1
              ? `Procedura „${tok.text}” potrzebuje jednego argumentu.`
              : `Procedura „${tok.text}” potrzebuje ${n} argumentów, a podano ${k}.`,
          ),
        );
      }
      return { k: 'call', tok, proc, args };
    }
    if (this.isKnownName(tok.name, ctx)) {
      this.err(`Tu powinno być polecenie, a jest nazwa „${tok.text}”.`, tok);
    }
    this.err(`Nie znam polecenia „${shorten(tok.text)}”.`, tok);
  }

  isKnownName(name: string, ctx: Ctx): boolean {
    if (ctx.proc && (ctx.proc.params.includes(name) || ctx.locals!.has(name))) return true;
    return this.globals.has(name);
  }

  parseCommand(kind: CmdKind, tok: Tok, ctx: Ctx): Stmt {
    if (this.mode === '2d' && ONLY_3D.has(kind)) {
      this.err(`Polecenie „${tok.text}” działa tylko w trybie 3D. Przełącz tryb na 3D.`, tok);
    }
    const num = () => this.parseExpr(tok, ctx, () => `Polecenie „${tok.text}” potrzebuje liczby.`);
    switch (kind) {
      case 'fd':
        return { k: 'move', tok, sign: 1, arg: num() };
      case 'bk':
        return { k: 'move', tok, sign: -1, arg: num() };
      case 'rt':
        return { k: 'turn', tok, axis: 'yaw', sign: 1, arg: num() };
      case 'lt':
        return { k: 'turn', tok, axis: 'yaw', sign: -1, arg: num() };
      case 'pitchup':
        return { k: 'turn', tok, axis: 'pitch', sign: 1, arg: num() };
      case 'pitchdown':
        return { k: 'turn', tok, axis: 'pitch', sign: -1, arg: num() };
      case 'rollright':
        return { k: 'turn', tok, axis: 'roll', sign: 1, arg: num() };
      case 'rollleft':
        return { k: 'turn', tok, axis: 'roll', sign: -1, arg: num() };
      case 'pu':
        return { k: 'pen', tok, down: false };
      case 'pd':
        return { k: 'pen', tok, down: true };
      case 'stop':
        return { k: 'stop', tok };
      case 'home':
        return { k: 'home', tok };
      case 'cs':
        return { k: 'clear', tok };
      case 'color': {
        const c = this.peek();
        if (c.t !== 'str') {
          this.err(
            `Polecenie „${tok.text}” potrzebuje koloru w cudzysłowie, np. "#16866a".`,
            c.t === 'eof' ? tok : c,
          );
        }
        if (!/^#[0-9a-fA-F]{6}$/.test(c.name)) {
          this.err(
            `Niepoprawny kolor ${shorten(c.text)}. Kolor to znak # i sześć cyfr szesnastkowych, np. "#16866a".`,
            c,
          );
        }
        this.i++;
        return { k: 'color', tok, color: c.name.toLowerCase() };
      }
      case 'width': {
        const arg = num();
        if (arg.literal) {
          const v = evalRpnLiteral(arg.rpn);
          const p = v === null ? null : widthProblem(v);
          if (p) this.err(p, arg.start);
        }
        return { k: 'width', tok, arg };
      }
      case 'repeat': {
        const count = this.parseExpr(tok, ctx, () => `Polecenie „${tok.text}” potrzebuje liczby powtórzeń.`);
        if (count.literal) {
          const v = evalRpnLiteral(count.rpn);
          const p = v === null ? null : repeatProblem(v);
          if (p) this.err(p, count.start);
        }
        const { body, close } = this.parseBody(tok, { ...ctx, repeatDepth: ctx.repeatDepth + 1 }, 'Po liczbie powtórzeń');
        return { k: 'repeat', tok, count, body, close };
      }
      case 'let': {
        const nt = this.peek();
        if (nt.t !== 'word' && nt.t !== 'cname') {
          this.err(`Po „${tok.text}” podaj nazwę zmiennej, np. „${tok.text} bok 50”.`, nt.t === 'eof' ? tok : nt);
        }
        if (isReserved(nt.name)) {
          this.err(`„${nt.text}” to słowo języka i nie może być nazwą zmiennej.`, nt);
        }
        if (this.arity.has(nt.name) && !(ctx.proc && ctx.proc.params.includes(nt.name))) {
          this.err(`„${nt.text}” to nazwa procedury i nie może być nazwą zmiennej.`, nt);
        }
        this.i++;
        const arg = this.parseExpr(tok, ctx, () => `Po nazwie zmiennej „${nt.text}” podaj jej wartość.`);
        return { k: 'let', tok, name: nt.name, arg };
      }
      case 'if': {
        const cond = this.parseCond(tok, ctx);
        const { body, close } = this.parseBody(tok, ctx, 'Po warunku');
        return { k: 'if', tok, cond, body, close };
      }
      case 'ifelse': {
        const cond = this.parseCond(tok, ctx);
        const a = this.parseBody(tok, ctx, 'Po warunku');
        const b = this.parseBody(tok, ctx, `Polecenie „${tok.text}” ma dwie części w nawiasach [ ]. Po pierwszej`);
        return { k: 'ifelse', tok, cond, body: a.body, close: a.close, other: b.body, otherClose: b.close };
      }
    }
  }

  parseCond(cmd: Tok, ctx: Ctx): Cond {
    const left = this.parseExpr(cmd, ctx, () => `Polecenie „${cmd.text}” potrzebuje warunku, np. „bok > 10”.`);
    const op = this.peek();
    if (op.t !== 'cmp') {
      this.err(
        `W warunku brakuje porównania (<, >, =, <=, >=, <>)${op.t === 'eof' ? '' : `, a jest ${describe(op)}`}.`,
        op.t === 'eof' ? cmd : op,
      );
    }
    this.i++;
    const right = this.parseExpr(cmd, ctx, () => `Po „${op.text}” w warunku brakuje wartości.`);
    return { left, op: op.text, right, start: left.start };
  }

  parseBody(cmd: Tok, ctx: Ctx, where: string): { body: Stmt[]; close: Tok } {
    const open = this.peek();
    if (open.t !== '[') {
      this.err(
        `${where} powinien być nawias [${open.t === 'eof' ? '' : `, a jest ${describe(open)}`}.`,
        open.t === 'eof' ? cmd : open,
      );
    }
    if (ctx.depth + 1 > MAX_DEPTH) {
      this.err('Nawiasy [ ] są zagnieżdżone zbyt głęboko (limit to 32 poziomy).', open);
    }
    this.i++;
    const inner: Ctx = { ...ctx, depth: ctx.depth + 1 };
    const body: Stmt[] = [];
    for (;;) {
      const t = this.peek();
      if (t.t === 'eof') {
        this.err('Nawias [ nie został zamknięty: brakuje ].', open);
      }
      if (t.t === ']') {
        this.i++;
        return { body, close: t };
      }
      body.push(this.parseStmt(inner));
    }
  }

  /**
   * Parses one expression (shunting-yard, no recursion) into postfix form.
   * A binary operator needs whitespace on both sides or on neither side;
   * otherwise the expression ends before it.
   */
  parseExpr(cmd: Tok, ctx: Ctx, missing: () => string): Expr {
    const start = this.peek();
    const out: RpnOp[] = [];
    const ops: { k: string; tok: Tok }[] = [];
    let literal = true;
    let wantOperand = true;
    const parens: Tok[] = [];
    const reduce = () => {
      const o = ops.pop()!;
      out.push({ k: o.k } as RpnOp);
    };
    for (;;) {
      const t = this.peek();
      if (wantOperand) {
        if (t.t === 'op' && (t.text === '-' || t.text === '+')) {
          if (t.text === '-') ops.push({ k: 'neg', tok: t });
          this.i++;
          continue;
        }
        if (t.t === '(') {
          ops.push({ k: '(', tok: t });
          parens.push(t);
          this.i++;
          continue;
        }
        if (t.t === 'num') {
          out.push({ k: 'num', v: t.value });
        } else if (t.t === 'word' || t.t === 'cname') {
          if (t.t === 'word' && REPCOUNT_WORDS.has(t.name)) {
            if (ctx.repeatDepth === 0) {
              this.err(
                ctx.proc
                  ? `„${t.text}” działa tylko wewnątrz nawiasów polecenia „powtorz” zapisanego w tej samej procedurze.`
                  : `„${t.text}” działa tylko wewnątrz nawiasów polecenia „powtorz”.`,
                t,
              );
            }
            out.push({ k: 'rep' });
          } else if (t.t === 'word' && isReserved(t.name)) {
            this.err(`${missing()} Zamiast niej jest ${describe(t)}.`, t);
          } else if (this.isKnownName(t.name, ctx)) {
            out.push({ k: 'var', name: t.name, text: t.t === 'cname' ? t.text.slice(1) : t.text });
          } else {
            this.err(
              `Nie znam nazwy „${shorten(t.text)}”. To nie jest parametr ani zmienna utworzona poleceniem „niech”.`,
              t,
            );
          }
          literal = false;
        } else if (t.t === 'eof') {
          this.err(out.length || ops.length ? 'Wyrażenie jest niedokończone: brakuje wartości.' : missing(), cmd);
        } else {
          this.err(
            out.length || ops.length
              ? `W wyrażeniu brakuje wartości: zamiast niej jest ${describe(t)}.`
              : `${missing()} Zamiast niej jest ${describe(t)}.`,
            t,
          );
        }
        this.i++;
        wantOperand = false;
        continue;
      }
      // After an operand.
      if (t.t === ')' && parens.length > 0) {
        while (ops[ops.length - 1].k !== '(') reduce();
        ops.pop();
        parens.pop();
        this.i++;
        continue;
      }
      if (t.t === 'op' && t.wsBefore === t.wsAfter) {
        const p = PREC[t.text];
        while (ops.length > 0) {
          const top = ops[ops.length - 1];
          if (top.k === '(') break;
          if (top.k === 'neg' || PREC[top.k] >= p) reduce();
          else break;
        }
        ops.push({ k: t.text, tok: t });
        this.i++;
        wantOperand = true;
        continue;
      }
      break;
    }
    if (parens.length > 0) {
      const t = this.peek();
      if (t.t === 'eof') {
        this.err('Nawias ( nie został zamknięty: brakuje ).', parens[parens.length - 1]);
      }
      if (t.t === 'op') {
        this.err(
          `Znak „${t.text}” musi mieć odstęp z obu stron albo z żadnej (np. „10 - 5” lub „10-5”).`,
          t,
        );
      }
      this.err(`Tu powinien być nawias ), a jest ${describe(t)}.`, t);
    }
    while (ops.length > 0) reduce();
    return { rpn: out, start, literal };
  }
}

export function parse(src: string, mode: Mode): Program {
  return new Parser(src, mode).parseProgram();
}

