  const [s, c] = sinCos(deg);
  return [
    [a[0] * c + b[0] * s, a[1] * c + b[1] * s, a[2] * c + b[2] * s],
    [b[0] * c - a[0] * s, b[1] * c - a[1] * s, b[2] * c - a[2] * s],
  ];
}

const z = (v: number) => (v === 0 ? 0 : v);

export class Machine {
  program: Program;
  segments: Segment[] = [];
  pos: Vec3 = [0, 0, 0];
  heading: Vec3 = [0, 1, 0];
  right: Vec3 = [1, 0, 0];
  up: Vec3 = [0, 0, 1];
  penDown = true;
  color = DEFAULT_COLOR;
  width = DEFAULT_WIDTH;
  ops = 0;
  frames = 0;
  globals = new Map<string, number>();
  /** Bumped by `czyść`, so that views know earlier segments are gone. */
  clears = 0;

  constructor(program: Program) {
    this.program = program;
  }

  private fail(msg: string, tok: Tok): never {
    throw new LogoError(msg, tok.line, tok.col, true);
  }

  private tick(tok: Tok) {
    if (this.ops >= MAX_OPS) {
      this.fail('Program wykonał już 10 000 operacji i został zatrzymany. Może powtarza się bez końca?', tok);
    }
    this.ops++;
  }

  private evalExpr(e: Expr, env: Env, at: Tok): number {
    const st: number[] = [];
    for (const o of e.rpn) {
      switch (o.k) {
        case 'num':
          st.push(o.v);
          break;
        case 'var': {
          const v = env.locals?.get(o.name) ?? this.globals.get(o.name);
          if (v === undefined) {
            this.fail(`Zmienna „${o.text}” nie ma jeszcze wartości. Nadaj ją wcześniej poleceniem „niech”.`, at);
          }
          st.push(v);
          break;
        }
        case 'rep':
          st.push(env.rep[env.rep.length - 1]);
          break;
        case 'neg':
          st.push(-st.pop()!);
          break;
        default: {
          const b = st.pop()!;
          const a = st.pop()!;
          let r: number;
          if (o.k === '+') r = a + b;
          else if (o.k === '-') r = a - b;
          else if (o.k === '*') r = a * b;
          else {
            if (b === 0) this.fail('Dzielenie przez zero.', at);
            r = a / b;
          }
          if (!Number.isFinite(r)) this.fail('Wynik działania nie jest skończoną liczbą.', at);
          st.push(r);
        }
      }
    }
    return st[0];
  }

  private evalCond(c: Cond, env: Env): boolean {
    const a = this.evalExpr(c.left, env, c.start);
    const b = this.evalExpr(c.right, env, c.start);
    switch (c.op) {
      case '<':
        return a < b;
      case '>':
        return a > b;
      case '=':
        return a === b;
      case '<=':
        return a <= b;
      case '>=':
        return a >= b;
      default:
        return a !== b;
    }
  }

  private moveTo(p: Vec3, tok: Tok) {
    if (Math.abs(p[0]) > MAX_COORD || Math.abs(p[1]) > MAX_COORD || Math.abs(p[2]) > MAX_COORD) {
      this.fail('Żółw uciekł za daleko: współrzędne muszą mieścić się w zakresie ±100 000.', tok);
    }
    const q = this.pos;
    const moved = p[0] !== q[0] || p[1] !== q[1] || p[2] !== q[2];
    if (moved && this.penDown) {
      if (this.segments.length >= MAX_SEGMENTS) {
        this.fail('Rysunek ma już 10 000 odcinków i więcej się nie zmieści.', tok);
      }
      this.segments.push({
        from: [z(q[0]), z(q[1]), z(q[2])],
        to: [z(p[0]), z(p[1]), z(p[2])],
        color: this.color,
        width: this.width,
      });
    }
    this.pos = p;
  }

  /** Runs the program; yields the token of each operation just before it executes. */
  *run(): Generator<Tok, void, void> {
    yield* this.block(this.program.body, { locals: null, rep: [] });
  }

  private *block(stmts: Stmt[], env: Env): Generator<Tok, boolean, void> {
    for (const s of stmts) {
      yield s.tok;
      this.tick(s.tok);
      switch (s.k) {
        case 'move': {
          const d = this.evalExpr(s.arg, env, s.arg.start) * s.sign;
          const h = this.heading;
          const p = this.pos;
          this.moveTo([p[0] + h[0] * d, p[1] + h[1] * d, p[2] + h[2] * d], s.tok);
          break;
        }
        case 'turn': {
          const a = this.evalExpr(s.arg, env, s.arg.start) * s.sign;
          if (s.axis === 'yaw') [this.heading, this.right] = rotate(this.heading, this.right, a);
          else if (s.axis === 'pitch') [this.heading, this.up] = rotate(this.heading, this.up, a);
          else [this.up, this.right] = rotate(this.up, this.right, a);
          break;
        }
        case 'pen':
          this.penDown = s.down;
          break;
        case 'color':
          this.color = s.color;
          break;
        case 'width': {
          const v = this.evalExpr(s.arg, env, s.arg.start);
          const p = widthProblem(v);
          if (p) this.fail(p, s.arg.start);
          this.width = v;
          break;
        }
        case 'let': {
          const v = this.evalExpr(s.arg, env, s.arg.start);
          (env.locals ?? this.globals).set(s.name, v);
          break;
        }
        case 'home':
          this.moveTo([0, 0, 0], s.tok);
          this.heading = [0, 1, 0];
          this.right = [1, 0, 0];
          this.up = [0, 0, 1];
          break;
        case 'clear':
          this.segments.length = 0;
          this.clears++;
          break;
        case 'stop':
          return true;
        case 'repeat': {
          const n = this.evalExpr(s.count, env, s.count.start);
          const p = repeatProblem(n);
          if (p) this.fail(p, s.count.start);
          if (n === 0) break;
          if (this.frames >= MAX_FRAMES) this.failFrames(s.tok);
          this.frames++;
          env.rep.push(0);
          for (let i = 1; i <= n; i++) {
            env.rep[env.rep.length - 1] = i;
            if (yield* this.block(s.body, env)) {
              env.rep.pop();
              this.frames--;
              return true;
            }
            this.tick(s.close);
          }
          env.rep.pop();
          this.frames--;
          break;
        }
        case 'if':
          if (this.evalCond(s.cond, env)) {
            if (yield* this.block(s.body, env)) return true;
            this.tick(s.close);
          }
          break;
        case 'ifelse': {
          const yes = this.evalCond(s.cond, env);
          if (yield* this.block(yes ? s.body : s.other, env)) return true;
          this.tick(yes ? s.close : s.otherClose);
          break;
        }
        case 'call': {
          const locals = new Map<string, number>();
          for (let i = 0; i < s.args.length; i++) {
            locals.set(s.proc.params[i], this.evalExpr(s.args[i], env, s.args[i].start));
          }
          if (this.frames >= MAX_FRAMES) this.failFrames(s.tok);
          const saved = this.frames;
          this.frames++;
          const stopped = yield* this.block(s.proc.body, { locals, rep: [] });
          this.frames = saved;
          if (!stopped) this.tick(s.proc.end);
          break;
        }
      }
    }
    return false;
  }

  private failFrames(tok: Tok): never {
    this.fail(
      'Zbyt wiele zagnieżdżonych wywołań procedur i powtórzeń naraz (limit to 32). Czy rekurencja ma warunek zakończenia?',
      tok,
    );
  }
}

export function toErrorInfo(e: unknown): LogoErrorInfo {
  if (e instanceof LogoError) return { message: e.message, line: e.line, column: e.column };
  if (e instanceof RangeError) {
    return { message: 'Program jest zbyt złożony, żeby go wykonać.', line: 1, column: 1 };
  }
  throw e;
}

export function copySegments(segs: Segment[]): Segment[] {
  return segs.map((s) => ({
    from: [s.from[0], s.from[1], s.from[2]],
    to: [s.to[0], s.to[1], s.to[2]],
    color: s.color,
    width: s.width,
  }));
}

export function normMode(mode: unknown): Mode {
  return String(mode).toLowerCase() === '3d' ? '3d' : '2d';
}

/** Interprets a whole program at once. */
export function run(source: string, mode: Mode | string = '2d'): RunResult {
  const m = normMode(mode);
  let program: Program;
  try {
    program = parse(String(source ?? ''), m);
  } catch (e) {
    return { segments: [], error: toErrorInfo(e) };
  }
  const machine = new Machine(program);
  let error: LogoErrorInfo | null = null;
  try {
    const it = machine.run();
    while (!it.next().done);
  } catch (e) {
    error = toErrorInfo(e);
  }
  return { segments: copySegments(machine.segments), error };
}

