import { describe, expect, test } from 'bun:test';
import { run } from '../src/lang';
import { EXAMPLES } from '../src/examples';

const r2 = (s: string) => run(s, '2d');
const r3 = (s: string) => run(s, '3d');
const near = (a: number[], b: number[], eps = 1e-9) => {
  expect(a.length).toBe(b.length);
  a.forEach((v, i) => expect(Math.abs(v - b[i])).toBeLessThan(eps));
};
const end = (s: string, mode = '2d') => {
  const r = run(s, mode);
  expect(r.error).toBeNull();
  return r.segments[r.segments.length - 1].to;
};
const errAt = (s: string, line: number, column: number, mode = '2d') => {
  const r = run(s, mode);
  expect(r.error).not.toBeNull();
  expect([r.error!.line, r.error!.column]).toEqual([line, column]);
  return r;
};

describe('podstawy', () => {
  test('np rysuje odcinek z domyślnym kolorem i grubością', () => {
    expect(r2('np 80')).toEqual({
      segments: [{ from: [0, 0, 0], to: [0, 80, 0], color: '#16866a', width: 3 }],
      error: null,
    });
  });
  test('aliasy i wielkość liter', () => {
    for (const c of ['np', 'NP', 'naprzod', 'naprzód', 'NAPRZÓD', 'fd', 'Forward']) {
      near(end(`${c} 10`), [0, 10, 0]);
    }
    for (const c of ['ws', 'wstecz', 'bk', 'back']) near(end(`${c} 10`), [0, -10, 0]);
    for (const c of ['pw', 'prawo', 'rt', 'right']) near(end(`${c} 90 np 10`), [10, 0, 0]);
    for (const c of ['lw', 'lewo', 'lt', 'left']) near(end(`${c} 90 np 10`), [-10, 0, 0]);
    for (const c of ['pod', 'podnies', 'podnieś', 'pu', 'penup']) expect(r2(`${c} np 10`).segments).toEqual([]);
    for (const c of ['opu', 'opusc', 'opuść', 'pd', 'pendown']) expect(r2(`pod ${c} np 10`).segments.length).toBe(1);
    for (const c of ['powtorz', 'powtórz', 'repeat']) expect(r2(`${c} 3 [np 10]`).segments.length).toBe(3);
    for (const c of ['czyść', 'czysc', 'cs', 'clearscreen']) expect(r2(`np 10 ${c}`).segments).toEqual([]);
    for (const c of ['dom', 'home']) near(end(`np 10 ${c}`), [0, 0, 0]);
    for (const c of ['grubosc', 'grubość', 'width']) expect(r2(`${c} 7 np 1`).segments[0].width).toBe(7);
    for (const c of ['kolor', 'color']) expect(r2(`${c} "#AABBCC" np 1`).segments[0].color).toBe('#aabbcc');
    for (const c of ['jeśli', 'jesli', 'if']) expect(r2(`${c} 1 < 2 [np 1]`).segments.length).toBe(1);
    for (const c of ['jeżeli', 'jezeli', 'ifelse']) near(end(`${c} 1 > 2 [np 1] [np 2]`), [0, 2, 0]);
    for (const c of ['niech', 'let']) near(end(`${c} x 5 np X`), [0, 5, 0]);
    for (const c of ['gora', 'góra', 'pitchup']) near(end(`${c} 90 np 10`, '3d'), [0, 0, 10]);
    for (const c of ['dol', 'dół', 'pitchdown']) near(end(`${c} 90 np 10`, '3d'), [0, 0, -10]);
    for (const c of ['pp', 'przechylprawo', 'rr', 'rollright']) near(end(`${c} 90 gora 90 np 10`, '3d'), [10, 0, 0]);
    for (const c of ['pl', 'przechyllewo', 'rl', 'rollleft']) near(end(`${c} 90 gora 90 np 10`, '3d'), [-10, 0, 0]);
    for (const c of ['nrpowt', 'repcount']) near(end(`powtorz 3 [np ${c}]`), [0, 6, 0]);
  });
