  test('śnieżynka się zamyka', () => {
    const r = run(EXAMPLES.find((e) => e.id === 'sniezynka')!.source, '2d');
    expect(r.segments.length).toBe(3 * 256);
    near(r.segments[0].from, r.segments[r.segments.length - 1].to, 1e-6);
