// Lenient syntax highlighter for the editor and the reference page.
import { COMMANDS, DEF_WORDS, END_WORDS, REPCOUNT_WORDS, normName } from '../lang/tokens';
import { esc } from './dom';

const TOKEN_RE =
  /(;.*$)|("[^"]*"?)|(:?[\p{L}_][\p{L}\p{N}\p{M}_]*:?)|(\d+(?:\.\d+)?|\.\d+)|([[\]])|([()])|(<=|>=|<>|[-+*/<>=,])|(\s+)|(.)/gu;
const CONTROL = new Set(['repeat', 'let', 'if', 'ifelse', 'stop']);

function procNames(src: string): Set<string> {
  const names = new Set<string>();
  const re = /^[ \t]*(?:oto|to)[ \t]+([\p{L}_][\p{L}\p{N}\p{M}_]*)/gimu;
  let m: RegExpExecArray | null;
  while ((m = re.exec(src))) names.add(normName(m[1]));
  return names;
}

export function highlightLine(line: string, procs: Set<string>): string {
  let out = '';
  TOKEN_RE.lastIndex = 0;
  let m: RegExpExecArray | null;
  while ((m = TOKEN_RE.exec(line))) {
    const t = m[0];
    let cls = '';
    if (m[1]) cls = 'com';
    else if (m[2]) cls = 'str';
    else if (m[3]) {
      const bare = normName(t.replace(/:$/, ''));
      if (t.startsWith(':')) cls = 'var';
      else if (t.endsWith(':')) cls = bare === 'ma' ? 'def' : 'name';
      else if (COMMANDS.has(bare)) cls = CONTROL.has(COMMANDS.get(bare)!) ? 'ctl' : 'cmd';
      else if (DEF_WORDS.has(bare) || END_WORDS.has(bare)) cls = 'def';
      else if (REPCOUNT_WORDS.has(bare)) cls = 'rep';
      else if (procs.has(bare)) cls = 'proc';
      else cls = 'name';
    } else if (m[4]) cls = 'num';
    else if (m[5]) cls = 'br';
    else if (m[6]) cls = 'par';
    else if (m[7]) cls = 'op';
    out += cls ? `<span class="t-${cls}">${esc(t)}</span>` : esc(t);
  }
  return out;
}

export function highlightLines(src: string): string[] {
  const procs = procNames(src);
  return src.split(/\r\n|\r|\n/).map((l) => highlightLine(l, procs));
}

export function highlightHtml(src: string): string {
  return highlightLines(src).join('\n');
}
