// Code editor: a textarea with a highlighted overlay, line numbers and markers.
import { esc, h } from './dom';
import { highlightLines } from './highlight';

export interface EditorError {
  message: string;
  line: number;
  column: number;
}

export class Editor {
  el: HTMLElement;
  textarea: HTMLTextAreaElement;
  onChange: (value: string) => void = () => {};
  private gutterInner: HTMLElement;
  private layers: HTMLElement;
  private pre: HTMLElement;
  private execBand: HTMLElement;
  private errBand: HTMLElement;
  private squiggle: HTMLElement;
  private error: EditorError | null = null;
  private execLine: number | null = null;
  private lineCount = 0;

  constructor(label: string, describedBy: string) {
    this.textarea = h('textarea', {
      class: 'ed-input',
      spellcheck: 'false',
      autocapitalize: 'off',
      autocomplete: 'off',
      autocorrect: 'off',
      wrap: 'off',
      'aria-label': label,
      'aria-describedby': describedBy,
    });
    this.pre = h('pre', { class: 'ed-hl' });
    this.execBand = h('div', { class: 'ed-band exec', hidden: true });
    this.errBand = h('div', { class: 'ed-band err', hidden: true });
    this.squiggle = h('div', { class: 'ed-squiggle', hidden: true });
    this.layers = h('div', { class: 'ed-layers', 'aria-hidden': 'true' }, this.execBand, this.errBand, this.pre, this.squiggle);
    this.gutterInner = h('div', { class: 'ed-gutter-inner' });
    this.el = h(
      'div',
      { class: 'editor' },
      h('div', { class: 'ed-gutter', 'aria-hidden': 'true' }, this.gutterInner),
      h('div', { class: 'ed-main' }, this.layers, this.textarea),
    );
    this.textarea.addEventListener('input', () => {
      this.error = null;
      this.execLine = null;
      this.refresh();
      this.onChange(this.textarea.value);
    });
    this.textarea.addEventListener('scroll', () => this.syncScroll());
    this.textarea.addEventListener('keydown', (e) => this.onKey(e));
    this.refresh();
  }

  getValue(): string {
    return this.textarea.value;
  }

  setValue(v: string) {
    this.textarea.value = v;
    this.error = null;
    this.execLine = null;
    this.textarea.scrollTop = 0;
    this.textarea.scrollLeft = 0;
    this.refresh();
    this.syncScroll();
  }

  setError(err: EditorError | null, reveal = true) {
    this.error = err;
    this.refreshMarks();
    if (err && reveal) this.revealLine(err.line);
  }

  setExecLine(line: number | null, reveal = true) {
    if (this.execLine === line) return;
    this.execLine = line;
    this.refreshMarks();
    if (line !== null && reveal) this.revealLine(line);
  }

  /** Puts the caret at a 1-based line and column and focuses the editor. */
  goto(line: number, column: number) {
    const lines = this.textarea.value.split('\n');
    let pos = 0;
    for (let i = 0; i < Math.min(line - 1, lines.length); i++) pos += lines[i].length + 1;
    pos += Math.min(column - 1, (lines[line - 1] ?? '').length);
    this.textarea.focus();
    this.textarea.setSelectionRange(pos, pos);
    this.revealLine(line);
  }

  private lineHeight(): number {
    return parseFloat(getComputedStyle(this.textarea).lineHeight) || 22;
  }

  private revealLine(line: number) {
    const lh = this.lineHeight();
    const ta = this.textarea;
    const top = (line - 1) * lh;
    if (top < ta.scrollTop) ta.scrollTop = Math.max(0, top - lh);
    else if (top + lh * 2 > ta.scrollTop + ta.clientHeight) ta.scrollTop = top + lh * 3 - ta.clientHeight;
    this.syncScroll();
  }

  private syncScroll() {
    const ta = this.textarea;
    this.layers.style.transform = `translate(${-ta.scrollLeft}px, ${-ta.scrollTop}px)`;
    this.gutterInner.style.transform = `translateY(${-ta.scrollTop}px)`;
  }

  private refresh() {
    const src = this.textarea.value;
    const lines = highlightLines(src);
    const err = this.error;
    if (err && err.line >= 1 && err.line <= lines.length) {
      lines[err.line - 1] += `<span class="ed-lens">  ← ${esc(err.message)}</span>`;
