    this.pre.innerHTML = lines.join('\n') + '\n';
    if (lines.length !== this.lineCount) {
      this.lineCount = lines.length;
      let html = '';
      for (let i = 1; i <= lines.length; i++) html += `<div class="ed-ln" data-line="${i}">${i}</div>`;
      this.gutterInner.innerHTML = html;
    }
    this.refreshMarks(false);
  }

