    if (redrawLens) {
      // The message at the end of the error line lives in the highlight layer.
      const src = this.textarea.value;
      const lines = highlightLines(src);
      const err = this.error;
      if (err && err.line >= 1 && err.line <= lines.length) {
        lines[err.line - 1] += `<span class="ed-lens">  ← ${esc(err.message)}</span>`;
      }
      this.pre.innerHTML = lines.join('\n') + '\n';
    }
    const gutter = this.gutterInner.children;
    for (let i = 0; i < gutter.length; i++) {
      const cls = 'ed-ln' + (this.error?.line === i + 1 ? ' err' : '') + (this.execLine === i + 1 ? ' exec' : '');
      if (gutter[i].className !== cls) gutter[i].className = cls;
    }
    const place = (band: HTMLElement, line: number | null) => {
      if (line === null) {
        band.hidden = true;
        return;
      }
      band.hidden = false;
      band.style.top = `calc(var(--ed-pad) + ${line - 1} * var(--ed-lh))`;
    };
    place(this.execBand, this.execLine);
    place(this.errBand, this.error ? this.error.line : null);
    const err = this.error;
    if (err) {
      const text = this.textarea.value.split(/\r\n|\r|\n/)[err.line - 1] ?? '';
      const rest = text.slice(err.column - 1);
      const m = /^(?:"[^"]*"?|:?[\p{L}\p{N}\p{M}_.]+:?|<=|>=|<>|\S)/u.exec(rest);
      const len = Math.max(1, m ? m[0].length : 1);
      this.squiggle.hidden = false;
      this.squiggle.style.top = `calc(var(--ed-pad) + ${err.line} * var(--ed-lh) - 4px)`;
      this.squiggle.style.left = `calc(var(--ed-pad-x) + ${err.column - 1}ch)`;
      this.squiggle.style.width = `${len}ch`;
    } else {
      this.squiggle.hidden = true;
    }
  }

  private insert(text: string) {
    const ta = this.textarea;
    let ok = false;
    try {
      ok = document.execCommand('insertText', false, text);
    } catch {
      ok = false;
    }
    if (!ok) {
      ta.setRangeText(text, ta.selectionStart, ta.selectionEnd, 'end');
      ta.dispatchEvent(new Event('input', { bubbles: true }));
    }
  }

  private onKey(e: KeyboardEvent) {
    if (e.key === 'Enter' && !e.ctrlKey && !e.metaKey && !e.altKey && !e.shiftKey && !e.isComposing) {
      // Keep the indentation of the current line; indent after an opening bracket.
      const ta = this.textarea;
      const before = ta.value.slice(0, ta.selectionStart);
      const line = before.slice(before.lastIndexOf('\n') + 1);
      let indent = /^[ \t]*/.exec(line)![0];
      const trimmed = line.trimEnd();
      if (trimmed.endsWith('[') || /^\s*(oto|to)\s/i.test(line)) indent += '  ';
      if (indent) {
        e.preventDefault();
        this.insert('\n' + indent);
      }
    }
  }
}

