// Canvas renderers: the flat 2D plane and the 3D space (software projection,
// drawn with the 2D canvas API so it needs no WebGL and works everywhere).
import type { Segment, Vec3 } from '../lang/interp';

export interface TurtleState {
  pos: Vec3;
  heading: Vec3;
  up: Vec3;
  right: Vec3;
  penDown: boolean;
  color: string;
}

export interface Scene {
  segments: Segment[];
  /** How many of `segments` are fully drawn. */
  count: number;
  /** A segment still being drawn (animation). */
  tip: Segment | null;
  turtle: TurtleState | null;
  /** Challenge target, drawn as a faint trace. */
  ghost: Segment[] | null;
}

export interface Palette {
  paper: string;
  grid: string;
  gridStrong: string;
  axis: string;
  text: string;
  ghost: string;
  shell: string;
  shellEdge: string;
  skin: string;
  axisX: string;
  axisY: string;
  axisZ: string;
}

export interface DrawOpts {
  turtle: boolean;
  dpr: number;
}

export interface Bounds {
  min: Vec3;
  max: Vec3;
}

export function sceneBounds(scene: Scene, withGhost = true): Bounds {
  const min: Vec3 = [Infinity, Infinity, Infinity];
  const max: Vec3 = [-Infinity, -Infinity, -Infinity];
  const add = (p: Vec3) => {
    for (let i = 0; i < 3; i++) {
      if (p[i] < min[i]) min[i] = p[i];
      if (p[i] > max[i]) max[i] = p[i];
    }
  };
  for (let i = 0; i < scene.count; i++) {
    add(scene.segments[i].from);
    add(scene.segments[i].to);
  }
  if (scene.tip) {
    add(scene.tip.from);
    add(scene.tip.to);
  }
  if (withGhost && scene.ghost) {
    for (const s of scene.ghost) {
      add(s.from);
      add(s.to);
    }
  }
  if (scene.turtle) add(scene.turtle.pos);
  if (min[0] === Infinity) return { min: [0, 0, 0], max: [0, 0, 0] };
  return { min, max };
}

export interface View {
  /** True until the user moves the view by hand: the view then follows the drawing. */
  auto: boolean;
  draw(ctx: CanvasRenderingContext2D, w: number, h: number, scene: Scene, pal: Palette, opts: DrawOpts): void;
  fit(b: Bounds, w: number, h: number): void;
  /** Refits only when the bounds do not fit in the current view. */
  ensure(b: Bounds, w: number, h: number): void;
  reset(): void;
  zoomBy(f: number, px: number, py: number, w: number, h: number): void;
  drag(dx: number, dy: number, alt: boolean, w: number, h: number): void;
  key(dx: number, dy: number, alt: boolean, w: number, h: number): void;
}

const clamp = (v: number, a: number, b: number) => Math.min(b, Math.max(a, v));

function lineScale(pxPerUnit: number): number {
  return clamp(Math.sqrt(pxPerUnit), 0.6, 1.6);
}

function niceStep(minUnits: number): number {
  const pow = Math.pow(10, Math.floor(Math.log10(minUnits)));
  for (const m of [1, 2, 5, 10]) if (pow * m >= minUnits) return pow * m;
  return pow * 10;
}

// ---------------------------------------------------------------- 2D

export class View2D implements View {
  auto = true;
  cx = 0;
  cy = 0;
  scale = 2;

  reset() {
    this.cx = 0;
    this.cy = 0;
    this.scale = 2;
    this.auto = true;
  }

  fit(b: Bounds, w: number, h: number) {
    const m = Math.max(28, Math.min(w, h) * 0.1);
    const bw = b.max[0] - b.min[0];
    const bh = b.max[1] - b.min[1];
    const sx = bw > 1e-9 ? (w - 2 * m) / bw : Infinity;
    const sy = bh > 1e-9 ? (h - 2 * m) / bh : Infinity;
    let s = Math.min(sx, sy);
    if (!Number.isFinite(s)) s = 2;
    this.scale = clamp(s, 0.002, 6);
    this.cx = (b.min[0] + b.max[0]) / 2;
    this.cy = (b.min[1] + b.max[1]) / 2;
  }

  ensure(b: Bounds, w: number, h: number) {
    const m = 18;
    const x0 = w / 2 + (b.min[0] - this.cx) * this.scale;
    const x1 = w / 2 + (b.max[0] - this.cx) * this.scale;
    const y0 = h / 2 - (b.max[1] - this.cy) * this.scale;
    const y1 = h / 2 - (b.min[1] - this.cy) * this.scale;
    if (x0 < m || y0 < m || x1 > w - m || y1 > h - m) {
      const old = this.scale;
      this.fit(b, w, h);
      // Zoom out a little further so that the view does not refit on every step.
      if (this.scale < old) this.scale *= 0.85;
      else this.scale = old;
    }
  }

  zoomBy(f: number, px: number, py: number, w: number, h: number) {
    const wx = this.cx + (px - w / 2) / this.scale;
    const wy = this.cy - (py - h / 2) / this.scale;
    this.scale = clamp(this.scale * f, 0.002, 60);
    this.cx = wx - (px - w / 2) / this.scale;
    this.cy = wy + (py - h / 2) / this.scale;
    this.auto = false;
  }

  drag(dx: number, dy: number) {
    this.cx -= dx / this.scale;
    this.cy += dy / this.scale;
    this.auto = false;
  }

  key(dx: number, dy: number) {
    this.drag(-dx * 40, -dy * 40);
  }

  draw(ctx: CanvasRenderingContext2D, w: number, h: number, scene: Scene, pal: Palette, opts: DrawOpts) {
    const s = this.scale;
    const X = (x: number) => w / 2 + (x - this.cx) * s;
    const Y = (y: number) => h / 2 - (y - this.cy) * s;
    ctx.fillStyle = pal.paper;
    ctx.fillRect(0, 0, w, h);

    // Graph-paper grid.
    const step = niceStep(12 / s);
    const major = step * 5;
    const left = this.cx - w / 2 / s;
    const right = this.cx + w / 2 / s;
    const bottom = this.cy - h / 2 / s;
    const top = this.cy + h / 2 / s;
    for (const [st, color] of [
      [step, pal.grid],
      [major, pal.gridStrong],
    ] as [number, string][]) {
      ctx.beginPath();
      for (let x = Math.ceil(left / st) * st; x <= right; x += st) {
        const px = Math.round(X(x)) + 0.5;
        ctx.moveTo(px, 0);
        ctx.lineTo(px, h);
      }
      for (let y = Math.ceil(bottom / st) * st; y <= top; y += st) {
        const py = Math.round(Y(y)) + 0.5;
        ctx.moveTo(0, py);
        ctx.lineTo(w, py);
      }
      ctx.strokeStyle = color;
      ctx.lineWidth = 1;
      ctx.stroke();
    }

    // Axes and the origin.
    const ox = Math.round(X(0)) + 0.5;
    const oy = Math.round(Y(0)) + 0.5;
    ctx.strokeStyle = pal.axis;
    ctx.lineWidth = 1.25;
    ctx.beginPath();
    ctx.moveTo(0, oy);
    ctx.lineTo(w, oy);
    ctx.moveTo(ox, 0);
    ctx.lineTo(ox, h);
    ctx.stroke();
    ctx.beginPath();
    ctx.arc(ox, oy, 4.5, 0, Math.PI * 2);
    ctx.fillStyle = pal.paper;
    ctx.fill();
    ctx.lineWidth = 1.5;
    ctx.stroke();
    ctx.fillStyle = pal.text;
    ctx.font = '600 11px ui-monospace, Menlo, Consolas, monospace';
    ctx.textBaseline = 'top';
    ctx.textAlign = 'left';
    if (ox > -40 && ox < w + 40 && oy > -40 && oy < h + 40) {
      ctx.fillText('0', ox + 7, oy + 6);
    }
    ctx.textAlign = 'right';
    ctx.fillText('x', w - 8, clamp(oy + 6, 6, h - 18));
    ctx.textAlign = 'left';
    ctx.fillText('y', clamp(ox + 7, 6, w - 14), 7);

    const ls = lineScale(s);
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';

    if (scene.ghost) {
      ctx.save();
      ctx.strokeStyle = pal.ghost;
      ctx.lineWidth = Math.max(5, 7 * ls);
      ctx.beginPath();
      for (const g of scene.ghost) {
        ctx.moveTo(X(g.from[0]), Y(g.from[1]));
        ctx.lineTo(X(g.to[0]), Y(g.to[1]));
      }
      ctx.stroke();
      ctx.restore();
    }

    // Strokes: consecutive segments that share a style are joined into one path.
    const segs = scene.segments;
    const total = scene.count + (scene.tip ? 1 : 0);
    let open = false;
    let last: Segment | null = null;
    for (let i = 0; i < total; i++) {
      const g = i < scene.count ? segs[i] : scene.tip!;
      const joined =
        last !== null &&
        last.color === g.color &&
        last.width === g.width &&
        last.to[0] === g.from[0] &&
        last.to[1] === g.from[1];
      if (!joined) {
        if (open) ctx.stroke();
        ctx.beginPath();
        ctx.strokeStyle = g.color;
        ctx.lineWidth = Math.max(0.75, g.width * ls);
        ctx.moveTo(X(g.from[0]), Y(g.from[1]));
        open = true;
      }
      ctx.lineTo(X(g.to[0]), Y(g.to[1]));
      last = g;
    }
    if (open) ctx.stroke();

    if (opts.turtle && scene.turtle) {
      const t = scene.turtle;
      drawTurtle2D(ctx, X(t.pos[0]), Y(t.pos[1]), Math.atan2(t.heading[0], t.heading[1]), t, pal);
    }
  }
}

function drawTurtle2D(
  ctx: CanvasRenderingContext2D,
  x: number,
  y: number,
  angle: number,
  t: TurtleState,
  pal: Palette,
) {
  ctx.save();
  ctx.translate(x, y);
  ctx.rotate(angle);
  ctx.lineWidth = 1.5;
  ctx.strokeStyle = pal.shellEdge;
  ctx.fillStyle = pal.skin;
  const blob = (cx: number, cy: number, rx: number, ry: number, rot = 0) => {
    ctx.beginPath();
    ctx.ellipse(cx, cy, rx, ry, rot, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();
  };
  // Legs, tail, head (the turtle points up: -y).
  blob(-8.5, -6.5, 3, 4.4, -0.7);
  blob(8.5, -6.5, 3, 4.4, 0.7);
  blob(-8.5, 7, 3, 4.4, 0.7);
  blob(8.5, 7, 3, 4.4, -0.7);
  ctx.beginPath();
  ctx.moveTo(-2, 10);
  ctx.lineTo(0, 15.5);
  ctx.lineTo(2, 10);
  ctx.fill();
  ctx.stroke();
  blob(0, -13.5, 4, 4.8);
  // Shell.
  ctx.fillStyle = pal.shell;
  blob(0, 0, 9.5, 11.5);
  // The pen: a dot in the pen colour, hollow when the pen is up.
  ctx.beginPath();
  ctx.arc(0, 0, 3.6, 0, Math.PI * 2);
  ctx.fillStyle = t.penDown ? t.color : pal.paper;
  ctx.fill();
  ctx.strokeStyle = t.penDown ? pal.paper : pal.shellEdge;
  ctx.lineWidth = 1.5;
  ctx.stroke();
  ctx.restore();
}

// ---------------------------------------------------------------- 3D

const FOV = (38 * Math.PI) / 180;
const DEF_AZ = (-32 * Math.PI) / 180;
const DEF_EL = (24 * Math.PI) / 180;

interface Cam {
  c: Vec3;
  f: Vec3;
  r: Vec3;
  u: Vec3;
  focal: number;
  w: number;
  h: number;
}

type P3 = [number, number, number]; // camera space: x right, y up, z depth

export class View3D implements View {
  auto = true;
  az = DEF_AZ;
  el = DEF_EL;
  dist = 520;
  target: Vec3 = [0, 0, 0];

  reset() {
    this.az = DEF_AZ;
    this.el = DEF_EL;
    this.dist = 520;
    this.target = [0, 0, 0];
    this.auto = true;
  }

  private cam(w: number, h: number): Cam {
    const ce = Math.cos(this.el);
    const se = Math.sin(this.el);
    const sa = Math.sin(this.az);
    const ca = Math.cos(this.az);
    const f: Vec3 = [sa * ce, ca * ce, -se];
    const r: Vec3 = [ca, -sa, 0];
    const u: Vec3 = [r[1] * f[2] - r[2] * f[1], r[2] * f[0] - r[0] * f[2], r[0] * f[1] - r[1] * f[0]];
    const t = this.target;
    const c: Vec3 = [t[0] - f[0] * this.dist, t[1] - f[1] * this.dist, t[2] - f[2] * this.dist];
    return { c, f, r, u, focal: h / 2 / Math.tan(FOV / 2), w, h };
  }

  private toCam(cam: Cam, p: Vec3): P3 {
    const x = p[0] - cam.c[0];
    const y = p[1] - cam.c[1];
    const z = p[2] - cam.c[2];
    return [
      x * cam.r[0] + y * cam.r[1] + z * cam.r[2],
      x * cam.u[0] + y * cam.u[1] + z * cam.u[2],
      x * cam.f[0] + y * cam.f[1] + z * cam.f[2],
    ];
  }

  fit(b: Bounds, w: number, h: number) {
    const cx = (b.min[0] + b.max[0]) / 2;
    const cy = (b.min[1] + b.max[1]) / 2;
    const cz = (b.min[2] + b.max[2]) / 2;
    const dx = b.max[0] - b.min[0];
    const dy = b.max[1] - b.min[1];
    const dz = b.max[2] - b.min[2];
    const radius = Math.max(30, Math.sqrt(dx * dx + dy * dy + dz * dz) / 2);
    const fovX = 2 * Math.atan(Math.tan(FOV / 2) * (w / Math.max(1, h)));
    const half = Math.min(FOV, fovX) / 2;
    this.target = [cx, cy, cz];
    this.dist = (radius / Math.sin(half)) * 1.12;
  }

  ensure(b: Bounds, w: number, h: number) {
    const cam = this.cam(w, h);
    const m = 14;
    let out = false;
    for (let i = 0; i < 8 && !out; i++) {
      const p: Vec3 = [i & 1 ? b.max[0] : b.min[0], i & 2 ? b.max[1] : b.min[1], i & 4 ? b.max[2] : b.min[2]];
      const q = this.toCam(cam, p);
      if (q[2] < 1) out = true;
      else {
        const sx = w / 2 + (cam.focal * q[0]) / q[2];
        const sy = h / 2 - (cam.focal * q[1]) / q[2];
        if (sx < m || sy < m || sx > w - m || sy > h - m) out = true;
      }
    }
    if (out) {
      const old = this.dist;
      this.fit(b, w, h);
      if (this.dist > old) this.dist *= 1.1;
    }
  }

  zoomBy(f: number) {
    this.dist = clamp(this.dist / f, 5, 2e6);
    this.auto = false;
  }

  drag(dx: number, dy: number, alt: boolean, w: number, h: number) {
    if (alt) {
      const cam = this.cam(w, h);
      const k = this.dist / cam.focal;
      for (let i = 0; i < 3; i++) this.target[i] += (-dx * cam.r[i] + dy * cam.u[i]) * k;
    } else {
      this.az += dx * 0.008;
      this.el = clamp(this.el + dy * 0.008, (-89 * Math.PI) / 180, (89 * Math.PI) / 180);
    }
    this.auto = false;
  }

  key(dx: number, dy: number, alt: boolean, w: number, h: number) {
    if (alt) this.drag(-dx * 30, -dy * 30, true, w, h);
    else this.drag(dx * 12, dy * 12, false, w, h);
  }

  draw(ctx: CanvasRenderingContext2D, w: number, h: number, scene: Scene, pal: Palette, opts: DrawOpts) {
    const cam = this.cam(w, h);
    const NEAR = Math.max(0.5, this.dist * 0.01);
    ctx.fillStyle = pal.paper;
    ctx.fillRect(0, 0, w, h);
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';

    /** Projects a world segment, clipped at the near plane. */
    const proj = (a: Vec3, b: Vec3): [number, number, number, number, number] | null => {
      let p = this.toCam(cam, a);
      let q = this.toCam(cam, b);
      if (p[2] < NEAR && q[2] < NEAR) return null;
      if (p[2] < NEAR) {
        const t = (NEAR - p[2]) / (q[2] - p[2]);
        p = [p[0] + (q[0] - p[0]) * t, p[1] + (q[1] - p[1]) * t, NEAR];
      } else if (q[2] < NEAR) {
        const t = (NEAR - q[2]) / (p[2] - q[2]);
        q = [q[0] + (p[0] - q[0]) * t, q[1] + (p[1] - q[1]) * t, NEAR];
      }
      return [
        w / 2 + (cam.focal * p[0]) / p[2],
        h / 2 - (cam.focal * p[1]) / p[2],
        w / 2 + (cam.focal * q[0]) / q[2],
        h / 2 - (cam.focal * q[1]) / q[2],
        (p[2] + q[2]) / 2,
      ];
    };
    const line = (a: Vec3, b: Vec3) => {
      const l = proj(a, b);
      if (!l) return;
      ctx.moveTo(l[0], l[1]);
      ctx.lineTo(l[2], l[3]);
    };

    // Ground grid on the plane z = 0, sized to the drawing.
    const bb = sceneBounds(scene);
    const reach = Math.max(
      150,
      Math.abs(bb.min[0]),
      Math.abs(bb.max[0]),
      Math.abs(bb.min[1]),
      Math.abs(bb.max[1]),
      Math.abs(bb.min[2]),
      Math.abs(bb.max[2]),
    );
    const step = niceStep(reach / 6);
    const half = Math.ceil((reach * 1.15) / step) * step;
    const n = Math.round(half / step);
    for (const [every, color] of [
      [1, pal.grid],
      [5, pal.gridStrong],
    ] as [number, string][]) {
      ctx.beginPath();
      for (let i = -n; i <= n; i++) {
        if (i === 0 || (every === 1 ? i % 5 === 0 : i % 5 !== 0)) continue;
        line([i * step, -half, 0], [i * step, half, 0]);
        line([-half, i * step, 0], [half, i * step, 0]);
      }
      ctx.strokeStyle = color;
      ctx.lineWidth = 1;
      ctx.stroke();
    }
    ctx.beginPath();
    line([-half, -half, 0], [half, -half, 0]);
    line([half, -half, 0], [half, half, 0]);
    line([half, half, 0], [-half, half, 0]);
    line([-half, half, 0], [-half, -half, 0]);
    line([-half, 0, 0], [0, 0, 0]);
    line([0, -half, 0], [0, 0, 0]);
    ctx.strokeStyle = pal.gridStrong;
    ctx.lineWidth = 1;
    ctx.stroke();

    // Axes: X, Y on the ground, Z up.
    const axisLen = half;
    const axes: [Vec3, string, string][] = [
      [[axisLen, 0, 0], pal.axisX, 'x'],
      [[0, axisLen, 0], pal.axisY, 'y'],
      [[0, 0, axisLen * 0.6], pal.axisZ, 'z'],
    ];
    ctx.font = '700 12px ui-monospace, Menlo, Consolas, monospace';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    for (const [end, color, label] of axes) {
      ctx.beginPath();
      line([0, 0, 0], end);
      ctx.strokeStyle = color;
      ctx.lineWidth = 1.75;
      ctx.stroke();
      const q = this.toCam(cam, [end[0] * 1.06, end[1] * 1.06, end[2] * 1.08]);
      if (q[2] > NEAR) {
        ctx.fillStyle = color;
        ctx.fillText(label, w / 2 + (cam.focal * q[0]) / q[2], h / 2 - (cam.focal * q[1]) / q[2]);
      }
    }
    const o = this.toCam(cam, [0, 0, 0]);
    if (o[2] > NEAR) {
      ctx.beginPath();
      ctx.arc(w / 2 + (cam.focal * o[0]) / o[2], h / 2 - (cam.focal * o[1]) / o[2], 3.5, 0, Math.PI * 2);
      ctx.fillStyle = pal.paper;
      ctx.fill();
      ctx.strokeStyle = pal.axis;
      ctx.lineWidth = 1.5;
      ctx.stroke();
    }

    if (scene.ghost) {
      ctx.beginPath();
      for (const g of scene.ghost) line(g.from, g.to);
      ctx.strokeStyle = pal.ghost;
      ctx.lineWidth = 7;
      ctx.stroke();
    }

    // Strokes, painted far to near.
    const total = scene.count + (scene.tip ? 1 : 0);
    const items: { l: [number, number, number, number, number]; g: Segment }[] = [];
    for (let i = 0; i < total; i++) {
      const g = i < scene.count ? scene.segments[i] : scene.tip!;
      const l = proj(g.from, g.to);
      if (l) items.push({ l, g });
    }
    items.sort((a, b) => b.l[4] - a.l[4]);
    let color = '';
    let lw = -1;
    let open = false;
    for (const it of items) {
      const width = Math.max(0.75, it.g.width * lineScale(cam.focal / it.l[4]));
      const q = Math.round(width * 4) / 4;
      if (it.g.color !== color || q !== lw) {
        if (open) ctx.stroke();
        ctx.beginPath();
        color = it.g.color;
        lw = q;
        ctx.strokeStyle = color;
        ctx.lineWidth = q;
        open = true;
      }
      ctx.moveTo(it.l[0], it.l[1]);
      ctx.lineTo(it.l[2], it.l[3]);
    }
    if (open) ctx.stroke();

    if (opts.turtle && scene.turtle) this.drawTurtle(ctx, cam, scene.turtle, pal, NEAR);
  }

  private drawTurtle(ctx: CanvasRenderingContext2D, cam: Cam, t: TurtleState, pal: Palette, near: number) {
    const centre = this.toCam(cam, t.pos);
    if (centre[2] < near * 2) return;
    // Constant size on screen.
    const s = (13 * centre[2]) / cam.focal;
    const at = (a: number, b: number, c: number): [number, number] => {
      const p: Vec3 = [
        t.pos[0] + (t.heading[0] * a + t.right[0] * b + t.up[0] * c) * s,
        t.pos[1] + (t.heading[1] * a + t.right[1] * b + t.up[1] * c) * s,
        t.pos[2] + (t.heading[2] * a + t.right[2] * b + t.up[2] * c) * s,
      ];
      const q = this.toCam(cam, p);
      const zz = Math.max(q[2], near);
      return [cam.w / 2 + (cam.focal * q[0]) / zz, cam.h / 2 - (cam.focal * q[1]) / zz];
    };
    const path = (pts: [number, number][], close = true) => {
      ctx.beginPath();
      pts.forEach((p, i) => (i ? ctx.lineTo(p[0], p[1]) : ctx.moveTo(p[0], p[1])));
      if (close) ctx.closePath();
    };
    const ring = (ca: number, cb: number, ra: number, rb: number) => {
      const pts: [number, number][] = [];
      for (let i = 0; i < 20; i++) {
        const a = (i / 20) * Math.PI * 2;
        pts.push(at(ca + Math.cos(a) * ra, cb + Math.sin(a) * rb, 0));
      }
      return pts;
    };
    ctx.lineWidth = 1.5;
    ctx.strokeStyle = pal.shellEdge;
    ctx.fillStyle = pal.skin;
    for (const [a, b] of [
      [0.62, -0.72],
      [0.62, 0.72],
      [-0.62, -0.72],
      [-0.62, 0.72],
    ]) {
      path(ring(a, b, 0.34, 0.27));
      ctx.fill();
      ctx.stroke();
    }
    path(ring(1.22, 0, 0.36, 0.3));
    ctx.fill();
    ctx.stroke();
    path([at(-0.85, -0.15, 0), at(-1.3, 0, 0), at(-0.85, 0.15, 0)]);
    ctx.fill();
    ctx.stroke();
    // Shell: a flat base with a dome towards the turtle's up vector.
    ctx.fillStyle = pal.shell;
    path(ring(0, 0, 0.95, 0.78));
    ctx.fill();
    ctx.stroke();
    const dome: [number, number][] = [];
    for (let i = 0; i <= 12; i++) {
      const a = (i / 12) * Math.PI;
      dome.push(at(Math.cos(a) * 0.95, 0, Math.sin(a) * 0.62));
    }
    path(dome, true);
    ctx.globalAlpha = 0.85;
    ctx.fill();
    ctx.globalAlpha = 1;
    ctx.stroke();
    const dome2: [number, number][] = [];
    for (let i = 0; i <= 12; i++) {
      const a = (i / 12) * Math.PI;
      dome2.push(at(0, Math.cos(a) * 0.78, Math.sin(a) * 0.62));
    }
    path(dome2, true);
    ctx.globalAlpha = 0.85;
    ctx.fill();
    ctx.globalAlpha = 1;
    ctx.stroke();
    // Pen dot on top of the shell.
    const top = at(0, 0, 0.62);
    ctx.beginPath();
    ctx.arc(top[0], top[1], 3.2, 0, Math.PI * 2);
    ctx.fillStyle = t.penDown ? t.color : pal.paper;
    ctx.fill();
    ctx.strokeStyle = t.penDown ? pal.paper : pal.shellEdge;
    ctx.stroke();
  }
}

