const targets = new Map<string, Segment[]>();

export function targetOf(ch: Challenge): Segment[] {
  let t = targets.get(ch.id);
  if (!t) {
    t = run(ch.solution, ch.mode).segments;
    targets.set(ch.id, t);
  }
  return t;
}

const NEED_TEXT: Record<string, string> = {
