// Static SVG previews of drawings (examples, challenges, reference).
import type { Segment, Vec3 } from '../lang/interp';
import type { Mode } from '../lang/tokens';

const AZ = (-32 * Math.PI) / 180;
const EL = (24 * Math.PI) / 180;

/** Orthographic projection matching the default 3D camera. */
function project(p: Vec3): [number, number, number] {
  const ce = Math.cos(EL);
  const se = Math.sin(EL);
  const sa = Math.sin(AZ);
  const ca = Math.cos(AZ);
  const f: Vec3 = [sa * ce, ca * ce, -se];
  const r: Vec3 = [ca, -sa, 0];
  const u: Vec3 = [r[1] * f[2] - r[2] * f[1], r[2] * f[0] - r[0] * f[2], r[0] * f[1] - r[1] * f[0]];
  return [
    p[0] * r[0] + p[1] * r[1] + p[2] * r[2],
    p[0] * u[0] + p[1] * u[1] + p[2] * u[2],
    p[0] * f[0] + p[1] * f[1] + p[2] * f[2],
  ];
}

export function thumbSvg(
  segments: Segment[],
  mode: Mode,
  opts: { size?: number; ghost?: boolean; label?: string } = {},
): string {
  const size = opts.size ?? 160;
  const lines: { a: [number, number]; b: [number, number]; d: number; s: Segment }[] = [];
  for (const s of segments) {
    if (mode === '3d') {
      const a = project(s.from);
      const b = project(s.to);
      lines.push({ a: [a[0], -a[1]], b: [b[0], -b[1]], d: (a[2] + b[2]) / 2, s });
    } else {
      lines.push({ a: [s.from[0], -s.from[1]], b: [s.to[0], -s.to[1]], d: 0, s });
    }
  }
  if (mode === '3d') lines.sort((x, y) => y.d - x.d);
  let x0 = Infinity;
  let y0 = Infinity;
  let x1 = -Infinity;
  let y1 = -Infinity;
  for (const l of lines) {
    for (const p of [l.a, l.b]) {
      x0 = Math.min(x0, p[0]);
      y0 = Math.min(y0, p[1]);
      x1 = Math.max(x1, p[0]);
      y1 = Math.max(y1, p[1]);
    }
  }
  if (!lines.length) {
    x0 = y0 = -1;
    x1 = y1 = 1;
  }
  const span = Math.max(x1 - x0, y1 - y0, 1e-6);
  const pad = 14;
  const k = (size - pad * 2) / span;
  const ox = (size - (x1 - x0) * k) / 2 - x0 * k;
  const oy = (size - (y1 - y0) * k) / 2 - y0 * k;
  const f = (v: number) => (Math.round(v * 100) / 100).toString();
  let body = '';
  for (const l of lines) {
    const w = opts.ghost ? 5 : Math.max(1, Math.min(3.2, l.s.width * 0.75));
    body += `<line x1="${f(l.a[0] * k + ox)}" y1="${f(l.a[1] * k + oy)}" x2="${f(l.b[0] * k + ox)}" y2="${f(l.b[1] * k + oy)}" stroke="${opts.ghost ? 'var(--ghost-solid)' : l.s.color}" stroke-width="${f(w)}"/>`;
  }
  const label = opts.label ? ` role="img" aria-label="${opts.label.replace(/"/g, '&quot;')}"` : ' aria-hidden="true"';
  return `<svg class="thumb" viewBox="0 0 ${size} ${size}" width="${size}" height="${size}" fill="none" stroke-linecap="round"${label} focusable="false">${body}</svg>`;
}
