// Compares a drawing with the expected one, ignoring stroke order, direction,
// colour and how lines are split into segments.
import type { Segment, Vec3 } from './lang/interp';

export interface CheckResult {
  pass: boolean;
  /** Share of the target trace covered by the drawing (0–1). */
  covered: number;
  /** Share of the drawing lying off the target trace (0–1). */
  extra: number;
  reason: string;
}

export const TOLERANCE = 2.5;

function dist2ToSegment(p: Vec3, s: Segment): number {
  const ax = s.from[0];
  const ay = s.from[1];
  const az = s.from[2];
  const dx = s.to[0] - ax;
  const dy = s.to[1] - ay;
  const dz = s.to[2] - az;
  const len2 = dx * dx + dy * dy + dz * dz;
  let t = len2 === 0 ? 0 : ((p[0] - ax) * dx + (p[1] - ay) * dy + (p[2] - az) * dz) / len2;
  t = t < 0 ? 0 : t > 1 ? 1 : t;
  const x = ax + dx * t - p[0];
  const y = ay + dy * t - p[1];
  const zz = az + dz * t - p[2];
  return x * x + y * y + zz * zz;
}

function samples(segs: Segment[], maxPoints = 3000): Vec3[] {
  let total = 0;
  for (const s of segs) total += Math.hypot(s.to[0] - s.from[0], s.to[1] - s.from[1], s.to[2] - s.from[2]);
  const step = Math.max(1.5, total / maxPoints);
  const pts: Vec3[] = [];
  for (const s of segs) {
    const len = Math.hypot(s.to[0] - s.from[0], s.to[1] - s.from[1], s.to[2] - s.from[2]);
    const n = Math.max(1, Math.ceil(len / step));
    for (let i = 0; i <= n; i++) {
      const t = i / n;
      pts.push([
        s.from[0] + (s.to[0] - s.from[0]) * t,
        s.from[1] + (s.to[1] - s.from[1]) * t,
        s.from[2] + (s.to[2] - s.from[2]) * t,
      ]);
    }
  }
  return pts;
}

/** Share of the points lying further than `tol` from every segment. */
function missShare(points: Vec3[], segs: Segment[], tol: number): number {
  if (!points.length) return 0;
  const tol2 = tol * tol;
  const boxes = segs.map((s) => [
    Math.min(s.from[0], s.to[0]) - tol,
    Math.max(s.from[0], s.to[0]) + tol,
    Math.min(s.from[1], s.to[1]) - tol,
    Math.max(s.from[1], s.to[1]) + tol,
    Math.min(s.from[2], s.to[2]) - tol,
    Math.max(s.from[2], s.to[2]) + tol,
  ]);
  let miss = 0;
  let hint = 0;
  for (const p of points) {
    let ok = false;
    // Neighbouring samples usually hit the same segment: try it first.
    for (let k = 0; k < segs.length; k++) {
      const i = (hint + k) % segs.length;
      const b = boxes[i];
      if (p[0] < b[0] || p[0] > b[1] || p[1] < b[2] || p[1] > b[3] || p[2] < b[4] || p[2] > b[5]) continue;
      if (dist2ToSegment(p, segs[i]) <= tol2) {
        ok = true;
        hint = i;
        break;
      }
    }
    if (!ok) miss++;
  }
  return miss / points.length;
}

export function checkDrawing(user: Segment[], target: Segment[], tol = TOLERANCE): CheckResult {
  if (user.length === 0) {
    return { pass: false, covered: 0, extra: 0, reason: 'Żółw niczego nie narysował. Sprawdź, czy pióro jest opuszczone.' };
  }
  const missing = missShare(samples(target), user, tol);
  const extra = missShare(samples(user), target, tol);
  const covered = 1 - missing;
  const pct = (v: number) => `${Math.max(1, Math.min(99, Math.round(v * 100)))}%`;
  if (missing <= 0.004 && extra <= 0.004) {
    return { pass: true, covered, extra, reason: 'Rysunek zgadza się ze wzorem.' };
  }
  let reason: string;
  if (missing > 0.004 && extra > 0.004) {
    reason =
      covered < 0.05
        ? 'Rysunek nie pokrywa się ze wzorem. Zacznij od środka i rysuj po szarym śladzie.'
        : `Jeszcze nie: pokrywasz ${pct(covered)} wzoru, a ${pct(extra)} Twoich linii leży poza nim.`;
  } else if (missing > 0.004) {
    reason = `Dobry kierunek, ale brakuje części wzoru: pokrywasz ${pct(covered)} szarego śladu.`;
  } else {
    reason = `Cały wzór jest pokryty, ale ${pct(extra)} Twoich linii wychodzi poza niego.`;
  }
  return { pass: false, covered, extra, reason };
}
