const NEED_TEXT: Record<string, string> = {
  repeat: 'polecenia „powtorz”',
  proc: 'własnej procedury (oto … już)',
  var: 'zmiennej (niech)',
  if: 'warunku (jeśli albo jeżeli)',
  penup: 'podnoszenia pióra (pod i opu)',
};

function uses(source: string): Set<string> {
  const found = new Set<string>();
  try {
    for (const t of tokenize(source)) {
      if (t.t !== 'word') continue;
      const kind: CmdKind | undefined = COMMANDS.get(t.name);
      if (kind === 'repeat') found.add('repeat');
      else if (kind === 'let') found.add('var');
      else if (kind === 'if' || kind === 'ifelse') found.add('if');
      else if (kind === 'pu') found.add('penup');
      else if (DEF_WORDS.has(t.name) && t.first) found.add('proc');
