    return {
      pass: false,
      covered: 0,
      extra: 0,
      reason: `Program zatrzymał się z błędem w wierszu ${res.error.line}: ${res.error.message}`,
      error: res.error,
      segments: res.segments,
    };
  }
  const check = checkDrawing(res.segments, targetOf(ch));
  if (check.pass && ch.needs) {
    const used = uses(source);
    const lacking = ch.needs.filter((n) => !used.has(n));
    if (lacking.length) {
      return {
        ...check,
        pass: false,
        reason: `Rysunek się zgadza, ale to wyzwanie wymaga użycia ${lacking.map((n) => NEED_TEXT[n]).join(' i ')}.`,
        error: null,
        segments: res.segments,
      };
    }
  }
  return { ...check, error: null, segments: res.segments };
}
