export function buildReference(onTry: (code: string, mode: Mode) => void): HTMLElement {
  const toc = h('nav', { class: 'ref-toc', 'aria-label': 'Spis treści' });
  const tocList = h('ul');
  toc.append(h('h2', null, 'Spis treści'), tocList);
  const body = h('div', { class: 'ref-body' });
  const jump = (id: string) => (e: Event) => {
    // In-page jumps must not disturb the hash router.
    e.preventDefault();
    const target = document.getElementById('ref-' + id);
    if (target) {
      target.scrollIntoView({ behavior: 'smooth', block: 'start' });
      target.focus({ preventScroll: true });
    }
  };
  const addToc = (id: string, title: string) => {
    tocList.append(h('li', null, h('a', { href: '#/polecenia', onclick: jump(id) }, title)));
  };
  for (const sec of SECTIONS) {
    addToc(sec.id, sec.title);
    const el = h('section', { class: 'ref-section', id: 'ref-' + sec.id, tabindex: '-1' });
    el.append(h('h2', null, sec.title), h('p', { class: 'ref-intro' }, sec.intro));
    if (sec.extra && sec.id !== 'procedury' && sec.id !== 'zmienne') el.append(h('div', { class: 'ref-extra', html: sec.extra }));
    for (const en of sec.entries ?? []) {
      const mode: Mode = en.mode ?? '2d';
      const res = run(en.code, mode);
      const card = h('article', { class: 'ref-card' });
      card.append(
        h(
          'div',
          { class: 'ref-card-text' },
          h('h3', null, en.names),
          h('p', { class: 'ref-arg' }, h('span', null, 'Argument: '), en.arg),
          h('p', null, en.text),
          h('pre', { class: 'code', html: highlightHtml(en.code), tabindex: '0', 'aria-label': 'Przykład' }),
          h(
            'button',
            { class: 'btn btn-small', type: 'button', onclick: () => onTry(en.code, mode) },
            icon('play'),
            mode === '3d' ? 'Wypróbuj w 3D' : 'Wypróbuj',
          ),
        ),
        h('div', {
          class: 'ref-card-thumb',
          html: thumbSvg(res.segments, mode, { size: 150, label: 'Wynik przykładu' }),
        }),
      );
      el.append(card);
    }
    if (sec.extra && (sec.id === 'procedury' || sec.id === 'zmienne')) el.append(h('div', { class: 'ref-extra', html: sec.extra }));
    body.append(el);
  }
  // Shortcuts.
  addToc('skroty', 'Skróty klawiszowe');
  const keys = h('section', { class: 'ref-section', id: 'ref-skroty', tabindex: '-1' }, h('h2', null, 'Skróty klawiszowe'));
  keys.append(shortcutTable());
  keys.append(
    h(
      'p',
      { class: 'ref-intro' },
      'Na komputerach Apple zamiast Ctrl możesz użyć klawisza ⌘. Rysunek przesuwasz myszą lub palcem, a powiększasz kółkiem albo gestem szczypania; w widoku 3D przeciąganie obraca kamerę, a przeciąganie z klawiszem Shift (albo dwoma palcami) ją przesuwa.',
    ),
  );
  body.append(keys);

  return h(
    'div',
    { class: 'ref' },
    h(
      'header',
      { class: 'page-head' },
      h('h1', null, 'Polecenia'),
      h(
        'p',
        null,
        'Cały język Logomocji na jednej stronie. Polecenia mają polskie i angielskie nazwy, które znaczą to samo; wielkość liter i polskie ogonki w słowach języka nie mają znaczenia.',
      ),
    ),
    h('div', { class: 'ref-layout' }, toc, body),
  );
}

export function shortcutTable(): HTMLElement {
  const tbody = h('tbody');
  for (const [k, d] of SHORTCUTS) {
    const cell = h('th', { scope: 'row' });
    k.split(' + ').forEach((part, i) => {
      if (i) cell.append(' + ');
      cell.append(h('kbd', null, part));
    });
    tbody.append(h('tr', null, cell, h('td', null, d)));
  }
  return h('table', { class: 'ref-table keys' }, h('caption', null, 'Skróty klawiszowe'), tbody);
}

