// The workspace: editor, stage (canvas), execution controls, files and sharing.
import { judge, targetOf, type Challenge } from '../challenges';
import { EXAMPLES } from '../examples';
import {
  Machine,
  copySegments,
  run as runProgram,
  toErrorInfo,
  type LogoErrorInfo,
  type RunResult,
  type Segment,
  type Vec3,
} from '../lang/interp';
import { parse } from '../lang/parser';
import { COMMANDS, ONLY_3D, tokenize, type Mode, type Tok } from '../lang/tokens';
import { download, h, icon, openDialog, toast } from './dom';
import { Editor } from './editor';
import { shortcutTable } from './reference';
import * as store from './store';
import { thumbSvg } from './thumb';
import { View2D, View3D, sceneBounds, type Palette, type Scene, type TurtleState, type View } from './views';

export type Context = { kind: 'free'; mode: Mode } | { kind: 'challenge'; ch: Challenge };
type RunState = 'idle' | 'running' | 'paused' | 'done' | 'error';

interface Anim {
  from: Vec3;
  to: Vec3;
  seg: Segment | null;
  dur: number;
  t: number;
}

const SPEEDS = [
  { name: 'Powoli', move: 80, op: 350 },
  { name: 'Spokojnie', move: 200, op: 150 },
  { name: 'Normalnie', move: 500, op: 60 },
  { name: 'Szybko', move: 1500, op: 16 },
  { name: 'Bardzo szybko', move: 6000, op: 3 },
  { name: 'Od razu', move: Infinity, op: 0 },
];

const HOME: TurtleState = {
  pos: [0, 0, 0],
  heading: [0, 1, 0],
  up: [0, 0, 1],
  right: [1, 0, 0],
  penDown: true,
  color: '#16866a',
};

const DEFAULT_DRAFT: Record<Mode, string> = {
  '2d': EXAMPLES.find((e) => e.id === 'kwadrat')!.source,
  '3d': EXAMPLES.find((e) => e.id === 'schody')!.source,
};

export function uses3d(source: string): boolean {
  try {
    return tokenize(source).some((t) => t.t === 'word' && ONLY_3D.has(COMMANDS.get(t.name)!));
  } catch {
    return false;
  }
}

export function encodeProgram(source: string): string {
  const bytes = new TextEncoder().encode(source);
  let bin = '';
  for (let i = 0; i < bytes.length; i++) bin += String.fromCharCode(bytes[i]);
  return btoa(bin).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

export function decodeProgram(data: string): string | null {
  try {
    const b64 = data.replace(/-/g, '+').replace(/_/g, '/');
    const bin = atob(b64 + '='.repeat((4 - (b64.length % 4)) % 4));
    const bytes = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
    return new TextDecoder('utf-8', { fatal: true }).decode(bytes);
  } catch {
    return null;
  }
}

export class Studio {
  el: HTMLElement;
  editor: Editor;
  context: Context = { kind: 'free', mode: '2d' };
  /** Called when a program was loaded into the free workspace of a mode. */
  onGoFree: (mode: Mode) => void = () => {};
  onSolved: () => void = () => {};
  visible = false;

  private canvas: HTMLCanvasElement;
  private ctx: CanvasRenderingContext2D;
  private views: Record<Mode, View> = { '2d': new View2D(), '3d': new View3D() };
  private palette: Palette | null = null;
  private w = 0;
  private h = 0;
  private dpr = 1;
  private drawQueued = false;

  private state: RunState = 'idle';
  private machine: Machine | null = null;
  private iter: Generator<Tok, void, void> | null = null;
  private pending: IteratorResult<Tok, void> | null = null;
  private anim: Anim | null = null;
  private budget = 0;
  private lastFrame = 0;
  private raf = 0;
  private speed = 3;
  private lastError: LogoErrorInfo | null = null;
  private ghost: Segment[] | null = null;
  private finalSegments: Segment[] = [];
  private finalTurtle: TurtleState = HOME;

  private statusEl!: HTMLElement;
  private errorEl!: HTMLElement;
  private readoutEl!: HTMLElement;
  private btnRun!: HTMLButtonElement;
  private btnStep!: HTMLButtonElement;
  private btnPause!: HTMLButtonElement;
  private btnReset!: HTMLButtonElement;
  private btnCam!: HTMLButtonElement;
  private mode2!: HTMLButtonElement;
  private mode3!: HTMLButtonElement;
  private modeBox!: HTMLElement;
  private speedOut!: HTMLElement;
  private chBar!: HTMLElement;
  private stageNote!: HTMLElement;
  private fileInput!: HTMLInputElement;

  get mode(): Mode {
    return this.context.kind === 'free' ? this.context.mode : this.context.ch.mode;
  }

  private get view(): View {
    return this.views[this.mode];
  }

  constructor() {
    this.speed = Math.min(6, Math.max(1, Number(store.load('speed')) || 3));
    this.editor = new Editor('Edytor programu Logo', 'run-error');
    this.editor.onChange = (v) => this.onEdit(v);
    this.canvas = h('canvas', {
      class: 'stage-canvas',
      tabindex: '0',
      role: 'img',
      'aria-label': 'Rysunek żółwia',
      'aria-describedby': 'stage-help',
    });
    this.ctx = this.canvas.getContext('2d')!;
    this.el = this.build();
    this.bindCanvas();
    if (typeof ResizeObserver !== 'undefined') {
      new ResizeObserver(() => this.resize()).observe(this.canvas.parentElement!);
    } else {
      window.addEventListener('resize', () => this.resize());
    }
  }

  // ------------------------------------------------------------ layout

  private build(): HTMLElement {
    const btn = (label: string, ic: string, onclick: () => void, extra: Record<string, unknown> = {}) =>
      h('button', { class: 'btn', type: 'button', onclick, ...extra }, icon(ic), h('span', { class: 'btn-label' }, label));
    const iconBtn = (label: string, ic: string, onclick: () => void) =>
      h('button', { class: 'icon-btn', type: 'button', title: label, 'aria-label': label, onclick }, icon(ic));

    this.mode2 = h('button', { type: 'button', class: 'seg', onclick: () => this.switchMode('2d'), title: 'Tryb 2D: płaszczyzna' }, '2D');
    this.mode3 = h('button', { type: 'button', class: 'seg', onclick: () => this.switchMode('3d'), title: 'Tryb 3D: przestrzeń' }, '3D');
    this.modeBox = h('div', { class: 'segmented', role: 'group', 'aria-label': 'Tryb rysowania' }, this.mode2, this.mode3);

    this.fileInput = h('input', {
      type: 'file',
      accept: '.logo,.lgo,.txt,text/plain',
      class: 'visually-hidden',
      tabindex: '-1',
      'aria-hidden': 'true',
      onchange: () => this.onFile(),
    });

    const toolbar = h(
      'div',
      { class: 'toolbar', role: 'toolbar', 'aria-label': 'Program' },
      this.modeBox,
      btn('Przykłady', 'grid', () => this.openExamples(), { title: 'Wczytaj jeden z gotowych programów' }),
      h('span', { class: 'toolbar-gap' }),
      btn('Otwórz', 'open', () => this.fileInput.click(), { title: 'Otwórz plik .logo z dysku' }),
      btn('Zapisz', 'save', () => this.saveFile(), { title: 'Pobierz program jako plik .logo' }),
      btn('Udostępnij', 'link', () => this.share(), { title: 'Utwórz link do programu' }),
      this.fileInput,
    );

    this.statusEl = h('p', { class: 'status', id: 'run-status', role: 'status', 'aria-live': 'polite' });
    this.errorEl = h('div', { class: 'error-box', id: 'run-error', role: 'alert', hidden: true });

    const codePane = h(
      'div',
      { class: 'pane pane-code' },
      toolbar,
      this.editor.el,
      h('div', { class: 'messages' }, this.errorEl, this.statusEl),
    );

    this.btnRun = btn('Uruchom', 'play', () => this.run(), { class: 'btn btn-primary', title: 'Uruchom (Ctrl + Enter)' }) as HTMLButtonElement;
    this.btnStep = btn('Krok', 'step', () => this.step(), { title: 'Wykonaj jedno polecenie (Alt + Enter)' }) as HTMLButtonElement;
    this.btnPause = btn('Pauza', 'pause', () => this.pause(), { title: 'Wstrzymaj (Esc)' }) as HTMLButtonElement;
    this.btnReset = btn('Reset', 'reset', () => this.reset(), { title: 'Wyczyść rysunek (Ctrl + Shift + Backspace)' }) as HTMLButtonElement;

    this.speedOut = h('output', { class: 'speed-out', for: 'speed' });
    const speed = h('input', {
      type: 'range',
      id: 'speed',
      min: '1',
      max: '6',
      step: '1',
      value: String(this.speed),
      oninput: (e: Event) => {
        this.speed = Number((e.target as HTMLInputElement).value);
        store.save('speed', String(this.speed));
        this.showSpeed(e.target as HTMLInputElement);
      },
    });
    this.showSpeed(speed);

    const transport = h(
      'div',
      { class: 'transport', role: 'toolbar', 'aria-label': 'Wykonanie programu' },
      this.btnRun,
      this.btnStep,
      this.btnPause,
      this.btnReset,
      h('div', { class: 'speed' }, h('label', { for: 'speed' }, 'Tempo'), speed, this.speedOut),
      h(
        'button',
        { class: 'icon-btn', type: 'button', title: 'Skróty klawiszowe', 'aria-label': 'Skróty klawiszowe', onclick: () => this.showShortcuts() },
        icon('keys'),
      ),
    );

    this.btnCam = iconBtn('Ustaw kamerę od nowa', 'camera', () => {
      this.view.reset();
      this.fit();
    }) as HTMLButtonElement;
    this.readoutEl = h('div', { class: 'readout', 'aria-hidden': 'true' });
    this.stageNote = h('div', { class: 'stage-note', hidden: true });
    const stage = h(
      'div',
      { class: 'stage' },
      this.canvas,
      h(
        'p',
        { id: 'stage-help', class: 'visually-hidden' },
        'Widok rysunku. Strzałki przesuwają widok (w 3D obracają kamerę, z Shift przesuwają), plus i minus zmieniają powiększenie, zero dopasowuje widok do rysunku.',
      ),
      this.stageNote,
      this.readoutEl,
      h(
        'div',
        { class: 'stage-tools', role: 'toolbar', 'aria-label': 'Widok' },
        iconBtn('Dopasuj widok do rysunku', 'fit', () => this.fit()),
        iconBtn('Powiększ', 'plus', () => this.zoom(1.3)),
        iconBtn('Pomniejsz', 'minus', () => this.zoom(1 / 1.3)),
        this.btnCam,
        iconBtn('Zapisz rysunek jako PNG', 'image', () => this.exportPng()),
      ),
    );

    this.chBar = h('div', { class: 'challenge-bar', hidden: true });

    return h(
      'div',
      { class: 'studio' },
      h('h1', { class: 'visually-hidden', id: 'studio-title', tabindex: '-1' }, 'Pracownia'),
      this.chBar,
      h('div', { class: 'studio-grid' }, codePane, h('div', { class: 'pane pane-stage' }, stage, transport)),
    );
  }

  private showSpeed(input: HTMLInputElement) {
    const name = SPEEDS[this.speed - 1].name;
    this.speedOut.textContent = name;
    input.setAttribute('aria-valuetext', name);
  }

  private showShortcuts() {
    openDialog('Skróty klawiszowe', h('div', null, shortcutTable(), h('p', { class: 'muted' }, 'Na komputerach Apple zamiast Ctrl działa także ⌘.')));
  }

  // ------------------------------------------------------------ context and drafts

  private draftKey(ctx: Context = this.context): string {
    return ctx.kind === 'free' ? `draft:${ctx.mode}` : `challenge:${ctx.ch.id}`;
  }

  static draftOf(mode: Mode): string {
    return store.load(`draft:${mode}`) ?? DEFAULT_DRAFT[mode];
  }

  /** True when the free draft of a mode holds work that exists nowhere else. */
  static isDirty(mode: Mode): boolean {
    const draft = Studio.draftOf(mode);
    if (draft.trim() === '') return false;
    const base = store.load(`base:${mode}`) ?? DEFAULT_DRAFT[mode];
    if (draft === base) return false;
    return !EXAMPLES.some((e) => e.source === draft);
  }

  setContext(ctx: Context, opts: { run?: boolean } = {}) {
    this.halt();
    this.context = ctx;
    const text =
      ctx.kind === 'free' ? Studio.draftOf(ctx.mode) : (store.load(this.draftKey(ctx)) ?? ctx.ch.starter);
    if (ctx.kind === 'free') store.save('mode', ctx.mode);
    this.editor.setValue(text);
    this.ghost = ctx.kind === 'challenge' ? targetOf(ctx.ch) : null;
    this.mode2.setAttribute('aria-pressed', String(this.mode === '2d'));
    this.mode3.setAttribute('aria-pressed', String(this.mode === '3d'));
    this.modeBox.hidden = ctx.kind === 'challenge';
    this.btnCam.hidden = this.mode !== '3d';
    this.stageNote.hidden = true;
    this.renderChallengeBar();
    this.clearRun();
    this.view.reset();
    if (ctx.kind === 'free' && opts.run !== false && text.trim() !== '') {
      // Show the finished drawing of the stored draft straight away.
      const res = runProgram(text, ctx.mode);
      if (!res.error) this.runInstant();
    }
    this.fit();
  }

  private switchMode(mode: Mode) {
    if (this.context.kind !== 'free' || this.context.mode === mode) return;
    this.setContext({ kind: 'free', mode });
  }

  private onEdit(value: string) {
    store.save(this.draftKey(), value);
    this.hideError();
    if (this.state === 'running' || this.state === 'paused') {
      this.halt();
      this.state = 'idle';
      this.setStatus('Program zmienił się w trakcie działania, więc został zatrzymany. Rysunek zostaje; uruchom program ponownie.');
      this.updateButtons();
      this.draw();
    } else if (this.state === 'error') {
      this.state = 'idle';
      this.setStatus('Gotowy do uruchomienia.');
      this.updateButtons();
    }
  }

  /**
   * Replaces the free draft of `mode` with `source`. A draft with unsaved
   * work is never dropped silently: the user is asked first (or, for
   * `ask: false`, gets an undo), and the old text is always kept as a backup.
   */
  async requestLoad(source: string, mode: Mode, label: string, opts: { ask?: boolean; quiet?: boolean } = {}): Promise<boolean> {
    // Make sure the latest keystrokes are stored.
    store.save(this.draftKey(), this.editor.getValue());
    const old = Studio.draftOf(mode);
    const dirty = Studio.isDirty(mode) && old !== source;
    if (dirty && opts.ask !== false) {
      const choice = await this.confirmReplace(label, mode);
      if (choice === 'cancel') return false;
      if (choice === 'save') this.downloadSource(old, mode);
    }
    if (dirty) store.saveJson('backup', { mode, source: old, time: Date.now() });
    store.save(`draft:${mode}`, source);
    store.save(`base:${mode}`, source);
    this.onGoFree(mode);
    if (!opts.quiet) {
      if (dirty) {
        toast(`Wczytano: ${label}. Poprzedni szkic ${mode.toUpperCase()} jest zachowany.`, {
          label: 'Przywróć szkic',
          run: () => this.restoreBackup(),
        });
      } else {
        toast(`Wczytano: ${label}.`);
      }
    }
    return true;
  }

  private restoreBackup() {
    const b = store.loadJson<{ mode: Mode; source: string } | null>('backup', null);
    if (!b) return;
    store.save(`draft:${b.mode}`, b.source);
    store.save(`base:${b.mode}`, '');
    store.save('backup', null);
    this.onGoFree(b.mode);
    toast('Przywrócono poprzedni szkic.');
  }

  private confirmReplace(label: string, mode: Mode): Promise<'load' | 'save' | 'cancel'> {
    return new Promise((resolve) => {
      let answer: 'load' | 'save' | 'cancel' = 'cancel';
      const pick = (a: 'load' | 'save' | 'cancel') => () => {
        answer = a;
        dlg.close();
      };
      const cancel = h('button', { class: 'btn', type: 'button', onclick: pick('cancel') }, 'Anuluj');
      const body = h(
        'div',
        null,
        h(
          'p',
          null,
          `W trybie ${mode.toUpperCase()} masz szkic, który nie został zapisany do pliku. Wczytanie programu „${label}” go zastąpi.`,
        ),
        h(
          'div',
          { class: 'dialog-actions' },
          h('button', { class: 'btn btn-primary', type: 'button', onclick: pick('save') }, icon('save'), 'Zapisz szkic i wczytaj'),
          h('button', { class: 'btn', type: 'button', onclick: pick('load') }, 'Wczytaj bez zapisywania'),
          cancel,
        ),
      );
      const dlg = openDialog('Zastąpić Twój szkic?', body);
      dlg.dialog.addEventListener('close', () => resolve(answer));
      cancel.focus();
    });
  }

  // ------------------------------------------------------------ files, sharing, examples

  private openExamples() {
    const body = h('div', { class: 'ex-groups' });
    let dlg: { close: () => void };
    for (const [mode, title] of [
      ['2d', 'Na płaszczyźnie (2D)'],
      ['3d', 'W przestrzeni (3D)'],
    ] as [Mode, string][]) {
      const grid = h('div', { class: 'ex-grid' });
      for (const ex of EXAMPLES.filter((e) => e.mode === mode)) {
        const res = runProgram(ex.source, ex.mode);
        grid.append(
          h(
            'button',
            {
              class: 'ex-card',
              type: 'button',
              'data-example': ex.id,
              onclick: () => {
                dlg.close();
                void this.requestLoad(ex.source, ex.mode, ex.name);
              },
            },
            h('span', { class: 'ex-thumb', html: thumbSvg(res.segments, ex.mode, { size: 120 }) }),
            h('span', { class: 'ex-name' }, ex.name, h('span', { class: 'badge' }, ex.mode.toUpperCase())),
            h('span', { class: 'ex-blurb' }, ex.blurb),
          ),
        );
      }
      body.append(h('section', null, h('h3', null, title), grid));
    }
    dlg = openDialog('Przykłady', body, { wide: true });
  }

  private downloadSource(source: string, mode: Mode) {
    const stamp = new Date().toISOString().slice(0, 10);
    download(`logomocja-${mode}-${stamp}.logo`, new Blob([source], { type: 'text/plain;charset=utf-8' }));
  }

  private saveFile() {
    const source = this.editor.getValue();
    this.downloadSource(source, this.mode);
    if (this.context.kind === 'free') store.save(`base:${this.mode}`, source);
    toast('Program zapisany do pliku .logo.');
  }

  private onFile() {
    const file = this.fileInput.files?.[0];
    this.fileInput.value = '';
    if (!file) return;
    if (file.size > 400000) {
      toast('Ten plik jest za duży na program Logo (limit to 50 000 znaków).');
      return;
    }
    const reader = new FileReader();
    reader.onload = () => {
      const text = String(reader.result ?? '').replace(/^\uFEFF/, '').replace(/\r\n?/g, '\n');
      const mode: Mode = uses3d(text) ? '3d' : this.context.kind === 'free' ? this.mode : '2d';
      void this.requestLoad(text, mode, file.name);
    };
    reader.onerror = () => toast('Nie udało się odczytać pliku.');
    reader.readAsText(file);
  }

  private share() {
    const url = `${location.href.split('#')[0]}#/program/${this.mode}/${encodeProgram(this.editor.getValue())}`;
    const input = h('input', { type: 'text', class: 'share-url', readonly: true, value: url, 'aria-label': 'Link do programu' });
    const note = h('p', { class: 'muted', role: 'status' }, 'Link zawiera cały program i tryb. Kto go otworzy, zobaczy gotowy rysunek.');
    const copy = h(
      'button',
      {
        class: 'btn btn-primary',
        type: 'button',
        onclick: async () => {
          input.select();
          let ok = false;
          try {
            await navigator.clipboard.writeText(url);
            ok = true;
          } catch {
            try {
              ok = document.execCommand('copy');
            } catch {
              ok = false;
            }
          }
          note.textContent = ok ? 'Skopiowano link do schowka.' : 'Nie udało się skopiować. Zaznacz link i skopiuj go ręcznie.';
        },
      },
      icon('copy'),
      'Kopiuj link',
    );
    openDialog('Udostępnij program', h('div', null, h('div', { class: 'share-row' }, input, copy), note));
    input.focus();
    input.select();
  }

  private exportPng() {
    this.measure();
    const scale = 2;
    const c = document.createElement('canvas');
    c.width = Math.max(2, Math.round(this.w * scale));
    c.height = Math.max(2, Math.round(this.h * scale));
    const cx = c.getContext('2d')!;
    cx.scale(scale, scale);
    this.view.draw(cx, this.w, this.h, { ...this.scene(), ghost: null }, this.pal(), { turtle: false, dpr: scale });
    c.toBlob((blob) => {
      if (!blob) {
        toast('Nie udało się utworzyć obrazu PNG.');
        return;
      }
      download(`logomocja-${this.mode}.png`, blob);
      toast('Rysunek zapisany jako PNG.');
    }, 'image/png');
  }

  // ------------------------------------------------------------ challenge bar

  private renderChallengeBar(result?: { pass: boolean; text: string }) {
    const ctx = this.context;
    this.chBar.hidden = ctx.kind !== 'challenge';
    this.chBar.textContent = '';
    if (ctx.kind !== 'challenge') return;
    const ch = ctx.ch;
    const solved = store.loadJson<string[]>('solved', []).includes(ch.id);
    const res = h('p', { class: 'ch-result' + (result ? (result.pass ? ' pass' : ' fail') : ''), role: 'status', 'aria-live': 'polite' });
    if (result) res.append(icon(result.pass ? 'check' : 'close'), h('span', null, result.text));
    else if (solved) res.append(icon('check'), h('span', null, 'To wyzwanie masz już zaliczone. Możesz rozwiązać je jeszcze raz.'));
    const actions = h(
      'div',
      { class: 'ch-actions' },
      h('button', { class: 'btn btn-primary', type: 'button', id: 'ch-check', onclick: () => this.checkChallenge() }, icon('check'), 'Sprawdź'),
      h('a', { class: 'btn', href: '#/wyzwania' }, icon('back'), 'Lista wyzwań'),
    );
    if (result?.pass) {
      const next = this.nextChallenge(ch);
      if (next) actions.append(h('a', { class: 'btn', href: `#/wyzwanie/${next.id}` }, 'Następne wyzwanie', icon('next')));
    }
    this.chBar.append(
      h(
        'div',
        { class: 'ch-text' },
        h('p', { class: 'ch-kicker' }, `Wyzwanie · ${ch.mode.toUpperCase()}`),
        h('h2', null, ch.title),
        h('p', null, ch.task, ' Rysuj po szarym śladzie.'),
        h('details', { class: 'ch-hint' }, h('summary', null, 'Podpowiedź'), h('p', null, ch.hint)),
      ),
      h('div', { class: 'ch-side' }, actions, res),
    );
  }

  nextChallenge: (ch: Challenge) => Challenge | null = () => null;

  private checkChallenge() {
    if (this.context.kind !== 'challenge') return;
    const ch = this.context.ch;
    this.runInstant();
    const verdict = judge(ch, this.editor.getValue());
    if (verdict.pass) {
      const solved = new Set(store.loadJson<string[]>('solved', []));
      solved.add(ch.id);
      store.saveJson('solved', [...solved]);
      this.onSolved();
    }
    this.renderChallengeBar({ pass: verdict.pass, text: verdict.pass ? 'Brawo! Rysunek zgadza się ze wzorem. Wyzwanie zaliczone.' : verdict.reason });
    (this.chBar.querySelector('#ch-check') as HTMLElement | null)?.focus();
  }

  // ------------------------------------------------------------ execution

  private halt() {
    cancelAnimationFrame(this.raf);
    this.raf = 0;
    if (this.machine) {
      this.finalSegments = this.machine.segments;
      this.finalTurtle = this.turtleOf(this.machine);
    }
    this.machine = null;
    this.iter = null;
    this.pending = null;
    this.anim = null;
    this.editor.setExecLine(null);
  }

  private clearRun() {
    this.halt();
    this.finalSegments = [];
    this.finalTurtle = HOME;
    this.state = 'idle';
    this.hideError();
    this.setStatus('Gotowy. Naciśnij „Uruchom”, żeby zobaczyć rysunek.');
    this.updateButtons();
    this.draw();
  }

  private turtleOf(m: Machine): TurtleState {
    return { pos: m.pos, heading: m.heading, up: m.up, right: m.right, penDown: m.penDown, color: m.color };
  }

  /** Parses the editor text and gets a machine ready. False on a parse error. */
  private prepare(): boolean {
    this.halt();
    this.finalSegments = [];
    this.finalTurtle = HOME;
    this.hideError();
    try {
      const program = parse(this.editor.getValue(), this.mode);
      this.machine = new Machine(program);
    } catch (e) {
      this.state = 'error';
      this.showError(toErrorInfo(e), false);
      this.updateButtons();
      this.draw();
      return false;
    }
    this.iter = this.machine.run();
    this.pending = this.iter.next();
    this.budget = 0;
    return true;
  }

  /** Executes the pending operation. Returns false when a run-time error stopped the program. */
  private advance(): boolean {
    const m = this.machine!;
    const tok = this.pending!.value as Tok;
    const from = m.pos;
    const count = m.segments.length;
    const clears = m.clears;
    try {
      this.pending = this.iter!.next();
    } catch (e) {
      const info = toErrorInfo(e);
      this.halt();
      this.state = 'error';
      this.showError(info, true);
      this.updateButtons();
      this.draw();
      return false;
    }
    this.editor.setExecLine(tok.line, this.state !== 'running' || this.speed <= 3);
    const moved = m.pos !== from;
    const sp = SPEEDS[this.speed - 1];
    const dist = moved ? Math.hypot(m.pos[0] - from[0], m.pos[1] - from[1], m.pos[2] - from[2]) : 0;
    const seg = moved && clears === m.clears && m.segments.length === count + 1 ? m.segments[count] : null;
    this.anim = {
      from,
      to: m.pos,
      seg,
      dur: moved ? Math.min(2500, Math.max(sp.op * 0.5, (dist / sp.move) * 1000)) : sp.op * 0.5,
      t: 0,
    };
    return true;
  }

  private finish() {
    const m = this.machine;
    const segs = m ? m.segments.length : 0;
    const ops = m ? m.ops : 0;
    this.halt();
    this.state = 'done';
    this.setStatus(`Gotowe: ${plural(segs, 'odcinek', 'odcinki', 'odcinków')}, ${plural(ops, 'operacja', 'operacje', 'operacji')}.`);
    this.updateButtons();
    if (this.view.auto) this.fit();
    else this.draw();
  }

  run() {
    if (this.state === 'running') return;
    if (this.state !== 'paused') {
      if (!this.prepare()) return;
    }
    this.state = 'running';
    this.setStatus('Program działa…');
    this.updateButtons();
    if (this.speed >= 6) {
      this.drain();
      return;
    }
    this.lastFrame = performance.now();
    cancelAnimationFrame(this.raf);
    this.raf = requestAnimationFrame((t) => this.frame(t));
  }

  /** Runs everything that is left without animation. */
  private drain() {
    this.anim = null;
    while (this.pending && !this.pending.done) {
      if (!this.advance()) return;
    }
    this.anim = null;
    this.finish();
  }

  private frame(now: number) {
    this.raf = 0;
    if (this.state !== 'running') return;
    if (this.speed >= 6) {
      this.drain();
      return;
    }
    this.budget += Math.min(100, Math.max(0, now - this.lastFrame));
    this.lastFrame = now;
    const started = performance.now();
    while (this.state === 'running') {
      if (this.anim) {
        const rest = this.anim.dur - this.anim.t;
        if (this.budget < rest) {
          this.anim.t += this.budget;
          this.budget = 0;
          break;
        }
        this.budget -= rest;
        this.anim = null;
      }
      if (this.pending!.done) {
        this.finish();
        return;
      }
      if (!this.advance()) return;
      if (performance.now() - started > 10) {
        this.budget = 0;
        break;
      }
    }
    if (this.view.auto && this.machine) this.view.ensure(sceneBounds(this.scene()), this.w, this.h);
    this.draw();
    if (this.state === 'running') this.raf = requestAnimationFrame((t) => this.frame(t));
  }

  step() {
    if (this.state === 'running') {
      this.pause();
      return;
    }
    if (this.state !== 'paused') {
      if (!this.prepare()) return;
      this.state = 'paused';
    }
    this.anim = null;
    if (this.pending!.done) {
      this.finish();
      return;
    }
    const tok = this.pending!.value as Tok;
    if (!this.advance()) return;
    this.anim = null;
    if (this.pending!.done) {
      this.finish();
      this.setStatus(`Ostatni krok wykonany (wiersz ${tok.line}). ${this.statusEl.textContent}`);
      return;
    }
    this.setStatus(`Krok: wykonano „${tok.text}” w wierszu ${tok.line}. Następny krok: wiersz ${(this.pending!.value as Tok).line}.`);
    this.updateButtons();
    if (this.view.auto) this.view.ensure(sceneBounds(this.scene()), this.w, this.h);
    this.draw();
  }

  pause() {
    if (this.state !== 'running') return;
    cancelAnimationFrame(this.raf);
    this.raf = 0;
    this.anim = null;
    if (this.pending?.done) {
      this.finish();
      return;
    }
    this.state = 'paused';
    this.setStatus('Pauza. „Wznów” kontynuuje, „Krok” wykonuje jedno polecenie.');
    this.updateButtons();
    this.draw();
  }

  reset() {
    this.clearRun();
    if (this.view.auto) this.fit();
  }

  /** Runs the editor's program to the end without animation. */
  runInstant(): RunResult {
    if (!this.prepare()) {
      return { segments: [], error: this.lastError };
    }
    this.state = 'running';
    const m = this.machine!;
    this.drain();
    return { segments: copySegments(m.segments), error: this.state === 'error' ? this.lastError : null };
  }

  /** The testing hook behind window.logomocja.open. */
  openSource(source: string, mode: Mode): RunResult {
    store.save(this.draftKey(), this.editor.getValue());
    const old = Studio.draftOf(mode);
    if (Studio.isDirty(mode) && old !== source) store.saveJson('backup', { mode, source: old, time: Date.now() });
    store.save(`draft:${mode}`, source);
    this.onGoFree(mode);
    this.setContext({ kind: 'free', mode }, { run: false });
    const res = this.runInstant();
    this.view.auto = true;
    this.fit();
    this.drawNow();
    return res;
  }

  // ------------------------------------------------------------ status

  private setStatus(text: string) {
    this.statusEl.textContent = text;
  }

  private showError(err: LogoErrorInfo, runtime: boolean) {
    this.lastError = err;
    this.editor.setError(err);
    this.errorEl.hidden = false;
    this.errorEl.textContent = '';
    this.errorEl.append(
      h(
        'div',
        null,
        h('strong', null, `Błąd w wierszu ${err.line}, kolumnie ${err.column}. `),
        h('span', null, err.message),
        runtime ? h('span', { class: 'muted' }, ' To, co żółw zdążył narysować, zostało na rysunku.') : null,
      ),
      h('button', { class: 'btn btn-small', type: 'button', onclick: () => this.editor.goto(err.line, err.column) }, 'Pokaż w edytorze'),
    );
    this.setStatus(runtime ? 'Program zatrzymany przez błąd.' : 'Program ma błąd, więc nic nie zostało narysowane.');
  }

  private hideError() {
    this.lastError = null;
    this.errorEl.hidden = true;
    this.errorEl.textContent = '';
    this.editor.setError(null);
  }

  private updateButtons() {
    const s = this.state;
    this.btnPause.disabled = s !== 'running';
    this.btnRun.disabled = s === 'running';
    const label = this.btnRun.querySelector('.btn-label')!;
    label.textContent = s === 'paused' ? 'Wznów' : 'Uruchom';
    this.el.dataset.state = s;
  }

  // ------------------------------------------------------------ drawing

  private scene(): Scene {
    const m = this.machine;
    if (!m) {
      return { segments: this.finalSegments, count: this.finalSegments.length, tip: null, turtle: this.finalTurtle, ghost: this.ghost };
    }
    const turtle = this.turtleOf(m);
    const a = this.anim;
    if (a && a.dur > 0 && a.t < a.dur && a.from !== a.to) {
      const k = a.t / a.dur;
      const p: Vec3 = [
        a.from[0] + (a.to[0] - a.from[0]) * k,
        a.from[1] + (a.to[1] - a.from[1]) * k,
        a.from[2] + (a.to[2] - a.from[2]) * k,
      ];
      turtle.pos = p;
      if (a.seg && m.segments[m.segments.length - 1] === a.seg) {
        return {
          segments: m.segments,
          count: m.segments.length - 1,
          tip: { from: a.seg.from, to: p, color: a.seg.color, width: a.seg.width },
          turtle,
          ghost: this.ghost,
        };
      }
    }
    return { segments: m.segments, count: m.segments.length, tip: null, turtle, ghost: this.ghost };
  }

  themeChanged() {
    this.palette = null;
    this.draw();
  }

  private pal(): Palette {
    if (!this.palette) {
      const cs = getComputedStyle(document.documentElement);
      const v = (n: string, d: string) => cs.getPropertyValue(n).trim() || d;
      this.palette = {
        paper: v('--cv-paper', '#fbf8f1'),
        grid: v('--cv-grid', '#e4ecec'),
        gridStrong: v('--cv-grid-strong', '#cfdcdc'),
        axis: v('--cv-axis', '#8fa3a3'),
        text: v('--cv-text', '#5b6b6b'),
        ghost: v('--cv-ghost', 'rgba(60,80,90,.2)'),
        shell: v('--cv-shell', '#2f9e7d'),
        shellEdge: v('--cv-shell-edge', '#0e4f3e'),
        skin: v('--cv-skin', '#9bd4a5'),
        axisX: v('--cv-x', '#c2504a'),
        axisY: v('--cv-y', '#3d8f4f'),
        axisZ: v('--cv-z', '#3a6fc0'),
      };
    }
    return this.palette;
  }

  private measure() {
    const box = this.canvas.parentElement!;
    const w = box.clientWidth;
    const hh = box.clientHeight;
    const dpr = Math.min(3, window.devicePixelRatio || 1);
    if (w === this.w && hh === this.h && dpr === this.dpr) return;
    this.w = w;
    this.h = hh;
    this.dpr = dpr;
    this.canvas.width = Math.max(1, Math.round(w * dpr));
    this.canvas.height = Math.max(1, Math.round(hh * dpr));
  }

  private resize() {
    const had = this.w > 1 && this.h > 1;
    this.measure();
    if (this.w < 2 || this.h < 2) return;
    if (this.view.auto || !had) this.fitQuiet();
    this.drawNow();
  }

  private fitQuiet() {
    if (this.w < 2 || this.h < 2) return;
    this.view.fit(sceneBounds(this.scene()), this.w, this.h);
  }

  fit() {
    this.measure();
    this.view.auto = true;
    this.fitQuiet();
    this.draw();
  }

  private zoom(f: number) {
    this.view.zoomBy(f, this.w / 2, this.h / 2, this.w, this.h);
    this.draw();
  }

  draw() {
    if (this.drawQueued) return;
    this.drawQueued = true;
    requestAnimationFrame(() => {
      if (this.drawQueued) this.drawNow();
    });
  }

  drawNow() {
    this.drawQueued = false;
    this.measure();
    if (this.w < 2 || this.h < 2) return;
    const scene = this.scene();
    this.ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
    this.view.draw(this.ctx, this.w, this.h, scene, this.pal(), { turtle: true, dpr: this.dpr });
    const t = scene.turtle!;
    const n = (v: number) => {
      const r = Math.round(v * 10) / 10;
      return (r === 0 ? 0 : r).toString().replace('-', '−');
    };
    if (this.mode === '2d') {
      let deg = (Math.atan2(t.heading[0], t.heading[1]) * 180) / Math.PI;
      deg = ((Math.round(deg * 10) / 10) % 360 + 360) % 360;
      this.readoutEl.textContent = `x ${n(t.pos[0])}  y ${n(t.pos[1])}  kierunek ${n(deg)}°  ${t.penDown ? 'pióro ↓' : 'pióro ↑'}`;
    } else {
      this.readoutEl.textContent = `x ${n(t.pos[0])}  y ${n(t.pos[1])}  z ${n(t.pos[2])}  ${t.penDown ? 'pióro ↓' : 'pióro ↑'}`;
    }
    const count = scene.count + (scene.tip ? 1 : 0);
    this.canvas.setAttribute(
      'aria-label',
      `Rysunek żółwia, tryb ${this.mode.toUpperCase()}: ${plural(count, 'odcinek', 'odcinki', 'odcinków')}. Żółw stoi w punkcie ${n(t.pos[0])}, ${n(t.pos[1])}, ${n(t.pos[2])}.`,
    );
  }

  private bindCanvas() {
    const c = this.canvas;
    const pts = new Map<number, { x: number; y: number; alt: boolean }>();
    let pinch = 0;
    c.addEventListener('pointerdown', (e) => {
      c.setPointerCapture(e.pointerId);
      pts.set(e.pointerId, { x: e.clientX, y: e.clientY, alt: e.shiftKey || e.button === 1 || e.button === 2 });
      pinch = 0;
      c.classList.add('dragging');
    });
    c.addEventListener('pointermove', (e) => {
      const p = pts.get(e.pointerId);
      if (!p) return;
      const dx = e.clientX - p.x;
      const dy = e.clientY - p.y;
      p.x = e.clientX;
      p.y = e.clientY;
      if (pts.size === 1) {
        this.view.drag(dx, dy, p.alt, this.w, this.h);
      } else if (pts.size === 2) {
        const [a, b] = [...pts.values()];
        const d = Math.hypot(a.x - b.x, a.y - b.y);
        const rect = c.getBoundingClientRect();
        if (pinch > 0 && d > 0) {
          this.view.zoomBy(d / pinch, (a.x + b.x) / 2 - rect.left, (a.y + b.y) / 2 - rect.top, this.w, this.h);
        }
        pinch = d;
        // Two fingers also move the view (half of each finger's motion).
        if (this.mode === '3d') this.view.drag(dx / 2, dy / 2, true, this.w, this.h);
      }
      this.draw();
    });
    const up = (e: PointerEvent) => {
      pts.delete(e.pointerId);
      pinch = 0;
      if (pts.size === 0) c.classList.remove('dragging');
    };
    c.addEventListener('pointerup', up);
    c.addEventListener('pointercancel', up);
    c.addEventListener('contextmenu', (e) => e.preventDefault());
    c.addEventListener(
      'wheel',
      (e) => {
        e.preventDefault();
        const rect = c.getBoundingClientRect();
        const delta = e.deltaMode === 1 ? e.deltaY * 30 : e.deltaY;
        this.view.zoomBy(Math.exp(-delta * 0.0016), e.clientX - rect.left, e.clientY - rect.top, this.w, this.h);
        this.draw();
      },
      { passive: false },
    );
    c.addEventListener('dblclick', () => this.fit());
    c.addEventListener('keydown', (e) => {
      if (e.ctrlKey || e.metaKey || e.altKey) return;
      const k = e.key;
      let used = true;
      if (k === 'ArrowLeft') this.view.key(-1, 0, e.shiftKey, this.w, this.h);
      else if (k === 'ArrowRight') this.view.key(1, 0, e.shiftKey, this.w, this.h);
      else if (k === 'ArrowUp') this.view.key(0, this.mode === '3d' && !e.shiftKey ? 1 : -1, e.shiftKey, this.w, this.h);
      else if (k === 'ArrowDown') this.view.key(0, this.mode === '3d' && !e.shiftKey ? -1 : 1, e.shiftKey, this.w, this.h);
      else if (k === '+' || k === '=') this.zoom(1.25);
      else if (k === '-' || k === '_') this.zoom(0.8);
      else if (k === '0' || k === 'Home') {
        if (this.mode === '3d') this.view.reset();
        this.fit();
      } else used = false;
      if (used) {
        e.preventDefault();
        this.draw();
      }
    });
  }

  /** Global keyboard shortcuts; returns true when the key was handled. */
  handleShortcut(e: KeyboardEvent): boolean {
    if (!this.visible || document.querySelector('dialog[open]')) return false;
    const mod = e.ctrlKey || e.metaKey;
    if (e.key === 'Enter' && mod && !e.altKey && !e.shiftKey) {
      if (this.state === 'running') return true;
      this.run();
      return true;
    }
    if (e.key === 'Enter' && e.altKey && !mod) {
      this.step();
      return true;
    }
    if (e.key === 'Escape' && this.state === 'running') {
      this.pause();
      return true;
    }
    if (e.key === 'Backspace' && mod && e.shiftKey) {
      this.reset();
      return true;
    }
    return false;
  }
}

export function plural(n: number, one: string, few: string, many: string): string {
  const abs = Math.abs(n);
  const d = abs % 10;
  const dd = abs % 100;
  const word = abs === 1 ? one : d >= 2 && d <= 4 && !(dd >= 12 && dd <= 14) ? few : many;
  return `${n} ${word}`;
}

