// Static SVG previews of drawings (examples, challenges, reference).
import type { Segment, Vec3 } from '../lang/interp';
import type { Mode } from '../lang/tokens';

const AZ = (-32 * Math.PI) / 180;
const EL = (24 * Math.PI) / 180;

/** Orthographic projection matching the default 3D camera. */
function project(p: Vec3): [number, number, number] {
  const ce = Math.cos(EL);
  const se = Math.sin(EL);
  const sa = Math.sin(AZ);
  const ca = Math.cos(AZ);
  const f: Vec3 = [sa * ce, ca * ce, -se];
  const r: Vec3 = [ca, -sa, 0];
  const u: Vec3 = [r[1] * f[2] - r[2] * f[1], r[2] * f[0] - r[0] * f[2], r[0] * f[1] - r[1] * f[0]];
  return [
    p[0] * r[0] + p[1] * r[1] + p[2] * r[2],
    p[0] * u[0] + p[1] * u[1] + p[2] * u[2],
    p[0] * f[0] + p[1] * f[1] + p[2] * f[2],
  ];
}

export function thumbSvg(
  segments: Segment[],
  mode: Mode,
  opts: { size?: number; ghost?: boolean; label?: string } = {},
): string {
  const size = opts.size ?? 160;
  const lines: { a: [number, number]; b: [number, number]; d: number; s: Segment }[] = [];
  for (const s of segments) {
    if (mode === '3d') {
      const a = project(s.from);
      const b = project(s.to);
      lines.push({ a: [a[0], -a[1]], b: [b[0], -b[1]], d: (a[2] + b[2]) / 2, s });
    } else {
      lines.push({ a: [s.from[0], -s.from[1]], b: [s.to[0], -s.to[1]], d: 0, s });
    }
  }
  if (mode === '3d') lines.sort((x, y) => y.d - x.d);
  let x0 = Infinity;
  let y0 = Infinity;
  let x1 = -Infinity;
  let y1 = -Infinity;
  for (const l of lines) {
    for (const p of [l.a, l.b]) {
      x0 = Math.min(x0, p[0]);
      y0 = Math.min(y0, p[1]);
      x1 = Math.max(x1, p[0]);
      y1 = Math.max(y1, p[1]);
    }
  }
  if (!lines.length) {
    x0 = y0 = -1;
    x1 = y1 = 1;
  }
  const span = Math.max(x1 - x0, y1 - y0, 1e-6);
  const pad = 14;
  const k = (size - pad * 2) / span;
  const ox = (size - (x1 - x0) * k) / 2 - x0 * k;
// Practice tasks. The expected drawing of each task is produced by running
// its reference solution; the learner's drawing is compared with it.
import { checkDrawing, type CheckResult } from './checker';
import { run, type Segment } from './lang/interp';
import { COMMANDS, DEF_WORDS, tokenize, type CmdKind, type Mode } from './lang/tokens';

export interface Challenge {
  id: string;
  title: string;
  mode: Mode;
  level: 1 | 2 | 3;
  task: string;
  hint: string;
  solution: string;
  starter: string;
  /** Constructs the program has to use. */
  needs?: ('repeat' | 'proc' | 'var' | 'if' | 'penup')[];
}

export const CHALLENGES: Challenge[] = [
  {
    id: 'trojkat',
    title: 'Trójkąt',
    mode: '2d',
    level: 1,
    task: 'Narysuj trójkąt równoboczny o boku 120. Zacznij w środku, pierwszy bok poprowadź prosto do góry, a potem skręcaj w prawo.',
    hint: 'Żółw na każdym rogu skręca o kąt zewnętrzny: 360 / 3 = 120 stopni.',
    solution: 'powtorz 3 [np 120 pw 120]',
    starter: '; Trójkąt równoboczny o boku 120.\nnp 120\npw 120\n',
  },
    starter: '; Trzy krawędzie: przód, prawo, góra.\nnp 100 ws 100\n',
  },
];

const targets = new Map<string, Segment[]>();

export function targetOf(ch: Challenge): Segment[] {
  let t = targets.get(ch.id);
  if (!t) {
    t = run(ch.solution, ch.mode).segments;
    targets.set(ch.id, t);
  }
  return t;
}

const NEED_TEXT: Record<string, string> = {
  repeat: 'polecenia „powtorz”',
  proc: 'własnej procedury (oto … już)',
  var: 'zmiennej (niech)',
  if: 'warunku (jeśli albo jeżeli)',
  penup: 'podnoszenia pióra (pod i opu)',
};

function uses(source: string): Set<string> {
  const found = new Set<string>();
  try {
    for (const t of tokenize(source)) {
      if (t.t !== 'word') continue;
      const kind: CmdKind | undefined = COMMANDS.get(t.name);
      if (kind === 'repeat') found.add('repeat');
      else if (kind === 'let') found.add('var');
      else if (kind === 'if' || kind === 'ifelse') found.add('if');
      else if (kind === 'pu') found.add('penup');
      else if (DEF_WORDS.has(t.name) && t.first) found.add('proc');
    }
  } catch {
    /* reported elsewhere */
  }
  return found;
}

export interface Verdict extends CheckResult {
  error: { message: string; line: number; column: number } | null;
  segments: Segment[];
}

/** Runs the learner's program and judges it against the challenge. */
export function judge(ch: Challenge, source: string): Verdict {
  const res = run(source, ch.mode);
  if (res.error) {
    return {
      pass: false,
      covered: 0,
      extra: 0,
      reason: `Program zatrzymał się z błędem w wierszu ${res.error.line}: ${res.error.message}`,
      error: res.error,
      segments: res.segments,
    };
  }
  const check = checkDrawing(res.segments, targetOf(ch));
  if (check.pass && ch.needs) {
