// Application shell: header, hash router, pages, theme and the public API.
import { CHALLENGES, targetOf, type Challenge } from '../challenges';
import { EXAMPLES, findExample } from '../examples';
import { normMode, run as runProgram, type RunResult } from '../lang/interp';
import type { Mode } from '../lang/tokens';
import { TURTLE_LOGO, h, icon, toast } from './dom';
import { buildReference } from './reference';
import * as store from './store';
import { Studio, decodeProgram } from './studio';
import { thumbSvg } from './thumb';

declare const __VERSION__: string;

type Theme = 'auto' | 'light' | 'dark';
type Page = 'studio' | 'challenges' | 'reference';

const TITLE = 'Logomocja';
const app = document.getElementById('app')!;
const studio = new Studio();

// ---------------------------------------------------------------- theme

const media = window.matchMedia ? window.matchMedia('(prefers-color-scheme: dark)') : null;
let theme: Theme = (store.load('theme') as Theme) || 'auto';
if (!['auto', 'light', 'dark'].includes(theme)) theme = 'auto';

const THEME_TEXT: Record<Theme, string> = {
  auto: 'Motyw: jak w systemie',
  light: 'Motyw: jasny',
  dark: 'Motyw: ciemny',
};
const THEME_ICON: Record<Theme, string> = { auto: 'auto', light: 'sun', dark: 'moon' };
const themeBtn = h('button', { class: 'icon-btn theme-btn', type: 'button', onclick: () => cycleTheme() });

function applyTheme() {
  const dark = theme === 'dark' || (theme === 'auto' && !!media?.matches);
  document.documentElement.dataset.theme = dark ? 'dark' : 'light';
  const meta = document.querySelector('meta[name="theme-color"]');
  if (meta) meta.setAttribute('content', dark ? '#141b26' : '#f6f1e7');
  const next: Theme = theme === 'auto' ? 'light' : theme === 'light' ? 'dark' : 'auto';
  const label = `${THEME_TEXT[theme]}. Zmień na: ${THEME_TEXT[next].replace('Motyw: ', '')}`;
  themeBtn.setAttribute('aria-label', label);
  themeBtn.title = label;
  themeBtn.textContent = '';
  themeBtn.append(icon(THEME_ICON[theme]));
  studio.themeChanged();
}

function cycleTheme() {
  theme = theme === 'auto' ? 'light' : theme === 'light' ? 'dark' : 'auto';
  store.save('theme', theme === 'auto' ? null : theme);
  applyTheme();
  toast(THEME_TEXT[theme] + '.', undefined, 2500);
}

media?.addEventListener?.('change', () => applyTheme());

// ---------------------------------------------------------------- shell

const navLinks: Record<Page, HTMLAnchorElement> = {
  studio: h('a', { href: '#/' }, icon('pencil'), h('span', null, 'Pracownia')),
  challenges: h('a', { href: '#/wyzwania' }, icon('flag'), h('span', null, 'Wyzwania')),
  reference: h('a', { href: '#/polecenia' }, icon('book'), h('span', null, 'Polecenia')),
};

const main = h('main', { id: 'main', tabindex: '-1' });
const pageBox = h('div', { class: 'page', hidden: true });
main.append(studio.el, pageBox);

app.append(
  h('a', { class: 'skip-link', href: '#/', onclick: (e: Event) => {
    e.preventDefault();
    main.focus();
  } }, 'Przejdź do treści'),
  h(
    'header',
    { class: 'app-head' },
    h('a', { class: 'brand', href: '#/', 'aria-label': 'Logomocja, strona główna' }, h('span', { class: 'brand-logo', html: TURTLE_LOGO }), h('span', { class: 'brand-name' }, 'Logomocja')),
    h('nav', { class: 'app-nav', 'aria-label': 'Główna nawigacja' }, navLinks.studio, navLinks.challenges, navLinks.reference),
    themeBtn,
  ),
  main,
);

let referenceEl: HTMLElement | null = null;
let currentKey = '';
let firstRoute = true;

function show(page: Page, title: string) {
  for (const [k, a] of Object.entries(navLinks)) {
    if (k === page) a.setAttribute('aria-current', 'page');
    else a.removeAttribute('aria-current');
  }
  studio.el.hidden = page !== 'studio';
  studio.visible = page === 'studio';
  pageBox.hidden = page === 'studio';
  document.body.dataset.page = page;
  document.title = title === TITLE ? `${TITLE} · żółw Logo w 2D i 3D` : `${title} · ${TITLE}`;
}

function focusHeading() {
  if (firstRoute) return;
  const target = (studio.visible ? studio.el : pageBox).querySelector('h1') as HTMLElement | null;
  if (target) {
    target.setAttribute('tabindex', '-1');
    target.focus({ preventScroll: true });
  }
  window.scrollTo(0, 0);
}

function setHash(hash: string) {
  if (location.hash === hash) return;
  try {
    history.replaceState(null, '', location.pathname + location.search + hash);
  } catch {
    location.hash = hash;
  }
}

function showFree(mode: Mode, force = false) {
  show('studio', TITLE);
  const key = `free:${mode}`;
  if (force || currentKey !== key) {
    currentKey = key;
    studio.setContext({ kind: 'free', mode });
  } else {
    studio.fit();
  }
}

function showChallenge(ch: Challenge) {
  show('studio', `Wyzwanie: ${ch.title}`);
  // The studio sits under the "Wyzwania" tab while a challenge is open.
  navLinks.studio.removeAttribute('aria-current');
  navLinks.challenges.setAttribute('aria-current', 'page');
  const key = `challenge:${ch.id}`;
  if (currentKey !== key) {
    currentKey = key;
    studio.setContext({ kind: 'challenge', ch });
  } else {
    studio.fit();
  }
}

function levelText(level: number): string {
  return level === 1 ? 'na rozgrzewkę' : level === 2 ? 'średnie' : 'trudniejsze';
}

function showChallenges() {
  show('challenges', 'Wyzwania');
  const solved = new Set(store.loadJson<string[]>('solved', []));
  const done = CHALLENGES.filter((c) => solved.has(c.id)).length;
  const list = h('ol', { class: 'ch-grid' });
  for (const ch of CHALLENGES) {
    const ok = solved.has(ch.id);
    list.append(
      h(
        'li',
        null,
        h(
          'a',
          { class: 'ch-card' + (ok ? ' solved' : ''), href: `#/wyzwanie/${ch.id}` },
          h('span', { class: 'ch-thumb', html: thumbSvg(targetOf(ch), ch.mode, { size: 132, ghost: !ok }) }),
          h(
            'span',
            { class: 'ch-card-text' },
            h('span', { class: 'ch-card-title' }, ch.title),
            h('span', { class: 'ch-meta' }, h('span', { class: 'badge' }, ch.mode.toUpperCase()), ` ${levelText(ch.level)}`),
            h('span', { class: 'ch-card-task' }, ch.task),
            h('span', { class: 'ch-state' + (ok ? ' ok' : '') }, ok ? icon('check') : null, ok ? 'Zaliczone' : 'Do zrobienia'),
          ),
        ),
      ),
    );
  }
  const progress = h('progress', { max: String(CHALLENGES.length), value: String(done), 'aria-label': 'Postęp w wyzwaniach' });
  const reset = h(
    'button',
    {
      class: 'btn btn-small',
      type: 'button',
      onclick: () => {
        const before = store.loadJson<string[]>('solved', []);
        store.saveJson('solved', []);
        showChallenges();
        toast('Postęp w wyzwaniach wyzerowany.', {
          label: 'Cofnij',
          run: () => {
            store.saveJson('solved', before);
            if (document.body.dataset.page === 'challenges') showChallenges();
          },
        });
      },
    },
    icon('undo'),
    'Wyzeruj postęp',
  );
  pageBox.textContent = '';
  pageBox.append(
    h(
      'div',
      { class: 'challenges' },
      h(
        'header',
        { class: 'page-head' },
        h('h1', null, 'Wyzwania'),
        h(
          'p',
          null,
          'Każde wyzwanie pokazuje rysunek do odtworzenia. Napisz program, naciśnij „Sprawdź”, a Logomocja porówna Twój rysunek ze wzorem i powie, co się zgadza, a co nie.',
        ),
        h(
          'div',
          { class: 'ch-progress' },
          progress,
          h('span', null, `Zaliczone: ${done} z ${CHALLENGES.length}`),
          done > 0 ? reset : null,
        ),
      ),
      list,
    ),
  );
}

function showReference() {
  show('reference', 'Polecenia');
  if (!referenceEl) {
    referenceEl = buildReference((code, mode) => {
      void studio.requestLoad(code, mode, 'przykład z opisu poleceń');
    });
  }
  pageBox.textContent = '';
  pageBox.append(referenceEl);
}

function storedMode(): Mode {
  return store.load('mode') === '3d' ? '3d' : '2d';
}

function route() {
  const raw = location.hash.replace(/^#\/?/, '');
  const parts = raw.split('/').filter((p) => p !== '');
  const head = parts[0] ?? '';
  if (head === 'wyzwania') {
    showChallenges();
  } else if (head === 'wyzwanie') {
    const ch = CHALLENGES.find((c) => c.id === parts[1]);
    if (ch) showChallenge(ch);
    else {
      setHash('#/wyzwania');
      showChallenges();
      toast('Nie ma takiego wyzwania. Oto lista wszystkich.');
    }
  } else if (head === 'polecenia') {
    showReference();
  } else if (head === 'przyklad') {
    const ex = findExample(decodeURIComponent(parts[1] ?? ''));
    setHash('#/');
    if (ex) {
      showFree(ex.mode);
      void studio.requestLoad(ex.source, ex.mode, ex.name);
    } else {
      showFree(storedMode());
      toast('Nie ma takiego przykładu. Wszystkie znajdziesz pod przyciskiem „Przykłady”.');
    }
  } else if (head === 'program') {
    const mode: Mode = parts[1] === '3d' ? '3d' : '2d';
    const source = parts[2] !== undefined ? decodeProgram(parts[2]) : parts.length === 2 ? '' : null;
    setHash('#/');
    if (source === null || (parts[1] !== '2d' && parts[1] !== '3d')) {
      showFree(storedMode());
      toast('Ten link do programu jest uszkodzony, więc nic nie zostało wczytane.');
    } else {
      // A shared program replaces the draft; the old one stays restorable.
      void studio.requestLoad(source, mode, 'program z linku', { ask: false }).then(() => {
        studio.runInstant();
        studio.fit();
      });
    }
  } else {
    if (raw !== '') setHash('#/');
    showFree(storedMode());
  }
  focusHeading();
  firstRoute = false;
}

studio.onGoFree = (mode) => {
  setHash('#/');
  showFree(mode, true);
};
studio.onSolved = () => {};
studio.nextChallenge = (ch) => {
  const solved = new Set(store.loadJson<string[]>('solved', []));
  const i = CHALLENGES.indexOf(ch);
  const order = [...CHALLENGES.slice(i + 1), ...CHALLENGES.slice(0, i)];
  return order.find((c) => !solved.has(c.id)) ?? null;
};

window.addEventListener('hashchange', route);
window.addEventListener('keydown', (e) => {
  if (studio.handleShortcut(e)) e.preventDefault();
});

applyTheme();
route();

// ---------------------------------------------------------------- public API

function settle(): Promise<void> {
  return new Promise((resolve) => {
    let done = false;
    const finish = () => {
      if (!done) {
        done = true;
        resolve();
      }
    };
    requestAnimationFrame(() => requestAnimationFrame(finish));
    // Background tabs do not get animation frames.
    setTimeout(finish, 250);
  });
}

const api = {
  version: __VERSION__,
  run(source: string, mode: string = '2d'): RunResult {
    return runProgram(String(source ?? ''), normMode(mode));
  },
  async open(source: string, mode: string = '2d'): Promise<RunResult> {
    const result = studio.openSource(String(source ?? ''), normMode(mode));
    await settle();
    studio.drawNow();
    return result;
  },
  examples: EXAMPLES.map((e) => ({ id: e.id, name: e.name, mode: e.mode, source: e.source })),
  challenges: CHALLENGES.map((c) => ({ id: c.id, title: c.title, mode: c.mode })),
};

(window as unknown as { logomocja: typeof api }).logomocja = api;

