/** Lightens a pen colour that would be hard to see on the dark drawing sheet. */
export function liftInk(color: string): string {
  const m = /^#([0-9a-f]{2})([0-9a-f]{2})([0-9a-f]{2})$/i.exec(color);
  if (!m) return color;
  let rgb = [parseInt(m[1], 16), parseInt(m[2], 16), parseInt(m[3], 16)];
  const lum = (c: number[]) => {
    const f = (v: number) => {
      const x = v / 255;
      return x <= 0.03928 ? x / 12.92 : Math.pow((x + 0.055) / 1.055, 2.4);
    };
    return 0.2126 * f(c[0]) + 0.7152 * f(c[1]) + 0.0722 * f(c[2]);
  };
  let guard = 0;
  while (lum(rgb) < 0.16 && guard++ < 40) rgb = rgb.map((v) => Math.min(255, Math.round(v + (255 - v) * 0.08) + 1));
  return '#' + rgb.map((v) => v.toString(16).padStart(2, '0')).join('');
}
"""
open(p,'w').write(s)
