/* Logomocja: a school-notebook look. Cream graph paper by day, a night classroom after dark. */
:root {
  color-scheme: light;
  --bg: #f6f1e7;
  --bg-line: rgba(60, 110, 140, 0.07);
  --surface: #fffdf8;
  --surface-2: #efe8d9;
  --ink: #1d2b3f;
  --muted: #566274;
  --line: #d6cbb4;
  --line-strong: #b9ac90;
  --accent: #16866a;
  --accent-strong: #0f6e57;
  --accent-ink: #ffffff;
  --accent-soft: #dcefe8;
  --copper: #c1763d;
  --copper-text: #96531f;
  --error: #b3261e;
  --error-bg: #fbe9e6;
  --ok: #0f6e57;
  --ok-bg: #dff1e9;
  --focus: #1f5fa8;
  --shadow: 0 1px 2px rgba(40, 30, 10, 0.08), 0 6px 18px rgba(40, 30, 10, 0.07);

  --cv-paper: #fffdf8;
  --cv-grid: #e7eff0;
  --cv-grid-strong: #cfdfe2;
  --cv-axis: #8aa0aa;
  --cv-text: #5b6b78;
  --cv-ghost: rgba(40, 60, 90, 0.17);
  --cv-shell: #2f9e7d;
  --cv-shell-edge: #0e4f3e;
  --cv-skin: #9bd4a5;
  --cv-x: #c2504a;
  --cv-y: #3d8f4f;
  --cv-z: #3a6fc0;
  --ghost-solid: #c5ccd3;

  --logo-skin: #9bd4a5;
  --logo-shell: #16866a;
  --logo-line: #f6f1e7;

  --t-cmd: #0f6e57;
  --t-ctl: #7a3fa0;
  --t-num: #a84d14;
  --t-str: #7a5b00;
  --t-com: #717b8a;
  --t-var: #1f5fa8;
  --t-proc: #a2336a;
  --t-br: #1d2b3f;
  --t-op: #566274;
  --exec-band: rgba(193, 118, 61, 0.2);
  --err-band: rgba(179, 38, 30, 0.1);

  --font-ui: system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
  --font-head: 'Iowan Old Style', 'Palatino Linotype', Palatino, 'Book Antiqua', Georgia, serif;
  --font-mono: ui-monospace, 'SF Mono', 'Cascadia Code', Menlo, Consolas, 'DejaVu Sans Mono', 'Liberation Mono', monospace;
  --radius: 12px;
  --ed-pad: 12px;
  --ed-pad-x: 12px;
  --ed-lh: 24px;
  --ed-size: 15px;
}

:root[data-theme='dark'] {
  color-scheme: dark;
  --bg: #131a24;
  --bg-line: rgba(140, 180, 220, 0.045);
  --surface: #1b2431;
