  --err-band: rgba(255, 148, 136, 0.13);
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

[hidden] {
  display: none !important;
}

html {
  -webkit-text-size-adjust: 100%;
  text-size-adjust: 100%;
}

body {
  margin: 0;
  min-height: 100vh;
  min-height: 100dvh;
  background-color: var(--bg);
  background-image: linear-gradient(var(--bg-line) 1px, transparent 1px), linear-gradient(90deg, var(--bg-line) 1px, transparent 1px);
  background-size: 24px 24px;
  color: var(--ink);
  font: 16px/1.5 var(--font-ui);
}

h1,
h2,
h3 {
  font-family: var(--font-head);
  line-height: 1.2;
  margin: 0;
  font-weight: 700;
  letter-spacing: 0.005em;
}

p {
  margin: 0;
}

a {
  color: var(--accent-strong);
  text-underline-offset: 0.18em;
}

kbd {
  font: 600 0.85em var(--font-mono);
  padding: 2px 6px;
  border: 1px solid var(--line-strong);
  border-bottom-width: 2px;
  border-radius: 6px;
  background: var(--surface);
  white-space: nowrap;
}

code,
.code {
  font-family: var(--font-mono);
}

:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.visually-hidden {
  position: absolute !important;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}

.muted {
  color: var(--muted);
}

.noscript {
  max-width: 40rem;
  margin: 3rem auto;
  padding: 1.5rem;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius);
}

/* ------------------------------------------------------------ icons and buttons */

.ic-wrap {
  display: inline-flex;
  flex: none;
}

.ic {
  display: block;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  min-height: 40px;
  padding: 6px 13px;
  border: 1.5px solid var(--line-strong);
  border-radius: 10px;
  background: var(--surface);
  color: var(--ink);
  font: 600 0.94rem/1.2 var(--font-ui);
  text-decoration: none;
  cursor: pointer;
  white-space: nowrap;
  transition: background-color 0.12s, border-color 0.12s, transform 0.06s;
}

.btn:hover:not(:disabled) {
  background: var(--surface-2);
  border-color: var(--ink);
}

.btn:active:not(:disabled) {
  transform: translateY(1px);
}

.btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.btn-primary {
  background: var(--accent);
  border-color: var(--accent);
  color: var(--accent-ink);
}

.btn-primary:hover:not(:disabled) {
  background: var(--accent-strong);
  border-color: var(--accent-strong);
}

.btn-small {
  min-height: 34px;
  padding: 4px 10px;
  font-size: 0.88rem;
}

.btn-small .ic {
  width: 16px;
  height: 16px;
}

.icon-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  flex: none;
  padding: 0;
  border: 1.5px solid transparent;
  border-radius: 10px;
  background: transparent;
  color: var(--ink);
  cursor: pointer;
}

.icon-btn:hover {
  background: var(--surface-2);
  border-color: var(--line-strong);
}

.badge {
  display: inline-block;
  padding: 1px 7px;
  border-radius: 999px;
  background: var(--accent-soft);
  color: var(--accent-strong);
  font: 700 0.72rem/1.5 var(--font-ui);
  letter-spacing: 0.04em;
  vertical-align: middle;
}

.segmented {
  display: inline-flex;
  border: 1.5px solid var(--line-strong);
  border-radius: 10px;
  background: var(--surface);
  padding: 2px;
  gap: 2px;
}

.seg {
  min-width: 46px;
  min-height: 33px;
  padding: 2px 10px;
  border: 0;
  border-radius: 7px;
  background: transparent;
  color: var(--ink);
  font: 700 0.94rem var(--font-ui);
  cursor: pointer;
}

.seg:hover {
  background: var(--surface-2);
}

.seg[aria-pressed='true'] {
  background: var(--ink);
  color: var(--bg);
}

/* ------------------------------------------------------------ shell */

#app {
  display: flex;
  flex-direction: column;
  min-height: 100vh;
  min-height: 100dvh;
}

.skip-link {
  position: absolute;
  left: 8px;
  top: -60px;
  z-index: 50;
  padding: 8px 14px;
  background: var(--ink);
  color: var(--bg);
  border-radius: 8px;
  font-weight: 600;
}

.skip-link:focus {
  top: 8px;
}

.app-head {
  display: flex;
  align-items: center;
  gap: 8px 18px;
  padding: 8px 16px;
  background: var(--surface);
  border-bottom: 1.5px solid var(--line);
  position: relative;
  z-index: 5;
}

.app-head::after {
  /* the red margin line of a school notebook */
  content: '';
  position: absolute;
  left: 0;
  right: 0;
  bottom: -5px;
  height: 1.5px;
  background: var(--copper);
  opacity: 0.55;
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: var(--ink);
  text-decoration: none;
  border-radius: 8px;
}

.brand-logo {
  display: inline-flex;
}

.brand-name {
  font: 700 1.35rem/1 var(--font-head);
  letter-spacing: 0.01em;
}

.app-nav {
  display: flex;
  gap: 4px;
  margin-left: auto;
}

.app-nav a {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-height: 40px;
  padding: 4px 12px;
  border-radius: 10px;
  color: var(--ink);
  font-weight: 600;
  text-decoration: none;
  border-bottom: 3px solid transparent;
}

.app-nav a:hover {
  background: var(--surface-2);
}

.app-nav a[aria-current='page'] {
  background: var(--accent-soft);
  color: var(--accent-strong);
  border-bottom-color: var(--accent);
}

.app-nav .ic {
  width: 18px;
  height: 18px;
}

main {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
  outline: none;
}

.page {
  width: 100%;
  max-width: 1120px;
  margin: 0 auto;
  padding: 28px 20px 56px;
}

.page-head {
  margin-bottom: 22px;
  max-width: 46rem;
}

.page-head h1 {
  font-size: clamp(1.8rem, 4vw, 2.4rem);
  margin-bottom: 8px;
}

.page-head h1:focus {
  outline: none;
}

.page-head p {
  color: var(--muted);
  font-size: 1.05rem;
}

/* ------------------------------------------------------------ studio */

.studio {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 16px;
}

.studio-grid {
  flex: 1;
  min-height: 0;
  display: grid;
  grid-template-columns: minmax(340px, 5fr) 7fr;
  gap: 14px;
}

.pane {
  display: flex;
  flex-direction: column;
  gap: 10px;
  min-width: 0;
  min-height: 0;
}

.toolbar,
.transport {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
}

.toolbar-gap {
  flex: 1;
}

.messages {
  display: flex;
  flex-direction: column;
  gap: 6px;
  min-height: 1.5em;
}

.status {
  color: var(--muted);
  font-size: 0.92rem;
  display: flex;
  align-items: baseline;
  gap: 8px;
}

.status::before {
  content: '';
  flex: none;
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: var(--line-strong);
  transform: translateY(-1px);
}

.studio[data-state='running'] .status::before {
  background: var(--accent);
  animation: pulse 0.9s ease-in-out infinite;
}

.studio[data-state='paused'] .status::before {
  background: var(--copper);
}

.studio[data-state='done'] .status::before {
  background: var(--accent);
}

.studio[data-state='error'] .status::before {
  background: var(--error);
}

@keyframes pulse {
  50% {
    opacity: 0.3;
  }
}

.error-box {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 8px 14px;
  padding: 9px 12px;
  border: 1.5px solid var(--error);
  border-left-width: 6px;
  border-radius: 10px;
  background: var(--error-bg);
  color: var(--ink);
  font-size: 0.95rem;
}

.error-box strong {
  color: var(--error);
}

/* editor */

.editor {
  flex: 1;
  min-height: 180px;
  display: flex;
  position: relative;
  overflow: hidden;
  border: 1.5px solid var(--line-strong);
  border-radius: var(--radius);
  background: var(--surface);
  box-shadow: var(--shadow);
  font: var(--ed-size) / var(--ed-lh) var(--font-mono);
}

.editor:focus-within {
  border-color: var(--focus);
  outline: 3px solid var(--focus);
  outline-offset: 1px;
}

.ed-gutter {
  flex: none;
  min-width: 3.1em;
  overflow: hidden;
  padding: var(--ed-pad) 0;
  background: var(--surface-2);
  border-right: 1.5px solid var(--copper);
  color: var(--muted);
  text-align: right;
  user-select: none;
  -webkit-user-select: none;
}

.ed-ln {
  height: var(--ed-lh);
  line-height: var(--ed-lh);
  padding: 0 8px 0 10px;
  font-size: 0.85em;
  font-variant-numeric: tabular-nums;
}

.ed-ln.exec {
  background: var(--copper);
  color: #fff;
  font-weight: 700;
}

:root[data-theme='dark'] .ed-ln.exec {
  color: #1a1206;
}

.ed-ln.err {
  background: var(--error);
  color: var(--surface);
  font-weight: 700;
}

.ed-main {
  position: relative;
  flex: 1;
  min-width: 0;
  overflow: hidden;
}

.ed-layers {
  position: absolute;
  top: 0;
  left: 0;
  min-width: 100%;
  pointer-events: none;
  will-change: transform;
}

.ed-hl,
.ed-input {
  margin: 0;
  padding: var(--ed-pad) var(--ed-pad-x);
  border: 0;
  font: inherit;
  letter-spacing: 0;
  white-space: pre;
  tab-size: 2;
  -moz-tab-size: 2;
  font-variant-ligatures: none;
}

.ed-hl {
  position: relative;
  color: var(--ink);
}

.ed-input {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  resize: none;
  overflow: auto;
  background: transparent;
  color: transparent;
  caret-color: var(--ink);
  outline: none;
  border-radius: 0;
  -webkit-text-fill-color: transparent;
}

.ed-input::selection {
  background: rgba(31, 95, 168, 0.28);
}

:root[data-theme='dark'] .ed-input::selection {
  background: rgba(132, 187, 245, 0.32);
}

.ed-band {
  position: absolute;
  left: -2000px;
  width: 200000px;
  height: var(--ed-lh);
}

.ed-band.exec {
  background: var(--exec-band);
}

.ed-band.err {
  background: var(--err-band);
}

.ed-squiggle {
  position: absolute;
  height: 5px;
  background: repeating-linear-gradient(135deg, var(--error) 0 2px, transparent 2px 4px);
  border-radius: 2px;
}

.ed-lens {
  color: var(--error);
  font-style: italic;
  font-family: var(--font-ui);
  font-size: 0.9em;
}

.t-com {
  color: var(--t-com);
  font-style: italic;
}
.t-str {
  color: var(--t-str);
}
.t-var {
  color: var(--t-var);
}
.t-def,
.t-ctl,
.t-rep {
  color: var(--t-ctl);
  font-weight: 600;
}
.t-cmd {
  color: var(--t-cmd);
  font-weight: 600;
}
.t-proc {
  color: var(--t-proc);
}
.t-name {
  color: var(--ink);
}
.t-num {
  color: var(--t-num);
}
.t-br,
.t-par {
  color: var(--t-br);
  font-weight: 700;
}
.t-op {
  color: var(--t-op);
}

/* stage */

.stage {
  position: relative;
  flex: 1;
  min-height: 0;
  border: 1.5px solid var(--line-strong);
  border-radius: var(--radius);
  background: var(--cv-paper);
  box-shadow: var(--shadow);
  overflow: hidden;
}

.stage-canvas {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  touch-action: none;
  cursor: grab;
  border-radius: calc(var(--radius) - 2px);
}

.stage-canvas.dragging {
  cursor: grabbing;
}

.stage-canvas:focus-visible {
  outline-offset: -4px;
}

.stage-tools {
  position: absolute;
  top: 8px;
  right: 8px;
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 4px;
  border: 1.5px solid var(--line);
  border-radius: 12px;
  background: color-mix(in srgb, var(--surface) 92%, transparent);
}

.stage-tools .icon-btn {
  width: 38px;
  height: 38px;
}

.readout {
  position: absolute;
  left: 8px;
  bottom: 8px;
  max-width: calc(100% - 16px);
  padding: 3px 9px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: color-mix(in srgb, var(--surface) 90%, transparent);
  color: var(--muted);
  font: 0.78rem/1.5 var(--font-mono);
  white-space: pre;
  overflow: hidden;
  text-overflow: ellipsis;
  pointer-events: none;
}

.stage-note {
  position: absolute;
  left: 8px;
  top: 8px;
  right: 64px;
  padding: 6px 10px;
  border-radius: 8px;
  background: var(--surface-2);
  font-size: 0.9rem;
}

.speed {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-left: auto;
  font-size: 0.92rem;
  font-weight: 600;
}

.speed input[type='range'] {
  width: 120px;
  height: 28px;
  accent-color: var(--accent);
  cursor: pointer;
}

.speed-out {
  min-width: 7.2em;
  color: var(--muted);
  font-weight: 500;
}

/* challenge bar */

.challenge-bar {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 10px 24px;
  align-items: center;
  padding: 12px 16px;
  border: 1.5px solid var(--line-strong);
  border-left: 6px solid var(--copper);
  border-radius: var(--radius);
  background: var(--surface);
  box-shadow: var(--shadow);
}

.ch-kicker {
  color: var(--copper-text);
  font: 700 0.76rem/1.4 var(--font-ui);
  letter-spacing: 0.09em;
  text-transform: uppercase;
}

.challenge-bar h2 {
  font-size: 1.3rem;
  margin: 1px 0 4px;
}

.ch-text {
  max-width: 62rem;
}

.ch-hint {
  margin-top: 4px;
  color: var(--muted);
}

.ch-hint summary {
  cursor: pointer;
  font-weight: 600;
  width: fit-content;
  border-radius: 6px;
}

.ch-side {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 8px;
  max-width: 30rem;
}

.ch-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  justify-content: flex-end;
}

.ch-result {
  display: flex;
  align-items: flex-start;
  gap: 6px;
  font-weight: 600;
  font-size: 0.95rem;
}

.ch-result:empty {
  display: none;
}

.ch-result.pass,
.ch-result.fail {
  padding: 7px 11px;
  border-radius: 10px;
  border: 1.5px solid;
}

.ch-result.pass {
  background: var(--ok-bg);
  border-color: var(--ok);
  color: var(--ink);
}

.ch-result.pass .ic-wrap,
.ch-result .ic-wrap {
  color: var(--ok);
}

.ch-result.fail {
  background: var(--error-bg);
  border-color: var(--error);
}

.ch-result.fail .ic-wrap {
  color: var(--error);
}

/* ------------------------------------------------------------ challenges page */

.ch-progress {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px 14px;
  margin-top: 14px;
  font-weight: 600;
  color: var(--ink);
}

.ch-progress progress {
  width: min(260px, 100%);
  height: 12px;
  accent-color: var(--accent);
}

.ch-grid {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(320px, 1fr));
  gap: 14px;
}

.ch-card {
  display: flex;
  gap: 14px;
  height: 100%;
  padding: 12px;
  border: 1.5px solid var(--line-strong);
  border-radius: var(--radius);
  background: var(--surface);
  color: var(--ink);
  text-decoration: none;
  box-shadow: var(--shadow);
  transition: transform 0.12s, border-color 0.12s;
}

.ch-card:hover {
  border-color: var(--ink);
  transform: translateY(-2px);
}

.ch-card.solved {
  border-color: var(--accent);
}

.ch-thumb,
.ex-thumb,
.ref-card-thumb {
  display: flex;
  align-items: center;
  justify-content: center;
  flex: none;
  border: 1px solid var(--line);
  border-radius: 10px;
  background-color: var(--cv-paper);
  background-image: linear-gradient(var(--cv-grid) 1px, transparent 1px), linear-gradient(90deg, var(--cv-grid) 1px, transparent 1px);
  background-size: 12px 12px;
}

.thumb {
  display: block;
  max-width: 100%;
  height: auto;
}

:root[data-theme='dark'] .thumb {
  filter: brightness(1.35) saturate(1.05);
}

.ch-thumb .thumb {
  width: 108px;
  height: 108px;
}

.ch-card-text {
  display: flex;
  flex-direction: column;
  gap: 3px;
  min-width: 0;
}

.ch-card-title {
  font: 700 1.2rem/1.2 var(--font-head);
}

.ch-meta {
  color: var(--muted);
  font-size: 0.85rem;
}

.ch-card-task {
  font-size: 0.92rem;
  color: var(--muted);
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.ch-state {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  margin-top: auto;
  padding-top: 4px;
  font-weight: 700;
  font-size: 0.88rem;
  color: var(--muted);
}

.ch-state.ok {
  color: var(--ok);
}

.ch-state .ic {
  width: 17px;
  height: 17px;
}

/* ------------------------------------------------------------ reference */

.ref-layout {
  display: grid;
  grid-template-columns: 220px minmax(0, 1fr);
  gap: 32px;
  align-items: start;
}

.ref-toc {
  position: sticky;
  top: 16px;
  max-height: calc(100vh - 32px);
  overflow: auto;
  padding: 14px 16px;
  border: 1.5px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface);
}

.ref-toc h2 {
  font-size: 1rem;
  margin-bottom: 8px;
}

.ref-toc ul {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.ref-toc a {
  display: block;
  padding: 5px 8px;
  border-radius: 8px;
  color: var(--ink);
  text-decoration: none;
  font-size: 0.95rem;
}

.ref-toc a:hover {
  background: var(--surface-2);
}

.ref-section {
  margin-bottom: 40px;
  scroll-margin-top: 16px;
}

.ref-section:focus {
  outline: none;
}

.ref-section > h2 {
  font-size: 1.55rem;
  padding-bottom: 6px;
  margin-bottom: 10px;
  border-bottom: 2px solid var(--copper);
}

.ref-intro {
  margin-bottom: 14px;
  max-width: 46rem;
}

.ref-extra {
  margin: 14px 0;
  max-width: 46rem;
}

.ref-extra p,
.ref-extra ul,
.ref-extra pre {
  margin: 0 0 10px;
}

.ref-extra ul {
  padding-left: 1.3em;
}

.ref-extra li {
  margin-bottom: 4px;
}

.ref-card {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 152px;
  gap: 16px;
  align-items: start;
  padding: 14px 16px;
  margin-bottom: 12px;
  border: 1.5px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface);
}

.ref-card h3 {
  font: 700 1.02rem/1.4 var(--font-mono);
  color: var(--t-cmd);
  margin-bottom: 2px;
  overflow-wrap: anywhere;
}

.ref-card-text > p {
  margin-bottom: 8px;
}

.ref-arg {
  color: var(--muted);
  font-size: 0.9rem;
}

.ref-arg span {
  font-weight: 600;
}

.code,
.ref-extra pre {
  margin: 0 0 10px;
  padding: 9px 12px;
  border: 1px solid var(--line);
  border-left: 3px solid var(--copper);
  border-radius: 8px;
  background: var(--bg);
  font: 0.9rem/1.55 var(--font-mono);
  overflow-x: auto;
  white-space: pre;
}

.ref-extra code,
.ref-intro code,
.ref-card-text p code,
.ref-table code {
  padding: 1px 5px;
  border-radius: 5px;
  background: var(--surface-2);
  font-size: 0.92em;
}

.ref-table {
  width: 100%;
  max-width: 46rem;
  border-collapse: collapse;
  margin: 10px 0 14px;
  background: var(--surface);
  border: 1.5px solid var(--line);
  border-radius: 10px;
  font-size: 0.95rem;
}

.ref-table caption {
  text-align: left;
  font-weight: 700;
  padding: 0 0 6px;
}

.ref-table th,
.ref-table td {
  padding: 8px 12px;
  border-bottom: 1px solid var(--line);
  text-align: left;
  vertical-align: top;
}

.ref-table th {
  font-weight: 600;
}

.ref-table tr:last-child th,
.ref-table tr:last-child td {
  border-bottom: 0;
}

.ref-table.keys th {
  white-space: nowrap;
  width: 1%;
}

/* ------------------------------------------------------------ dialogs and toast */

.dialog {
  width: min(540px, calc(100vw - 24px));
  max-height: calc(100dvh - 24px);
  padding: 0;
  border: 1.5px solid var(--line-strong);
  border-radius: 16px;
  background: var(--surface);
  color: var(--ink);
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.35);
  overflow: hidden;
}

.dialog[open] {
  display: flex;
  flex-direction: column;
}

.dialog.wide {
  width: min(940px, calc(100vw - 24px));
}

.dialog::backdrop {
  background: rgba(15, 22, 34, 0.55);
}

.dialog-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 12px 12px 12px 20px;
  border-bottom: 1.5px solid var(--line);
}

.dialog-head h2 {
  font-size: 1.3rem;
}

.dialog-body {
  padding: 16px 20px 20px;
  overflow: auto;
}

.dialog-body > div > p {
  margin-bottom: 12px;
}

.dialog-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 16px;
}

.share-row {
  display: flex;
  gap: 8px;
  margin-bottom: 12px;
}

.share-url {
  flex: 1;
  min-width: 0;
  min-height: 40px;
  padding: 6px 10px;
  border: 1.5px solid var(--line-strong);
  border-radius: 10px;
  background: var(--bg);
  color: var(--ink);
  font: 0.88rem var(--font-mono);
}

.ex-groups section + section {
  margin-top: 22px;
}

.ex-groups h3 {
  font-size: 1.1rem;
  margin-bottom: 10px;
}

.ex-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(150px, 1fr));
  gap: 10px;
}

.ex-card {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 10px;
  border: 1.5px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface);
  color: var(--ink);
  font: inherit;
  text-align: left;
  cursor: pointer;
}

.ex-card:hover {
  border-color: var(--ink);
  background: var(--surface-2);
}

.ex-thumb {
  width: 100%;
  aspect-ratio: 1.25;
}

.ex-thumb .thumb {
  width: auto;
  height: 100%;
}

.ex-name {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
  font-weight: 700;
}

.ex-blurb {
  font-size: 0.85rem;
  color: var(--muted);
  line-height: 1.35;
}

#toast {
  position: fixed;
  left: 50%;
  bottom: 18px;
  z-index: 100;
  display: flex;
  align-items: center;
  gap: 10px;
  width: max-content;
  max-width: calc(100vw - 24px);
  padding: 8px 8px 8px 16px;
  border-radius: 12px;
  background: var(--ink);
  color: var(--bg);
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.3);
  font-size: 0.95rem;
  transform: translate(-50%, 20px);
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.18s, transform 0.18s, visibility 0.18s;
}

#toast.show {
  transform: translate(-50%, 0);
  opacity: 1;
  visibility: visible;
}

#toast .btn {
  background: var(--bg);
  color: var(--ink);
  border-color: var(--bg);
}

#toast .icon-btn {
  color: var(--bg);
  width: 34px;
  height: 34px;
}

#toast .icon-btn:hover {
  background: rgba(127, 127, 127, 0.35);
}

#toast :focus-visible {
  outline-color: var(--bg);
}

/* ------------------------------------------------------------ desktop: the studio fills the window */

@media (min-width: 900px) {
  body[data-page='studio'] {
    height: 100vh;
    height: 100dvh;
    overflow: hidden;
  }

  body[data-page='studio'] #app {
    height: 100%;
    min-height: 0;
  }
}

/* ------------------------------------------------------------ phones and narrow windows */

@media (max-width: 899.98px) {
  :root {
    --ed-size: 16px;
  }

  .studio {
    padding: 10px;
    gap: 10px;
    flex: none;
  }

  .studio-grid {
    display: flex;
    flex-direction: column;
    gap: 12px;
  }

  .pane-stage {
    order: -1;
  }

  .stage {
    flex: none;
    height: 46vh;
    height: 46dvh;
    min-height: 240px;
  }

  .editor {
    flex: none;
    height: clamp(240px, 52dvh, 520px);
  }

  .btn,
  .icon-btn {
    min-height: 44px;
  }

  .icon-btn {
    width: 44px;
    height: 44px;
  }

  .stage-tools .icon-btn {
    width: 40px;
    height: 40px;
    min-height: 40px;
  }

  .seg {
    min-height: 38px;
  }

  .challenge-bar {
    grid-template-columns: 1fr;
  }

  .ch-side {
    align-items: stretch;
    max-width: none;
  }

  .ch-actions {
    justify-content: flex-start;
  }

  .ref-layout {
    grid-template-columns: 1fr;
    gap: 20px;
  }

  .ref-toc {
    position: static;
    max-height: none;
  }

  .ref-toc ul {
    flex-direction: row;
    flex-wrap: wrap;
    gap: 6px;
  }

  .ref-toc a {
    border: 1px solid var(--line);
    padding: 8px 12px;
  }

  .page {
    padding: 20px 14px 48px;
  }
}

@media (max-width: 600px) {
  .app-head {
    padding: 6px 10px;
    gap: 6px;
  }

  .brand-name {
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    clip: rect(0 0 0 0);
    white-space: nowrap;
  }

  .app-nav {
    gap: 2px;
  }

  .app-nav a {
    padding: 4px 9px;
    min-height: 44px;
    font-size: 0.95rem;
  }

  .app-nav .ic-wrap {
    display: none;
  }

  .toolbar .btn .btn-label {
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    clip: rect(0 0 0 0);
    white-space: nowrap;
  }

  .toolbar .btn {
    position: relative;
    min-width: 46px;
    padding: 6px 10px;
  }

  .toolbar .btn[title^='Wczytaj'] .btn-label {
    position: static;
    width: auto;
    height: auto;
    clip: auto;
  }

  .transport {
    gap: 6px;
  }

  .transport .btn {
    flex: 1 1 auto;
    padding: 6px 9px;
  }

  .speed {
    flex: 1 1 100%;
    margin-left: 0;
    order: 5;
  }

  .speed input[type='range'] {
    flex: 1;
    width: auto;
    height: 36px;
  }

  .transport > .icon-btn {
    display: none;
  }

  .ref-card {
    grid-template-columns: 1fr;
  }

  .ref-card-thumb {
    justify-self: start;
  }

  .ch-grid {
    grid-template-columns: 1fr;
  }

  .ch-thumb .thumb {
    width: 88px;
    height: 88px;
  }

  .share-row {
    flex-direction: column;
  }

  .readout {
    font-size: 0.72rem;
  }

  #toast {
    width: calc(100vw - 16px);
    bottom: 8px;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.001ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.001ms !important;
    scroll-behavior: auto !important;
  }
}

@media (forced-colors: active) {
  .seg[aria-pressed='true'] {
    outline: 2px solid Highlight;
  }

  .ed-input {
    color: CanvasText;
    -webkit-text-fill-color: CanvasText;
  }

  .ed-hl {
    visibility: hidden;
  }
}

@media print {
  .app-head,
  .toolbar,
  .transport,
  .stage-tools,
  #toast {
    display: none !important;
  }
}

toolu_01SeixsNYQ8mQ95BnSXe38tK.content:
/* Logomocja: a school-notebook look. Cream graph paper by day, a night classroom after dark. */
:root {
  color-scheme: light;
  --bg: #f6f1e7;
  --bg-line: rgba(60, 110, 140, 0.07);
  --surface: #fffdf8;
  --surface-2: #efe8d9;
  --ink: #1d2b3f;
  --muted: #566274;
  --line: #d6cbb4;
  --line-strong: #b9ac90;
  --accent: #16866a;
  --accent-strong: #0f6e57;
  --accent-ink: #ffffff;
  --accent-soft: #dcefe8;
  --copper: #c1763d;
  --copper-text: #96531f;
  --error: #b3261e;
  --error-bg: #fbe9e6;
  --ok: #0f6e57;
  --ok-bg: #dff1e9;
  --focus: #1f5fa8;
  --shadow: 0 1px 2px rgba(40, 30, 10, 0.08), 0 6px 18px rgba(40, 30, 10, 0.07);

  --cv-paper: #fffdf8;
  --cv-grid: #e7eff0;
  --cv-grid-strong: #cfdfe2;
  --cv-axis: #8aa0aa;
  --cv-text: #5b6b78;
  --cv-ghost: rgba(40, 60, 90, 0.17);
  --cv-shell: #2f9e7d;
  --cv-shell-edge: #0e4f3e;
  --cv-skin: #9bd4a5;
  --cv-x: #c2504a;
  --cv-y: #3d8f4f;
  --cv-z: #3a6fc0;
  --ghost-solid: #c5ccd3;

  --logo-skin: #9bd4a5;
  --logo-shell: #16866a;
  --logo-line: #f6f1e7;

  --t-cmd: #0f6e57;
  --t-ctl: #7a3fa0;
  --t-num: #a84d14;
  --t-str: #7a5b00;
  --t-com: #717b8a;
  --t-var: #1f5fa8;
  --t-proc: #a2336a;
  --t-br: #1d2b3f;
  --t-op: #566274;
  --exec-band: rgba(193, 118, 61, 0.2);
  --err-band: rgba(179, 38, 30, 0.1);

  --font-ui: system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
  --font-head: 'Iowan Old Style', 'Palatino Linotype', Palatino, 'Book Antiqua', Georgia, serif;
  --font-mono: ui-monospace, 'SF Mono', 'Cascadia Code', Menlo, Consolas, 'DejaVu Sans Mono', 'Liberation Mono', monospace;
  --radius: 12px;
  --ed-pad: 12px;
  --ed-pad-x: 12px;
  --ed-lh: 24px;
  --ed-size: 15px;
}

:root[data-theme='dark'] {
  color-scheme: dark;
  --bg: #131a24;
  --bg-line: rgba(140, 180, 220, 0.045);
  --surface: #1b2431;
  --surface-2: #243042;
  --ink: #ebe8df;
  --muted: #a6b0bd;
  --line: #334154;
  --line-strong: #4a5b72;
  --accent: #3fc6a0;
  --accent-strong: #6fdcbb;
  --accent-ink: #08201a;
  --accent-soft: #1d3b39;
  --copper: #e09a5f;
  --copper-text: #f0b07a;
  --error: #ff9488;
  --error-bg: #3b1f22;
  --ok: #6fdcbb;
  --ok-bg: #173630;
  --focus: #ffd166;
  --shadow: 0 1px 2px rgba(0, 0, 0, 0.35), 0 8px 22px rgba(0, 0, 0, 0.3);

  --cv-paper: #18212d;
  --cv-grid: #202b39;
  --cv-grid-strong: #2b394a;
  --cv-axis: #5b6f86;
  --cv-text: #9aa7b6;
  --cv-ghost: rgba(190, 215, 255, 0.2);
  --cv-shell: #3fc6a0;
  --cv-shell-edge: #0b3a30;
  --cv-skin: #a6e0b4;
  --cv-x: #f0766f;
  --cv-y: #62c276;
  --cv-z: #6ea3f0;
  --ghost-solid: #46566b;

  --logo-shell: #3fc6a0;
  --logo-line: #131a24;

  --t-cmd: #62d8b5;
  --t-ctl: #cba2f2;
  --t-num: #f2a66f;
  --t-str: #e6cf6a;
  --t-com: #8491a2;
  --t-var: #84bbf5;
  --t-proc: #f296bd;
  --t-br: #ebe8df;
  --t-op: #a6b0bd;
  --exec-band: rgba(224, 154, 95, 0.24);
  --err-band: rgba(255, 148, 136, 0.13);
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

[hidden] {
  display: none !important;
}

html {
  -webkit-text-size-adjust: 100%;
  text-size-adjust: 100%;
}

body {
  margin: 0;
  min-height: 100vh;
  min-height: 100dvh;
  background-color: var(--bg);
  background-image: linear-gradient(var(--bg-line) 1px, transparent 1px), linear-gradient(90deg, var(--bg-line) 1px, transparent 1px);
  background-size: 24px 24px;
  color: var(--ink);
  font: 16px/1.5 var(--font-ui);
}

h1,
h2,
h3 {
  font-family: var(--font-head);
  line-height: 1.2;
  margin: 0;
  font-weight: 700;
  letter-spacing: 0.005em;
}

p {
  margin: 0;
}

a {
  color: var(--accent-strong);
  text-underline-offset: 0.18em;
}

kbd {
  font: 600 0.85em var(--font-mono);
  padding: 2px 6px;
  border: 1px solid var(--line-strong);
  border-bottom-width: 2px;
  border-radius: 6px;
  background: var(--surface);
  white-space: nowrap;
}

code,
.code {
  font-family: var(--font-mono);
}

:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.visually-hidden {
  position: absolute !important;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}

.muted {
  color: var(--muted);
}

.noscript {
  max-width: 40rem;
  margin: 3rem auto;
  padding: 1.5rem;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius);
}

/* ------------------------------------------------------------ icons and buttons */

.ic-wrap {
  display: inline-flex;
  flex: none;
}

.ic {
  display: block;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  min-height: 40px;
  padding: 6px 13px;
  border: 1.5px solid var(--line-strong);
  border-radius: 10px;
  background: var(--surface);
  color: var(--ink);
  font: 600 0.94rem/1.2 var(--font-ui);
  text-decoration: none;
  cursor: pointer;
  white-space: nowrap;
  transition: background-color 0.12s, border-color 0.12s, transform 0.06s;
}

.btn:hover:not(:disabled) {
  background: var(--surface-2);
  border-color: var(--ink);
}

.btn:active:not(:disabled) {
  transform: translateY(1px);
}

.btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.btn-primary {
  background: var(--accent);
  border-color: var(--accent);
  color: var(--accent-ink);
}

.btn-primary:hover:not(:disabled) {
  background: var(--accent-strong);
  border-color: var(--accent-strong);
}

.btn-small {
  min-height: 34px;
  padding: 4px 10px;
  font-size: 0.88rem;
}

.btn-small .ic {
  width: 16px;
  height: 16px;
}

.icon-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  flex: none;
  padding: 0;
  border: 1.5px solid transparent;
  border-radius: 10px;
  background: transparent;
  color: var(--ink);
  cursor: pointer;
}

.icon-btn:hover {
  background: var(--surface-2);
  border-color: var(--line-strong);
}

.badge {
  display: inline-block;
  padding: 1px 7px;
  border-radius: 999px;
  background: var(--accent-soft);
  color: var(--accent-strong);
  font: 700 0.72rem/1.5 var(--font-ui);
  letter-spacing: 0.04em;
  vertical-align: middle;
}

.segmented {
  display: inline-flex;
  border: 1.5px solid var(--line-strong);
  border-radius: 10px;
  background: var(--surface);
  padding: 2px;
  gap: 2px;
}

.seg {
  min-width: 46px;
  min-height: 33px;
  padding: 2px 10px;
  border: 0;
  border-radius: 7px;
  background: transparent;
  color: var(--ink);
  font: 700 0.94rem var(--font-ui);
  cursor: pointer;
}

.seg:hover {
  background: var(--surface-2);
}

.seg[aria-pressed='true'] {
  background: var(--ink);
  color: var(--bg);
}

/* ------------------------------------------------------------ shell */

#app {
  display: flex;
  flex-direction: column;
  min-height: 100vh;
  min-height: 100dvh;
}

.skip-link {
  position: absolute;
  left: 8px;
  top: -60px;
  z-index: 50;
  padding: 8px 14px;
  background: var(--ink);
  color: var(--bg);
  border-radius: 8px;
  font-weight: 600;
}

.skip-link:focus {
  top: 8px;
}

.app-head {
  display: flex;
  align-items: center;
  gap: 8px 18px;
  padding: 8px 16px;
  background: var(--surface);
  border-bottom: 1.5px solid var(--line);
  position: relative;
  z-index: 5;
}

.app-head::after {
  /* the red margin line of a school notebook */
  content: '';
  position: absolute;
  left: 0;
  right: 0;
  bottom: -5px;
  height: 1.5px;
  background: var(--copper);
  opacity: 0.55;
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: var(--ink);
  text-decoration: none;
  border-radius: 8px;
}

.brand-logo {
  display: inline-flex;
}

.brand-name {
  font: 700 1.35rem/1 var(--font-head);
  letter-spacing: 0.01em;
}

.app-nav {
  display: flex;
  gap: 4px;
  margin-left: auto;
}

.app-nav a {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-height: 40px;
  padding: 4px 12px;
  border-radius: 10px;
  color: var(--ink);
  font-weight: 600;
  text-decoration: none;
  border-bottom: 3px solid transparent;
}

.app-nav a:hover {
  background: var(--surface-2);
}

.app-nav a[aria-current='page'] {
  background: var(--accent-soft);
  color: var(--accent-strong);
  border-bottom-color: var(--accent);
}

.app-nav .ic {
  width: 18px;
  height: 18px;
}

main {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
  outline: none;
}

.page {
  width: 100%;
  max-width: 1120px;
  margin: 0 auto;
  padding: 28px 20px 56px;
}

.page-head {
  margin-bottom: 22px;
  max-width: 46rem;
}

.page-head h1 {
  font-size: clamp(1.8rem, 4vw, 2.4rem);
  margin-bottom: 8px;
}

.page-head h1:focus {
  outline: none;
}

.page-head p {
  color: var(--muted);
  font-size: 1.05rem;
}

/* ------------------------------------------------------------ studio */

.studio {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 16px;
}

.studio-grid {
  flex: 1;
  min-height: 0;
  display: grid;
  grid-template-columns: minmax(340px, 5fr) 7fr;
  gap: 14px;
}

.pane {
  display: flex;
  flex-direction: column;
  gap: 10px;
  min-width: 0;
  min-height: 0;
}

.toolbar,
.transport {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
}

.toolbar-gap {
  flex: 1;
}

.messages {
  display: flex;
  flex-direction: column;
  gap: 6px;
  min-height: 1.5em;
}

.status {
  color: var(--muted);
  font-size: 0.92rem;
  display: flex;
  align-items: baseline;
  gap: 8px;
}

.status::before {
  content: '';
  flex: none;
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: var(--line-strong);
  transform: translateY(-1px);
}

.studio[data-state='running'] .status::before {
  background: var(--accent);
  animation: pulse 0.9s ease-in-out infinite;
}

.studio[data-state='paused'] .status::before {
  background: var(--copper);
}

.studio[data-state='done'] .status::before {
  background: var(--accent);
}

.studio[data-state='error'] .status::before {
  background: var(--error);
}

@keyframes pulse {
  50% {
    opacity: 0.3;
  }
}

.error-box {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 8px 14px;
  padding: 9px 12px;
  border: 1.5px solid var(--error);
  border-left-width: 6px;
  border-radius: 10px;
  background: var(--error-bg);
  color: var(--ink);
  font-size: 0.95rem;
}

.error-box strong {
  color: var(--error);
}

/* editor */

.editor {
  flex: 1;
  min-height: 180px;
  display: flex;
  position: relative;
  overflow: hidden;
  border: 1.5px solid var(--line-strong);
  border-radius: var(--radius);
  background: var(--surface);
  box-shadow: var(--shadow);
  font: var(--ed-size) / var(--ed-lh) var(--font-mono);
}

.editor:focus-within {
  border-color: var(--focus);
  outline: 3px solid var(--focus);
  outline-offset: 1px;
}

.ed-gutter {
  flex: none;
  min-width: 3.1em;
  overflow: hidden;
  padding: var(--ed-pad) 0;
  background: var(--surface-2);
  border-right: 1.5px solid var(--copper);
  color: var(--muted);
  text-align: right;
  user-select: none;
  -webkit-user-select: none;
}

.ed-ln {
  height: var(--ed-lh);
  line-height: var(--ed-lh);
  padding: 0 8px 0 10px;
  font-size: 0.85em;
  font-variant-numeric: tabular-nums;
}

.ed-ln.exec {
  background: var(--copper);
  color: #fff;
  font-weight: 700;
}

:root[data-theme='dark'] .ed-ln.exec {
  color: #1a1206;
}

.ed-ln.err {
  background: var(--error);
  color: var(--surface);
  font-weight: 700;
}

.ed-main {
  position: relative;
  flex: 1;
  min-width: 0;
  overflow: hidden;
}

.ed-layers {
  position: absolute;
  top: 0;
  left: 0;
  min-width: 100%;
  pointer-events: none;
  will-change: transform;
}

.ed-hl,
.ed-input {
  margin: 0;
  padding: var(--ed-pad) var(--ed-pad-x);
  border: 0;
  font: inherit;
  letter-spacing: 0;
  white-space: pre;
  tab-size: 2;
  -moz-tab-size: 2;
  font-variant-ligatures: none;
}

.ed-hl {
  position: relative;
  color: var(--ink);
}

.ed-input {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  resize: none;
  overflow: auto;
  background: transparent;
  color: transparent;
  caret-color: var(--ink);
  outline: none;
  border-radius: 0;
  -webkit-text-fill-color: transparent;
}

.ed-input::selection {
  background: rgba(31, 95, 168, 0.28);
}

:root[data-theme='dark'] .ed-input::selection {
  background: rgba(132, 187, 245, 0.32);
}

.ed-band {
  position: absolute;
  left: -2000px;
  width: 200000px;
  height: var(--ed-lh);
}

.ed-band.exec {
  background: var(--exec-band);
}

.ed-band.err {
  background: var(--err-band);
}

.ed-squiggle {
  position: absolute;
  height: 5px;
  background: repeating-linear-gradient(135deg, var(--error) 0 2px, transparent 2px 4px);
  border-radius: 2px;
}

.ed-lens {
  color: var(--error);
  font-style: italic;
  font-family: var(--font-ui);
  font-size: 0.9em;
}

.t-com {
  color: var(--t-com);
  font-style: italic;
}
.t-str {
  color: var(--t-str);
}
.t-var {
  color: var(--t-var);
}
.t-def,
.t-ctl,
.t-rep {
  color: var(--t-ctl);
  font-weight: 600;
}
.t-cmd {
  color: var(--t-cmd);
  font-weight: 600;
}
.t-proc {
  color: var(--t-proc);
}
.t-name {
  color: var(--ink);
}
.t-num {
  color: var(--t-num);
}
.t-br,
.t-par {
  color: var(--t-br);
  font-weight: 700;
}
.t-op {
  color: var(--t-op);
}

/* stage */

.stage {
  position: relative;
  flex: 1;
  min-height: 0;
  border: 1.5px solid var(--line-strong);
  border-radius: var(--radius);
  background: var(--cv-paper);
  box-shadow: var(--shadow);
  overflow: hidden;
}

.stage-canvas {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  touch-action: none;
  cursor: grab;
  border-radius: calc(var(--radius) - 2px);
}

.stage-canvas.dragging {
  cursor: grabbing;
}

.stage-canvas:focus-visible {
  outline-offset: -4px;
}

.stage-tools {
  position: absolute;
  top: 8px;
  right: 8px;
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 4px;
  border: 1.5px solid var(--line);
  border-radius: 12px;
  background: color-mix(in srgb, var(--surface) 92%, transparent);
}

.stage-tools .icon-btn {
  width: 38px;
  height: 38px;
}

.readout {
  position: absolute;
  left: 8px;
  bottom: 8px;
  max-width: calc(100% - 16px);
  padding: 3px 9px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: color-mix(in srgb, var(--surface) 90%, transparent);
  color: var(--muted);
  font: 0.78rem/1.5 var(--font-mono);
  white-space: pre;
  overflow: hidden;
  text-overflow: ellipsis;
  pointer-events: none;
}

.stage-note {
  position: absolute;
  left: 8px;
  top: 8px;
  right: 64px;
  padding: 6px 10px;
  border-radius: 8px;
  background: var(--surface-2);
  font-size: 0.9rem;
}

.speed {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-left: auto;
  font-size: 0.92rem;
  font-weight: 600;
}

.speed input[type='range'] {
  width: 120px;
  height: 28px;
  accent-color: var(--accent);
  cursor: pointer;
}

.speed-out {
  min-width: 7.2em;
  color: var(--muted);
  font-weight: 500;
}

/* challenge bar */

.challenge-bar {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 10px 24px;
  align-items: center;
  padding: 12px 16px;
  border: 1.5px solid var(--line-strong);
  border-left: 6px solid var(--copper);
  border-radius: var(--radius);
  background: var(--surface);
  box-shadow: var(--shadow);
}

.ch-kicker {
  color: var(--copper-text);
  font: 700 0.76rem/1.4 var(--font-ui);
  letter-spacing: 0.09em;
  text-transform: uppercase;
}

.challenge-bar h2 {
  font-size: 1.3rem;
  margin: 1px 0 4px;
}

.ch-text {
  max-width: 62rem;
}

.ch-hint {
  margin-top: 4px;
  color: var(--muted);
}

.ch-hint summary {
  cursor: pointer;
  font-weight: 600;
  width: fit-content;
  border-radius: 6px;
}

.ch-side {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 8px;
  max-width: 30rem;
}

.ch-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  justify-content: flex-end;
}

.ch-result {
  display: flex;
  align-items: flex-start;
  gap: 6px;
  font-weight: 600;
  font-size: 0.95rem;
}

.ch-result:empty {
  display: none;
}

.ch-result.pass,
.ch-result.fail {
  padding: 7px 11px;
  border-radius: 10px;
  border: 1.5px solid;
}

.ch-result.pass {
  background: var(--ok-bg);
  border-color: var(--ok);
  color: var(--ink);
}

.ch-result.pass .ic-wrap,
.ch-result .ic-wrap {
  color: var(--ok);
}

.ch-result.fail {
  background: var(--error-bg);
  border-color: var(--error);
}

.ch-result.fail .ic-wrap {
  color: var(--error);
}

/* ------------------------------------------------------------ challenges page */

.ch-progress {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px 14px;
  margin-top: 14px;
  font-weight: 600;
  color: var(--ink);
}

.ch-progress progress {
  width: min(260px, 100%);
  height: 12px;
  accent-color: var(--accent);
}

.ch-grid {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(320px, 1fr));
  gap: 14px;
}

.ch-card {
  display: flex;
  gap: 14px;
  height: 100%;
  padding: 12px;
  border: 1.5px solid var(--line-strong);
  border-radius: var(--radius);
  background: var(--surface);
  color: var(--ink);
  text-decoration: none;
  box-shadow: var(--shadow);
  transition: transform 0.12s, border-color 0.12s;
}

.ch-card:hover {
  border-color: var(--ink);
  transform: translateY(-2px);
}

.ch-card.solved {
  border-color: var(--accent);
}

.ch-thumb,
.ex-thumb,
.ref-card-thumb {
  display: flex;
  align-items: center;
  justify-content: center;
  flex: none;
  border: 1px solid var(--line);
  border-radius: 10px;
  background-color: var(--cv-paper);
  background-image: linear-gradient(var(--cv-grid) 1px, transparent 1px), linear-gradient(90deg, var(--cv-grid) 1px, transparent 1px);
  background-size: 12px 12px;
}

.thumb {
  display: block;
  max-width: 100%;
  height: auto;
}

:root[data-theme='dark'] .thumb {
  filter: brightness(1.35) saturate(1.05);
}

.ch-thumb .thumb {
  width: 108px;
  height: 108px;
}

.ch-card-text {
  display: flex;
  flex-direction: column;
  gap: 3px;
  min-width: 0;
}

.ch-card-title {
  font: 700 1.2rem/1.2 var(--font-head);
}

.ch-meta {
  color: var(--muted);
  font-size: 0.85rem;
}

.ch-card-task {
  font-size: 0.92rem;
  color: var(--muted);
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.ch-state {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  margin-top: auto;
  padding-top: 4px;
  font-weight: 700;
  font-size: 0.88rem;
  color: var(--muted);
}

.ch-state.ok {
  color: var(--ok);
}

.ch-state .ic {
  width: 17px;
  height: 17px;
}

/* ------------------------------------------------------------ reference */

.ref-layout {
  display: grid;
  grid-template-columns: 220px minmax(0, 1fr);
  gap: 32px;
  align-items: start;
}

.ref-toc {
  position: sticky;
  top: 16px;
  max-height: calc(100vh - 32px);
  overflow: auto;
  padding: 14px 16px;
  border: 1.5px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface);
}

.ref-toc h2 {
  font-size: 1rem;
  margin-bottom: 8px;
}

.ref-toc ul {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.ref-toc a {
  display: block;
  padding: 5px 8px;
  border-radius: 8px;
  color: var(--ink);
  text-decoration: none;
  font-size: 0.95rem;
}

.ref-toc a:hover {
  background: var(--surface-2);
}

.ref-section {
  margin-bottom: 40px;
  scroll-margin-top: 16px;
}

.ref-section:focus {
  outline: none;
}

.ref-section > h2 {
  font-size: 1.55rem;
  padding-bottom: 6px;
  margin-bottom: 10px;
  border-bottom: 2px solid var(--copper);
}

.ref-intro {
  margin-bottom: 14px;
  max-width: 46rem;
}

.ref-extra {
  margin: 14px 0;
  max-width: 46rem;
}

.ref-extra p,
.ref-extra ul,
.ref-extra pre {
  margin: 0 0 10px;
}

.ref-extra ul {
  padding-left: 1.3em;
}

.ref-extra li {
  margin-bottom: 4px;
}

.ref-card {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 152px;
  gap: 16px;
  align-items: start;
  padding: 14px 16px;
  margin-bottom: 12px;
  border: 1.5px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface);
}

.ref-card h3 {
  font: 700 1.02rem/1.4 var(--font-mono);
  color: var(--t-cmd);
  margin-bottom: 2px;
  overflow-wrap: anywhere;
}

.ref-card-text > p {
  margin-bottom: 8px;
}

.ref-arg {
  color: var(--muted);
  font-size: 0.9rem;
}

.ref-arg span {
  font-weight: 600;
}

.code,
.ref-extra pre {
  margin: 0 0 10px;
  padding: 9px 12px;
  border: 1px solid var(--line);
  border-left: 3px solid var(--copper);
  border-radius: 8px;
  background: var(--bg);
  font: 0.9rem/1.55 var(--font-mono);
  overflow-x: auto;
  white-space: pre;
}

.ref-extra code,
.ref-intro code,
.ref-card-text p code,
.ref-table code {
  padding: 1px 5px;
  border-radius: 5px;
  background: var(--surface-2);
  font-size: 0.92em;
}

.ref-table {
  width: 100%;
  max-width: 46rem;
  border-collapse: collapse;
  margin: 10px 0 14px;
  background: var(--surface);
  border: 1.5px solid var(--line);
  border-radius: 10px;
  font-size: 0.95rem;
}

.ref-table caption {
  text-align: left;
  font-weight: 700;
  padding: 0 0 6px;
}

.ref-table th,
.ref-table td {
  padding: 8px 12px;
  border-bottom: 1px solid var(--line);
  text-align: left;
  vertical-align: top;
}

.ref-table th {
  font-weight: 600;
}

.ref-table tr:last-child th,
.ref-table tr:last-child td {
  border-bottom: 0;
}

.ref-table.keys th {
  white-space: nowrap;
  width: 1%;
}

/* ------------------------------------------------------------ dialogs and toast */

.dialog {
  width: min(540px, calc(100vw - 24px));
  max-height: calc(100dvh - 24px);
  padding: 0;
  border: 1.5px solid var(--line-strong);
  border-radius: 16px;
  background: var(--surface);
  color: var(--ink);
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.35);
  overflow: hidden;
}

.dialog[open] {
  display: flex;
  flex-direction: column;
}

.dialog.wide {
  width: min(940px, calc(100vw - 24px));
}

.dialog::backdrop {
  background: rgba(15, 22, 34, 0.55);
}

.dialog-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 12px 12px 12px 20px;
  border-bottom: 1.5px solid var(--line);
}

.dialog-head h2 {
  font-size: 1.3rem;
}

.dialog-body {
  padding: 16px 20px 20px;
  overflow: auto;
}

.dialog-body > div > p {
  margin-bottom: 12px;
}

.dialog-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 16px;
}

.share-row {
  display: flex;
  gap: 8px;
  margin-bottom: 12px;
}

.share-url {
  flex: 1;
  min-width: 0;
  min-height: 40px;
  padding: 6px 10px;
  border: 1.5px solid var(--line-strong);
  border-radius: 10px;
  background: var(--bg);
  color: var(--ink);
  font: 0.88rem var(--font-mono);
}

.ex-groups section + section {
  margin-top: 22px;
}

.ex-groups h3 {
  font-size: 1.1rem;
  margin-bottom: 10px;
}

.ex-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(150px, 1fr));
  gap: 10px;
}

.ex-card {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 10px;
  border: 1.5px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface);
  color: var(--ink);
  font: inherit;
  text-align: left;
  cursor: pointer;
}

.ex-card:hover {
  border-color: var(--ink);
  background: var(--surface-2);
}

.ex-thumb {
  width: 100%;
  aspect-ratio: 1.25;
}

.ex-thumb .thumb {
  width: auto;
  height: 100%;
}

.ex-name {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
  font-weight: 700;
}

.ex-blurb {
  font-size: 0.85rem;
  color: var(--muted);
  line-height: 1.35;
}

#toast {
  position: fixed;
  left: 50%;
  bottom: 18px;
  z-index: 100;
  display: flex;
  align-items: center;
  gap: 10px;
  width: max-content;
  max-width: calc(100vw - 24px);
  padding: 8px 8px 8px 16px;
  border-radius: 12px;
  background: var(--ink);
  color: var(--bg);
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.3);
  font-size: 0.95rem;
  transform: translate(-50%, 20px);
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.18s, transform 0.18s, visibility 0.18s;
}

#toast.show {
  transform: translate(-50%, 0);
  opacity: 1;
  visibility: visible;
}

#toast .btn {
  background: var(--bg);
  color: var(--ink);
  border-color: var(--bg);
}

#toast .icon-btn {
  color: var(--bg);
  width: 34px;
  height: 34px;
}

#toast .icon-btn:hover {
  background: rgba(127, 127, 127, 0.35);
}

#toast :focus-visible {
  outline-color: var(--bg);
}

/* ------------------------------------------------------------ desktop: the studio fills the window */

@media (min-width: 900px) {
  body[data-page='studio'] {
    height: 100vh;
    height: 100dvh;
    overflow: hidden;
  }

  body[data-page='studio'] #app {
    height: 100%;
    min-height: 0;
  }
}

/* ------------------------------------------------------------ phones and narrow windows */

@media (max-width: 899.98px) {
  :root {
    --ed-size: 16px;
  }

  .studio {
    padding: 10px;
    gap: 10px;
    flex: none;
  }

  .studio-grid {
    display: flex;
    flex-direction: column;
    gap: 12px;
  }

  .pane-stage {
    order: -1;
  }

  .stage {
    flex: none;
    height: 46vh;
    height: 46dvh;
    min-height: 240px;
  }

  .editor {
    flex: none;
    height: clamp(240px, 52dvh, 520px);
  }

  .btn,
  .icon-btn {
    min-height: 44px;
  }

  .icon-btn {
    width: 44px;
    height: 44px;
  }

  .stage-tools .icon-btn {
    width: 40px;
    height: 40px;
    min-height: 40px;
  }

  .seg {
    min-height: 38px;
  }

  .challenge-bar {
    grid-template-columns: 1fr;
  }

  .ch-side {
    align-items: stretch;
    max-width: none;
  }

  .ch-actions {
    justify-content: flex-start;
  }

  .ref-layout {
    grid-template-columns: 1fr;
    gap: 20px;
  }

  .ref-toc {
    position: static;
    max-height: none;
  }

  .ref-toc ul {
    flex-direction: row;
    flex-wrap: wrap;
    gap: 6px;
  }

  .ref-toc a {
    border: 1px solid var(--line);
    padding: 8px 12px;
  }

  .page {
    padding: 20px 14px 48px;
  }
}

@media (max-width: 600px) {
  .app-head {
    padding: 6px 10px;
    gap: 6px;
  }

  .brand-name {
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    clip: rect(0 0 0 0);
    white-space: nowrap;
  }

  .app-nav {
    gap: 2px;
  }

  .app-nav a {
    padding: 4px 9px;
    min-height: 44px;
    font-size: 0.95rem;
  }

  .app-nav .ic-wrap {
    display: none;
  }

  .toolbar .btn .btn-label {
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    clip: rect(0 0 0 0);
    white-space: nowrap;
  }

  .toolbar .btn {
    position: relative;
    min-width: 46px;
    padding: 6px 10px;
  }

  .toolbar .btn[title^='Wczytaj'] .btn-label {
    position: static;
    width: auto;
    height: auto;
    clip: auto;
  }

  .transport {
    gap: 6px;
  }

  .transport .btn {
    flex: 1 1 auto;
    padding: 6px 9px;
  }

  .speed {
    flex: 1 1 100%;
    margin-left: 0;
    order: 5;
  }

  .speed input[type='range'] {
    flex: 1;
    width: auto;
    height: 36px;
  }

  .transport > .icon-btn {
    display: none;
  }

  .ref-card {
    grid-template-columns: 1fr;
  }

  .ref-card-thumb {
    justify-self: start;
  }

  .ch-grid {
    grid-template-columns: 1fr;
  }

  .ch-thumb .thumb {
    width: 88px;
    height: 88px;
  }

  .share-row {
    flex-direction: column;
  }

  .readout {
    font-size: 0.72rem;
  }

  #toast {
    width: calc(100vw - 16px);
    bottom: 8px;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.001ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.001ms !important;
    scroll-behavior: auto !important;
  }
}

@media (forced-colors: active) {
  .seg[aria-pressed='true'] {
    outline: 2px solid Highlight;
  }

  .ed-input {
    color: CanvasText;
    -webkit-text-fill-color: CanvasText;
  }

  .ed-hl {
    visibility: hidden;
  }
}

@media print {
  .app-head,
  .toolbar,
  .transport,
  .stage-tools,
  #toast {
    display: none !important;
  }
}

tool_use_result.content:
/* Logomocja: a school-notebook look. Cream graph paper by day, a night classroom after dark. */
:root {
  color-scheme: light;
  --bg: #f6f1e7;
  --bg-line: rgba(60, 110, 140, 0.07);
  --surface: #fffdf8;
  --surface-2: #efe8d9;
  --ink: #1d2b3f;
  --muted: #566274;
  --line: #d6cbb4;
  --line-strong: #b9ac90;
  --accent: #16866a;
  --accent-strong: #0f6e57;
  --accent-ink: #ffffff;
  --accent-soft: #dcefe8;
  --copper: #c1763d;
  --copper-text: #96531f;
  --error: #b3261e;
  --error-bg: #fbe9e6;
  --ok: #0f6e57;
  --ok-bg: #dff1e9;
  --focus: #1f5fa8;
  --shadow: 0 1px 2px rgba(40, 30, 10, 0.08), 0 6px 18px rgba(40, 30, 10, 0.07);

  --cv-paper: #fffdf8;
  --cv-grid: #e7eff0;
  --cv-grid-strong: #cfdfe2;
  --cv-axis: #8aa0aa;
  --cv-text: #5b6b78;
  --cv-ghost: rgba(40, 60, 90, 0.17);
  --cv-shell: #2f9e7d;
  --cv-shell-edge: #0e4f3e;
  --cv-skin: #9bd4a5;
  --cv-x: #c2504a;
  --cv-y: #3d8f4f;
  --cv-z: #3a6fc0;
  --ghost-solid: #c5ccd3;

  --logo-skin: #9bd4a5;
  --logo-shell: #16866a;
  --logo-line: #f6f1e7;

  --t-cmd: #0f6e57;
  --t-ctl: #7a3fa0;
  --t-num: #a84d14;
  --t-str: #7a5b00;
  --t-com: #717b8a;
  --t-var: #1f5fa8;
  --t-proc: #a2336a;
  --t-br: #1d2b3f;
  --t-op: #566274;
  --exec-band: rgba(193, 118, 61, 0.2);
  --err-band: rgba(179, 38, 30, 0.1);

  --font-ui: system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
  --font-head: 'Iowan Old Style', 'Palatino Linotype', Palatino, 'Book Antiqua', Georgia, serif;
  --font-mono: ui-monospace, 'SF Mono', 'Cascadia Code', Menlo, Consolas, 'DejaVu Sans Mono', 'Liberation Mono', monospace;
  --radius: 12px;
  --ed-pad: 12px;
  --ed-pad-x: 12px;
  --ed-lh: 24px;
  --ed-size: 15px;
}

:root[data-theme='dark'] {
  color-scheme: dark;
  --bg: #131a24;
  --bg-line: rgba(140, 180, 220, 0.045);
  --surface: #1b2431;
  --surface-2: #243042;
  --ink: #ebe8df;
  --muted: #a6b0bd;
  --line: #334154;
  --line-strong: #4a5b72;
  --accent: #3fc6a0;
  --accent-strong: #6fdcbb;
  --accent-ink: #08201a;
  --accent-soft: #1d3b39;
  --copper: #e09a5f;
  --copper-text: #f0b07a;
  --error: #ff9488;
  --error-bg: #3b1f22;
  --ok: #6fdcbb;
  --ok-bg: #173630;
  --focus: #ffd166;
  --shadow: 0 1px 2px rgba(0, 0, 0, 0.35), 0 8px 22px rgba(0, 0, 0, 0.3);

  --cv-paper: #18212d;
  --cv-grid: #202b39;
  --cv-grid-strong: #2b394a;
  --cv-axis: #5b6f86;
  --cv-text: #9aa7b6;
  --cv-ghost: rgba(190, 215, 255, 0.2);
  --cv-shell: #3fc6a0;
  --cv-shell-edge: #0b3a30;
  --cv-skin: #a6e0b4;
  --cv-x: #f0766f;
  --cv-y: #62c276;
  --cv-z: #6ea3f0;
  --ghost-solid: #46566b;

  --logo-shell: #3fc6a0;
  --logo-line: #131a24;

  --t-cmd: #62d8b5;
  --t-ctl: #cba2f2;
  --t-num: #f2a66f;
  --t-str: #e6cf6a;
  --t-com: #8491a2;
  --t-var: #84bbf5;
  --t-proc: #f296bd;
  --t-br: #ebe8df;
  --t-op: #a6b0bd;
  --exec-band: rgba(224, 154, 95, 0.24);
  --err-band: rgba(255, 148, 136, 0.13);
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

[hidden] {
  display: none !important;
}

html {
  -webkit-text-size-adjust: 100%;
  text-size-adjust: 100%;
}

body {
  margin: 0;
  min-height: 100vh;
  min-height: 100dvh;
  background-color: var(--bg);
  background-image: linear-gradient(var(--bg-line) 1px, transparent 1px), linear-gradient(90deg, var(--bg-line) 1px, transparent 1px);
  background-size: 24px 24px;
  color: var(--ink);
  font: 16px/1.5 var(--font-ui);
}

h1,
h2,
h3 {
  font-family: var(--font-head);
  line-height: 1.2;
  margin: 0;
  font-weight: 700;
  letter-spacing: 0.005em;
}

p {
  margin: 0;
}

a {
  color: var(--accent-strong);
  text-underline-offset: 0.18em;
}

kbd {
  font: 600 0.85em var(--font-mono);
  padding: 2px 6px;
  border: 1px solid var(--line-strong);
  border-bottom-width: 2px;
  border-radius: 6px;
  background: var(--surface);
  white-space: nowrap;
}

code,
.code {
  font-family: var(--font-mono);
}

:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.visually-hidden {
  position: absolute !important;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}

.muted {
  color: var(--muted);
}

.noscript {
  max-width: 40rem;
  margin: 3rem auto;
  padding: 1.5rem;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius);
}

/* ------------------------------------------------------------ icons and buttons */

.ic-wrap {
  display: inline-flex;
  flex: none;
}

.ic {
  display: block;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  min-height: 40px;
  padding: 6px 13px;
  border: 1.5px solid var(--line-strong);
  border-radius: 10px;
  background: var(--surface);
  color: var(--ink);
  font: 600 0.94rem/1.2 var(--font-ui);
  text-decoration: none;
  cursor: pointer;
  white-space: nowrap;
  transition: background-color 0.12s, border-color 0.12s, transform 0.06s;
}

.btn:hover:not(:disabled) {
  background: var(--surface-2);
  border-color: var(--ink);
}

.btn:active:not(:disabled) {
  transform: translateY(1px);
}

.btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.btn-primary {
  background: var(--accent);
  border-color: var(--accent);
  color: var(--accent-ink);
}

.btn-primary:hover:not(:disabled) {
  background: var(--accent-strong);
  border-color: var(--accent-strong);
}

.btn-small {
  min-height: 34px;
  padding: 4px 10px;
  font-size: 0.88rem;
}

.btn-small .ic {
  width: 16px;
  height: 16px;
}

.icon-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  flex: none;
  padding: 0;
  border: 1.5px solid transparent;
  border-radius: 10px;
  background: transparent;
  color: var(--ink);
  cursor: pointer;
}

.icon-btn:hover {
  background: var(--surface-2);
  border-color: var(--line-strong);
}

.badge {
  display: inline-block;
  padding: 1px 7px;
  border-radius: 999px;
  background: var(--accent-soft);
  color: var(--accent-strong);
  font: 700 0.72rem/1.5 var(--font-ui);
  letter-spacing: 0.04em;
  vertical-align: middle;
}

.segmented {
  display: inline-flex;
  border: 1.5px solid var(--line-strong);
  border-radius: 10px;
  background: var(--surface);
  padding: 2px;
  gap: 2px;
}

.seg {
  min-width: 46px;
  min-height: 33px;
  padding: 2px 10px;
  border: 0;
  border-radius: 7px;
  background: transparent;
  color: var(--ink);
  font: 700 0.94rem var(--font-ui);
  cursor: pointer;
}

.seg:hover {
  background: var(--surface-2);
}

.seg[aria-pressed='true'] {
  background: var(--ink);
  color: var(--bg);
}

/* ------------------------------------------------------------ shell */

#app {
  display: flex;
  flex-direction: column;
  min-height: 100vh;
  min-height: 100dvh;
}

.skip-link {
  position: absolute;
  left: 8px;
  top: -60px;
  z-index: 50;
  padding: 8px 14px;
  background: var(--ink);
  color: var(--bg);
  border-radius: 8px;
  font-weight: 600;
}

.skip-link:focus {
  top: 8px;
}

.app-head {
  display: flex;
  align-items: center;
  gap: 8px 18px;
  padding: 8px 16px;
  background: var(--surface);
  border-bottom: 1.5px solid var(--line);
  position: relative;
  z-index: 5;
}

.app-head::after {
  /* the red margin line of a school notebook */
  content: '';
  position: absolute;
  left: 0;
  right: 0;
  bottom: -5px;
  height: 1.5px;
  background: var(--copper);
  opacity: 0.55;
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: var(--ink);
  text-decoration: none;
  border-radius: 8px;
}

.brand-logo {
  display: inline-flex;
}

.brand-name {
  font: 700 1.35rem/1 var(--font-head);
  letter-spacing: 0.01em;
}

.app-nav {
  display: flex;
  gap: 4px;
  margin-left: auto;
}

.app-nav a {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-height: 40px;
  padding: 4px 12px;
  border-radius: 10px;
  color: var(--ink);
  font-weight: 600;
  text-decoration: none;
  border-bottom: 3px solid transparent;
}

.app-nav a:hover {
  background: var(--surface-2);
}

.app-nav a[aria-current='page'] {
  background: var(--accent-soft);
  color: var(--accent-strong);
  border-bottom-color: var(--accent);
}

.app-nav .ic {
  width: 18px;
  height: 18px;
}

main {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
  outline: none;
}

.page {
  width: 100%;
  max-width: 1120px;
  margin: 0 auto;
  padding: 28px 20px 56px;
}

.page-head {
  margin-bottom: 22px;
  max-width: 46rem;
}

.page-head h1 {
  font-size: clamp(1.8rem, 4vw, 2.4rem);
  margin-bottom: 8px;
}

.page-head h1:focus {
  outline: none;
}

.page-head p {
  color: var(--muted);
  font-size: 1.05rem;
}

/* ------------------------------------------------------------ studio */

.studio {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 16px;
}

.studio-grid {
  flex: 1;
  min-height: 0;
  display: grid;
  grid-template-columns: minmax(340px, 5fr) 7fr;
  gap: 14px;
}

.pane {
  display: flex;
  flex-direction: column;
  gap: 10px;
  min-width: 0;
  min-height: 0;
}

.toolbar,
.transport {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
}

.toolbar-gap {
  flex: 1;
}

.messages {
  display: flex;
  flex-direction: column;
  gap: 6px;
  min-height: 1.5em;
}

.status {
  color: var(--muted);
  font-size: 0.92rem;
  display: flex;
  align-items: baseline;
  gap: 8px;
}

.status::before {
  content: '';
  flex: none;
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: var(--line-strong);
  transform: translateY(-1px);
}

.studio[data-state='running'] .status::before {
  background: var(--accent);
  animation: pulse 0.9s ease-in-out infinite;
}

.studio[data-state='paused'] .status::before {
  background: var(--copper);
}

.studio[data-state='done'] .status::before {
  background: var(--accent);
}

.studio[data-state='error'] .status::before {
  background: var(--error);
}

@keyframes pulse {
  50% {
    opacity: 0.3;
  }
}

.error-box {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 8px 14px;
  padding: 9px 12px;
  border: 1.5px solid var(--error);
  border-left-width: 6px;
  border-radius: 10px;
  background: var(--error-bg);
  color: var(--ink);
  font-size: 0.95rem;
}

.error-box strong {
  color: var(--error);
}

/* editor */

.editor {
  flex: 1;
  min-height: 180px;
  display: flex;
  position: relative;
  overflow: hidden;
  border: 1.5px solid var(--line-strong);
  border-radius: var(--radius);
  background: var(--surface);
  box-shadow: var(--shadow);
  font: var(--ed-size) / var(--ed-lh) var(--font-mono);
}

.editor:focus-within {
  border-color: var(--focus);
  outline: 3px solid var(--focus);
  outline-offset: 1px;
}

.ed-gutter {
  flex: none;
  min-width: 3.1em;
  overflow: hidden;
  padding: var(--ed-pad) 0;
  background: var(--surface-2);
  border-right: 1.5px solid var(--copper);
  color: var(--muted);
  text-align: right;
  user-select: none;
  -webkit-user-select: none;
}

.ed-ln {
  height: var(--ed-lh);
  line-height: var(--ed-lh);
  padding: 0 8px 0 10px;
  font-size: 0.85em;
  font-variant-numeric: tabular-nums;
}

.ed-ln.exec {
  background: var(--copper);
  color: #fff;
  font-weight: 700;
}

:root[data-theme='dark'] .ed-ln.exec {
  color: #1a1206;
}

.ed-ln.err {
  background: var(--error);
  color: var(--surface);
  font-weight: 700;
}

.ed-main {
  position: relative;
  flex: 1;
  min-width: 0;
  overflow: hidden;
}

.ed-layers {
  position: absolute;
  top: 0;
  left: 0;
  min-width: 100%;
  pointer-events: none;
  will-change: transform;
}

.ed-hl,
.ed-input {
  margin: 0;
  padding: var(--ed-pad) var(--ed-pad-x);
  border: 0;
  font: inherit;
  letter-spacing: 0;
  white-space: pre;
  tab-size: 2;
  -moz-tab-size: 2;
  font-variant-ligatures: none;
}

.ed-hl {
  position: relative;
  color: var(--ink);
}

.ed-input {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  resize: none;
  overflow: auto;
  background: transparent;
  color: transparent;
  caret-color: var(--ink);
  outline: none;
  border-radius: 0;
  -webkit-text-fill-color: transparent;
}

.ed-input::selection {
  background: rgba(31, 95, 168, 0.28);
}

:root[data-theme='dark'] .ed-input::selection {
  background: rgba(132, 187, 245, 0.32);
}

.ed-band {
  position: absolute;
  left: -2000px;
  width: 200000px;
  height: var(--ed-lh);
}

.ed-band.exec {
  background: var(--exec-band);
}

.ed-band.err {
  background: var(--err-band);
}

.ed-squiggle {
  position: absolute;
  height: 5px;
  background: repeating-linear-gradient(135deg, var(--error) 0 2px, transparent 2px 4px);
  border-radius: 2px;
}

.ed-lens {
  color: var(--error);
  font-style: italic;
  font-family: var(--font-ui);
  font-size: 0.9em;
}

.t-com {
  color: var(--t-com);
  font-style: italic;
}
.t-str {
  color: var(--t-str);
}
.t-var {
  color: var(--t-var);
}
.t-def,
.t-ctl,
.t-rep {
  color: var(--t-ctl);
  font-weight: 600;
}
.t-cmd {
  color: var(--t-cmd);
  font-weight: 600;
}
.t-proc {
  color: var(--t-proc);
}
.t-name {
  color: var(--ink);
}
.t-num {
  color: var(--t-num);
}
.t-br,
.t-par {
  color: var(--t-br);
  font-weight: 700;
}
.t-op {
  color: var(--t-op);
}

/* stage */

.stage {
  position: relative;
  flex: 1;
  min-height: 0;
  border: 1.5px solid var(--line-strong);
  border-radius: var(--radius);
  background: var(--cv-paper);
  box-shadow: var(--shadow);
  overflow: hidden;
}

.stage-canvas {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  touch-action: none;
  cursor: grab;
  border-radius: calc(var(--radius) - 2px);
}

.stage-canvas.dragging {
  cursor: grabbing;
}

.stage-canvas:focus-visible {
  outline-offset: -4px;
}

.stage-tools {
  position: absolute;
  top: 8px;
  right: 8px;
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 4px;
  border: 1.5px solid var(--line);
  border-radius: 12px;
  background: color-mix(in srgb, var(--surface) 92%, transparent);
}

.stage-tools .icon-btn {
  width: 38px;
  height: 38px;
}

.readout {
  position: absolute;
  left: 8px;
  bottom: 8px;
  max-width: calc(100% - 16px);
  padding: 3px 9px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: color-mix(in srgb, var(--surface) 90%, transparent);
  color: var(--muted);
  font: 0.78rem/1.5 var(--font-mono);
  white-space: pre;
  overflow: hidden;
  text-overflow: ellipsis;
  pointer-events: none;
}

.stage-note {
  position: absolute;
  left: 8px;
  top: 8px;
  right: 64px;
  padding: 6px 10px;
  border-radius: 8px;
  background: var(--surface-2);
  font-size: 0.9rem;
}

.speed {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-left: auto;
  font-size: 0.92rem;
  font-weight: 600;
}

.speed input[type='range'] {
  width: 120px;
  height: 28px;
  accent-color: var(--accent);
  cursor: pointer;
}

.speed-out {
  min-width: 7.2em;
  color: var(--muted);
  font-weight: 500;
}

/* challenge bar */

.challenge-bar {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 10px 24px;
  align-items: center;
  padding: 12px 16px;
  border: 1.5px solid var(--line-strong);
  border-left: 6px solid var(--copper);
  border-radius: var(--radius);
  background: var(--surface);
  box-shadow: var(--shadow);
}

.ch-kicker {
  color: var(--copper-text);
  font: 700 0.76rem/1.4 var(--font-ui);
  letter-spacing: 0.09em;
  text-transform: uppercase;
}

.challenge-bar h2 {
  font-size: 1.3rem;
  margin: 1px 0 4px;
}

.ch-text {
  max-width: 62rem;
}

.ch-hint {
  margin-top: 4px;
  color: var(--muted);
}

.ch-hint summary {
  cursor: pointer;
  font-weight: 600;
  width: fit-content;
  border-radius: 6px;
}

.ch-side {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 8px;
  max-width: 30rem;
}

.ch-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  justify-content: flex-end;
}

.ch-result {
  display: flex;
  align-items: flex-start;
  gap: 6px;
  font-weight: 600;
  font-size: 0.95rem;
}

.ch-result:empty {
  display: none;
}

.ch-result.pass,
.ch-result.fail {
  padding: 7px 11px;
  border-radius: 10px;
  border: 1.5px solid;
}

.ch-result.pass {
  background: var(--ok-bg);
  border-color: var(--ok);
  color: var(--ink);
}

.ch-result.pass .ic-wrap,
.ch-result .ic-wrap {
  color: var(--ok);
}

.ch-result.fail {
  background: var(--error-bg);
  border-color: var(--error);
}

.ch-result.fail .ic-wrap {
  color: var(--error);
}

/* ------------------------------------------------------------ challenges page */

.ch-progress {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px 14px;
  margin-top: 14px;
  font-weight: 600;
  color: var(--ink);
}

.ch-progress progress {
  width: min(260px, 100%);
  height: 12px;
  accent-color: var(--accent);
}

.ch-grid {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(320px, 1fr));
  gap: 14px;
}

.ch-card {
  display: flex;
  gap: 14px;
  height: 100%;
  padding: 12px;
  border: 1.5px solid var(--line-strong);
  border-radius: var(--radius);
  background: var(--surface);
  color: var(--ink);
  text-decoration: none;
  box-shadow: var(--shadow);
  transition: transform 0.12s, border-color 0.12s;
}

.ch-card:hover {
  border-color: var(--ink);
  transform: translateY(-2px);
}

.ch-card.solved {
  border-color: var(--accent);
}

.ch-thumb,
.ex-thumb,
.ref-card-thumb {
  display: flex;
  align-items: center;
  justify-content: center;
  flex: none;
  border: 1px solid var(--line);
  border-radius: 10px;
  background-color: var(--cv-paper);
  background-image: linear-gradient(var(--cv-grid) 1px, transparent 1px), linear-gradient(90deg, var(--cv-grid) 1px, transparent 1px);
  background-size: 12px 12px;
}

.thumb {
  display: block;
  max-width: 100%;
  height: auto;
}

:root[data-theme='dark'] .thumb {
  filter: brightness(1.35) saturate(1.05);
}

.ch-thumb .thumb {
  width: 108px;
  height: 108px;
}

.ch-card-text {
  display: flex;
  flex-direction: column;
  gap: 3px;
  min-width: 0;
}

.ch-card-title {
  font: 700 1.2rem/1.2 var(--font-head);
}

.ch-meta {
  color: var(--muted);
  font-size: 0.85rem;
}

.ch-card-task {
  font-size: 0.92rem;
  color: var(--muted);
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.ch-state {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  margin-top: auto;
  padding-top: 4px;
  font-weight: 700;
  font-size: 0.88rem;
  color: var(--muted);
}

.ch-state.ok {
  color: var(--ok);
}

.ch-state .ic {
  width: 17px;
  height: 17px;
}

/* ------------------------------------------------------------ reference */

.ref-layout {
  display: grid;
  grid-template-columns: 220px minmax(0, 1fr);
  gap: 32px;
  align-items: start;
}

.ref-toc {
  position: sticky;
  top: 16px;
  max-height: calc(100vh - 32px);
  overflow: auto;
  padding: 14px 16px;
  border: 1.5px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface);
}

.ref-toc h2 {
  font-size: 1rem;
  margin-bottom: 8px;
}

.ref-toc ul {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.ref-toc a {
  display: block;
  padding: 5px 8px;
  border-radius: 8px;
  color: var(--ink);
  text-decoration: none;
  font-size: 0.95rem;
}

.ref-toc a:hover {
  background: var(--surface-2);
}

.ref-section {
  margin-bottom: 40px;
  scroll-margin-top: 16px;
}

.ref-section:focus {
  outline: none;
}

.ref-section > h2 {
  font-size: 1.55rem;
  padding-bottom: 6px;
  margin-bottom: 10px;
  border-bottom: 2px solid var(--copper);
}

.ref-intro {
  margin-bottom: 14px;
  max-width: 46rem;
}

.ref-extra {
  margin: 14px 0;
  max-width: 46rem;
}

.ref-extra p,
.ref-extra ul,
.ref-extra pre {
  margin: 0 0 10px;
}

.ref-extra ul {
  padding-left: 1.3em;
}

.ref-extra li {
  margin-bottom: 4px;
}

.ref-card {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 152px;
  gap: 16px;
  align-items: start;
  padding: 14px 16px;
  margin-bottom: 12px;
  border: 1.5px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface);
}

.ref-card h3 {
  font: 700 1.02rem/1.4 var(--font-mono);
  color: var(--t-cmd);
  margin-bottom: 2px;
  overflow-wrap: anywhere;
}

.ref-card-text > p {
  margin-bottom: 8px;
}

.ref-arg {
  color: var(--muted);
  font-size: 0.9rem;
}

.ref-arg span {
  font-weight: 600;
}

.code,
.ref-extra pre {
  margin: 0 0 10px;
  padding: 9px 12px;
  border: 1px solid var(--line);
  border-left: 3px solid var(--copper);
  border-radius: 8px;
  background: var(--bg);
  font: 0.9rem/1.55 var(--font-mono);
  overflow-x: auto;
  white-space: pre;
}

.ref-extra code,
.ref-intro code,
.ref-card-text p code,
.ref-table code {
  padding: 1px 5px;
  border-radius: 5px;
  background: var(--surface-2);
  font-size: 0.92em;
}

.ref-table {
  width: 100%;
  max-width: 46rem;
  border-collapse: collapse;
  margin: 10px 0 14px;
  background: var(--surface);
  border: 1.5px solid var(--line);
  border-radius: 10px;
  font-size: 0.95rem;
}

.ref-table caption {
  text-align: left;
  font-weight: 700;
  padding: 0 0 6px;
}

.ref-table th,
.ref-table td {
  padding: 8px 12px;
  border-bottom: 1px solid var(--line);
  text-align: left;
  vertical-align: top;
}

.ref-table th {
  font-weight: 600;
}

.ref-table tr:last-child th,
.ref-table tr:last-child td {
  border-bottom: 0;
}

.ref-table.keys th {
  white-space: nowrap;
  width: 1%;
}

/* ------------------------------------------------------------ dialogs and toast */

.dialog {
  width: min(540px, calc(100vw - 24px));
  max-height: calc(100dvh - 24px);
  padding: 0;
  border: 1.5px solid var(--line-strong);
  border-radius: 16px;
  background: var(--surface);
  color: var(--ink);
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.35);
  overflow: hidden;
}

.dialog[open] {
  display: flex;
  flex-direction: column;
}

.dialog.wide {
  width: min(940px, calc(100vw - 24px));
}

.dialog::backdrop {
  background: rgba(15, 22, 34, 0.55);
}

.dialog-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 12px 12px 12px 20px;
  border-bottom: 1.5px solid var(--line);
}

.dialog-head h2 {
  font-size: 1.3rem;
}

.dialog-body {
  padding: 16px 20px 20px;
  overflow: auto;
}

.dialog-body > div > p {
  margin-bottom: 12px;
}

.dialog-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 16px;
}

.share-row {
  display: flex;
  gap: 8px;
  margin-bottom: 12px;
}

.share-url {
  flex: 1;
  min-width: 0;
  min-height: 40px;
  padding: 6px 10px;
  border: 1.5px solid var(--line-strong);
  border-radius: 10px;
  background: var(--bg);
  color: var(--ink);
  font: 0.88rem var(--font-mono);
}

.ex-groups section + section {
  margin-top: 22px;
}

.ex-groups h3 {
  font-size: 1.1rem;
  margin-bottom: 10px;
}

.ex-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(150px, 1fr));
  gap: 10px;
}

.ex-card {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 10px;
  border: 1.5px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface);
  color: var(--ink);
  font: inherit;
  text-align: left;
  cursor: pointer;
}

.ex-card:hover {
  border-color: var(--ink);
  background: var(--surface-2);
}

.ex-thumb {
  width: 100%;
  aspect-ratio: 1.25;
}

.ex-thumb .thumb {
  width: auto;
  height: 100%;
}

.ex-name {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
  font-weight: 700;
}

.ex-blurb {
  font-size: 0.85rem;
  color: var(--muted);
  line-height: 1.35;
}

#toast {
  position: fixed;
  left: 50%;
  bottom: 18px;
  z-index: 100;
  display: flex;
  align-items: center;
  gap: 10px;
  width: max-content;
  max-width: calc(100vw - 24px);
  padding: 8px 8px 8px 16px;
  border-radius: 12px;
  background: var(--ink);
  color: var(--bg);
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.3);
  font-size: 0.95rem;
  transform: translate(-50%, 20px);
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.18s, transform 0.18s, visibility 0.18s;
}

#toast.show {
  transform: translate(-50%, 0);
  opacity: 1;
  visibility: visible;
}

#toast .btn {
  background: var(--bg);
  color: var(--ink);
  border-color: var(--bg);
}

#toast .icon-btn {
  color: var(--bg);
  width: 34px;
  height: 34px;
}

#toast .icon-btn:hover {
  background: rgba(127, 127, 127, 0.35);
}

#toast :focus-visible {
  outline-color: var(--bg);
}

/* ------------------------------------------------------------ desktop: the studio fills the window */

@media (min-width: 900px) {
  body[data-page='studio'] {
    height: 100vh;
    height: 100dvh;
    overflow: hidden;
  }

  body[data-page='studio'] #app {
    height: 100%;
    min-height: 0;
  }
}

/* ------------------------------------------------------------ phones and narrow windows */

@media (max-width: 899.98px) {
  :root {
    --ed-size: 16px;
  }

  .studio {
    padding: 10px;
    gap: 10px;
    flex: none;
  }

  .studio-grid {
    display: flex;
    flex-direction: column;
    gap: 12px;
  }

  .pane-stage {
    order: -1;
  }

  .stage {
    flex: none;
    height: 46vh;
    height: 46dvh;
    min-height: 240px;
  }

  .editor {
    flex: none;
    height: clamp(240px, 52dvh, 520px);
  }

  .btn,
  .icon-btn {
    min-height: 44px;
  }

  .icon-btn {
    width: 44px;
    height: 44px;
  }

  .stage-tools .icon-btn {
    width: 40px;
    height: 40px;
    min-height: 40px;
  }

  .seg {
    min-height: 38px;
  }

  .challenge-bar {
    grid-template-columns: 1fr;
  }

  .ch-side {
    align-items: stretch;
    max-width: none;
  }

  .ch-actions {
    justify-content: flex-start;
  }

  .ref-layout {
    grid-template-columns: 1fr;
    gap: 20px;
  }

  .ref-toc {
    position: static;
    max-height: none;
  }

  .ref-toc ul {
    flex-direction: row;
    flex-wrap: wrap;
    gap: 6px;
  }

  .ref-toc a {
    border: 1px solid var(--line);
    padding: 8px 12px;
  }

  .page {
    padding: 20px 14px 48px;
  }
}

@media (max-width: 600px) {
  .app-head {
    padding: 6px 10px;
    gap: 6px;
  }

  .brand-name {
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    clip: rect(0 0 0 0);
    white-space: nowrap;
  }

  .app-nav {
    gap: 2px;
  }

  .app-nav a {
    padding: 4px 9px;
    min-height: 44px;
    font-size: 0.95rem;
  }

  .app-nav .ic-wrap {
    display: none;
  }

  .toolbar .btn .btn-label {
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    clip: rect(0 0 0 0);
    white-space: nowrap;
  }

  .toolbar .btn {
    position: relative;
    min-width: 46px;
    padding: 6px 10px;
  }

  .toolbar .btn[title^='Wczytaj'] .btn-label {
    position: static;
    width: auto;
    height: auto;
    clip: auto;
  }

  .transport {
    gap: 6px;
  }

  .transport .btn {
    flex: 1 1 auto;
    padding: 6px 9px;
  }

  .speed {
    flex: 1 1 100%;
    margin-left: 0;
    order: 5;
  }

  .speed input[type='range'] {
    flex: 1;
    width: auto;
    height: 36px;
  }

  .transport > .icon-btn {
    display: none;
  }

  .ref-card {
    grid-template-columns: 1fr;
  }

  .ref-card-thumb {
    justify-self: start;
  }

  .ch-grid {
    grid-template-columns: 1fr;
  }

  .ch-thumb .thumb {
    width: 88px;
    height: 88px;
  }

  .share-row {
    flex-direction: column;
  }

  .readout {
    font-size: 0.72rem;
  }

  #toast {
    width: calc(100vw - 16px);
    bottom: 8px;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.001ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.001ms !important;
    scroll-behavior: auto !important;
  }
}

@media (forced-colors: active) {
  .seg[aria-pressed='true'] {
    outline: 2px solid Highlight;
  }

  .ed-input {
    color: CanvasText;
    -webkit-text-fill-color: CanvasText;
  }

  .ed-hl {
    visibility: hidden;
  }
}

@media print {
  .app-head,
  .toolbar,
  .transport,
  .stage-tools,
  #toast {
    display: none !important;
  }
}

