// Builds the static site into dist/. Usage: bun run build  (env BASE_PATH, default "/").
import { createHash } from 'node:crypto';
import { mkdir, readFile, rm, writeFile } from 'node:fs/promises';
import { join } from 'node:path';

const root = import.meta.dir;
const out = join(root, 'dist');
const pkg = JSON.parse(await readFile(join(root, 'package.json'), 'utf8')) as { version: string };

/** "/x/y" → "/x/y/"; empty → "/". */
function normBase(raw: string | undefined): string {
  let b = (raw ?? '/').trim();
  if (b === '') b = '/';
  if (!b.startsWith('/')) b = '/' + b;
  if (!b.endsWith('/')) b += '/';
  return b.replace(/\/{2,}/g, '/');
}

const base = normBase(process.env.BASE_PATH);
// At the root the assets are linked relatively, so the folder also works when
// it is opened from any other place; under a sub-path the links carry the
// whole prefix, so the site works at that address with or without the final slash.
const prefix = base === '/' ? './' : base;

const hash = (data: string | Uint8Array) => createHash('sha256').update(data).digest('hex').slice(0, 10);

await rm(out, { recursive: true, force: true });
await mkdir(join(out, 'assets'), { recursive: true });

const result = await Bun.build({
  entrypoints: [join(root, 'src/ui/main.ts')],
  target: 'browser',
  format: 'iife',
  minify: true,
  define: { __VERSION__: JSON.stringify(pkg.version) },
});
if (!result.success) {
  for (const log of result.logs) console.error(log);
  process.exit(1);
}
const js = await result.outputs[0].text();
const jsName = `app.${hash(js)}.js`;
await writeFile(join(out, 'assets', jsName), js);

const css = (await readFile(join(root, 'src/styles.css'), 'utf8'))
  .replace(/\/\*[\s\S]*?\*\//g, '')
  .replace(/\s*\n\s*/g, '\n')
  .replace(/\n+/g, '\n')
  .trim();
const cssName = `app.${hash(css)}.css`;
await writeFile(join(out, 'assets', cssName), css);

const iconSvg =
  '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 48 48"><g transform="rotate(38 24 24)" fill="#9bd4a5">' +
  '<ellipse cx="24" cy="9.5" rx="5" ry="5.5"/><ellipse cx="11" cy="15" rx="4" ry="5" transform="rotate(-40 11 15)"/>' +
  '<ellipse cx="37" cy="15" rx="4" ry="5" transform="rotate(40 37 15)"/><ellipse cx="11.5" cy="35" rx="4" ry="5" transform="rotate(40 11.5 35)"/>' +
  '<ellipse cx="36.5" cy="35" rx="4" ry="5" transform="rotate(-40 36.5 35)"/><ellipse cx="24" cy="26" rx="13" ry="15" fill="#16866a"/>' +
  '<path d="M24 16l7 4.5v9L24 34l-7-4.500v-9z" fill="none" stroke="#f6f1e7" stroke-width="1.8"/></g></svg>';
await writeFile(join(out, 'assets', 'icon.svg'), iconSvg);

const html = (await readFile(join(root, 'src/index.html'), 'utf8'))
  .replace('%BASE%', base)
  .replace('%ICON%', `${prefix}assets/icon.svg`)
  .replace('%CSS%', `${prefix}assets/${cssName}`)
  .replace('%JS%', `${prefix}assets/${jsName}`);
await writeFile(join(out, 'index.html'), html);

const kb = (n: number) => (n / 1024).toFixed(1) + ' kB';
console.log(`Logomocja ${pkg.version} → dist/  (BASE_PATH=${base})`);
console.log(`  index.html          ${kb(html.length)}`);
console.log(`  assets/${jsName}   ${kb(js.length)}`);
console.log(`  assets/${cssName}  ${kb(css.length)}`);

