// Tiny static server for looking at dist/ locally. Not part of the built site.
// Usage: bun run serve   (env PORT, default 4173; env BASE_PATH mounts dist/ under that prefix)
import { join, normalize } from 'node:path';

const dist = join(import.meta.dir, 'dist');
let base = process.env.BASE_PATH ?? '/';
if (!base.startsWith('/')) base = '/' + base;
if (!base.endsWith('/')) base += '/';
const port = Number(process.env.PORT) || 4173;

const server = Bun.serve({
  port,
  async fetch(req) {
    const url = new URL(req.url);
    let path = decodeURIComponent(url.pathname);
    if (path + '/' === base) path = base;
    if (!path.startsWith(base)) return new Response('Not found', { status: 404 });
    let rel = normalize(path.slice(base.length)).replace(/^(\.\.[/\\])+/, '');
    if (rel === '' || rel === '.' || rel.endsWith('/')) rel = join(rel, 'index.html');
    const file = Bun.file(join(dist, rel));
    if (!(await file.exists())) return new Response('Not found', { status: 404 });
    return new Response(file);
  },
});

console.log(`Logomocja: http://localhost:${server.port}${base}`);

